// Shared UI primitives — form fields, buttons, modal scaffolding.
const { useState, useRef, useEffect, useId, useCallback } = React;

// ─────────── Button ───────────
function Button({ variant = "primary", size = "md", children, disabled, onClick, type = "button", style, ...rest }) {
  const [pressed, setPressed] = useState(false);
  const base = {
    display: "inline-flex", alignItems: "center", justifyContent: "center",
    gap: 8, fontWeight: 700, letterSpacing: ".01em",
    border: "1px solid transparent", borderRadius: 4,
    padding: size === "sm" ? "8px 14px" : size === "lg" ? "14px 28px" : "11px 22px",
    fontSize: size === "sm" ? 12 : 13,
    transition: "background .12s ease, border-color .12s ease, color .12s ease, box-shadow .12s ease, transform .1s ease",
    cursor: disabled ? "not-allowed" : "pointer",
    whiteSpace: "nowrap",
    transform: (pressed && !disabled) ? "scale(.972)" : "scale(1)",
  };
  const styles = {
    primary: { background: disabled ? "#d4d4d8" : "#0e0e10", color: "#fff", borderColor: disabled ? "#d4d4d8" : "#0e0e10" },
    secondary: { background: "#fff", color: "#0e0e10", borderColor: "#0e0e10" },
    ghost: { background: "transparent", color: disabled ? "#9a9aa1" : "#0e0e10", borderColor: "transparent" },
    danger: { background: "#fff", color: "#b81d14", borderColor: "#b81d14" },
  }[variant];
  return (
    <button type={type} disabled={disabled} onClick={onClick}
      onMouseDown={() => !disabled && setPressed(true)}
      onMouseUp={() => setPressed(false)}
      onMouseLeave={() => setPressed(false)}
      style={{ ...base, ...styles, ...style }} {...rest}>
      {children}
    </button>
  );
}

// ─────────── Floating-label text input ───────────
function TextField({ label, value, onChange, error, prefix, suffix, type = "text", placeholder, autoFocus, name, onBlur, readOnly, style }) {
  const id = useId();
  const [focus, setFocus] = useState(false);
  const filled = value != null && String(value).length > 0;
  const float = focus || filled || placeholder;
  return (
    <div style={{ position: "relative", flex: 1, ...style }}>
      <div style={{
        position: "relative",
        border: `1px solid ${error ? "#b81d14" : focus ? "#0e0e10" : "#d4d4d8"}`,
        borderRadius: 4,
        background: readOnly ? "#fafafb" : "#fff",
        transition: "border-color .15s",
      }}>
        {prefix && <div style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)" }}>{prefix}</div>}
        <label htmlFor={id} style={{
          position: "absolute",
          left: prefix ? 56 : 12,
          top: float ? -7 : 14,
          fontSize: float ? 11 : 13,
          color: error ? "#b81d14" : focus ? "#0e0e10" : "#6b6b72",
          background: "#fff", padding: float ? "0 4px" : 0,
          pointerEvents: "none",
          transition: "all .12s ease",
          fontWeight: float ? 500 : 400,
        }}>{label}</label>
        <input
          id={id}
          type={type}
          name={name}
          value={value || ""}
          placeholder={focus ? placeholder : ""}
          autoFocus={autoFocus}
          readOnly={readOnly}
          onChange={(e) => onChange && onChange(e.target.value)}
          onFocus={() => setFocus(true)}
          onBlur={(e) => { setFocus(false); onBlur && onBlur(e); }}
          style={{
            width: "100%", border: 0, outline: 0, background: "transparent",
            padding: prefix ? "14px 12px 14px 56px" : suffix ? "14px 40px 14px 12px" : "14px 12px",
            fontSize: 14, color: "#0e0e10",
          }}
        />
        {suffix && <div style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)" }}>{suffix}</div>}
      </div>
      {error && <div style={{ color: "#b81d14", fontSize: 11, marginTop: 4, marginLeft: 2 }}>{error}</div>}
    </div>
  );
}

// ─────────── Select / dropdown ───────────
function SelectField({ label, value, onChange, options, error, placeholder, style }) {
  const [open, setOpen] = useState(false);
  const [focus, setFocus] = useState(false);
  const ref = useRef();
  useEffect(() => {
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  const filled = !!value;
  const float = focus || filled || open;
  const selected = options?.find((o) => (o.value || o) === value);
  return (
    <div ref={ref} style={{ position: "relative", flex: 1, ...style }}>
      <div
        tabIndex={0}
        onFocus={() => setFocus(true)}
        onBlur={() => setFocus(false)}
        onClick={() => setOpen((v) => !v)}
        style={{
          position: "relative",
          border: `1px solid ${error ? "#b81d14" : open || focus ? "#0e0e10" : "#d4d4d8"}`,
          borderRadius: 4, background: "#fff",
          padding: "16px 40px 16px 12px",
          cursor: "pointer", userSelect: "none", minHeight: 48,
          fontSize: 14,
        }}>
        <label style={{
          position: "absolute", left: 12, top: float ? -7 : 14,
          fontSize: float ? 11 : 13,
          color: error ? "#b81d14" : open || focus ? "#0e0e10" : "#6b6b72",
          background: "#fff", padding: float ? "0 4px" : 0,
          pointerEvents: "none", transition: "all .12s ease",
          fontWeight: float ? 500 : 400,
        }}>{label}</label>
        <div style={{ color: filled ? "#0e0e10" : "transparent" }}>{selected?.label || selected?.toString() || "—"}</div>
        <IconChevron size={18} style={{ position: "absolute", right: 12, top: "50%", transform: `translateY(-50%) rotate(${open ? 180 : 0}deg)`, transition: "transform .15s", color: "#6b6b72" }} />
      </div>
      {open && (
        <div style={{
          position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0,
          background: "#fff", border: "1px solid #e5e5e9", borderRadius: 6,
          boxShadow: "0 8px 24px rgba(20,20,30,.10)", zIndex: 30,
          maxHeight: 280, overflowY: "auto",
        }}>
          {options.map((o) => {
            const v = o.value || o;
            const l = o.label || o;
            const active = v === value;
            return (
              <div key={v}
                onMouseDown={(e) => { e.preventDefault(); onChange(v); setOpen(false); }}
                style={{
                  padding: "12px 16px", cursor: "pointer", fontSize: 14,
                  background: active ? "#f7f7f8" : "transparent",
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                }}
                onMouseEnter={(e) => { if (!active) e.currentTarget.style.background = "#fafafb"; }}
                onMouseLeave={(e) => { if (!active) e.currentTarget.style.background = "transparent"; }}>
                <span>{l}</span>
                {active && <IconCheck size={16} />}
              </div>
            );
          })}
        </div>
      )}
      {error && <div style={{ color: "#b81d14", fontSize: 11, marginTop: 4, marginLeft: 2 }}>{error}</div>}
    </div>
  );
}

// ─────────── Phone field with country prefix ───────────
function PhoneField({ value, onChange, error }) {
  return (
    <div style={{ position: "relative", flex: 1, display: "flex", border: `1px solid ${error ? "#b81d14" : "#d4d4d8"}`, borderRadius: 4, background: "#fff", overflow: "hidden" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "0 12px", borderRight: "1px solid #e5e5e9", background: "#fafafb", cursor: "pointer" }}>
        <span style={{ width: 24, height: 16, background: "linear-gradient(to bottom, #b22 33%, #fff 33% 66%, #2a4 66%)", borderRadius: 2, display: "inline-block", position: "relative", overflow: "hidden" }}>
          <span style={{ position: "absolute", inset: 0, background: "linear-gradient(to bottom, #c8102e 33%, #fff 33%, #fff 66%, #c8102e 66%)" }} />
          <span style={{ position: "absolute", inset: 0, width: 12, background: "#3c3b6e" }} />
        </span>
        <span style={{ fontSize: 13, color: "#0e0e10" }}>+1</span>
        <IconChevron size={14} style={{ color: "#6b6b72" }} />
      </div>
      <input
        type="tel"
        placeholder="Phone Number"
        value={value || ""}
        onChange={(e) => onChange(formatPhone(e.target.value))}
        style={{ flex: 1, border: 0, outline: 0, background: "transparent", padding: "16px 12px", fontSize: 14 }}
      />
    </div>
  );
}

// ─────────── Checkbox ───────────
function Checkbox({ checked, onChange, label, size = 16, style }) {
  return (
    <label style={{ display: "inline-flex", alignItems: "flex-start", gap: 12, cursor: "pointer", ...style }}>
      <span
        onClick={(e) => { e.preventDefault(); onChange(!checked); }}
        style={{
          width: size, height: size, flexShrink: 0,
          border: `1.5px solid ${checked ? "#0e0e10" : "#9a9aa1"}`,
          background: checked ? "#0e0e10" : "#fff",
          borderRadius: 3, display: "inline-flex", alignItems: "center", justifyContent: "center",
          transition: "all .12s ease", marginTop: 1,
        }}>
        {checked && <IconCheck size={size - 4} style={{ color: "#fff", strokeWidth: 3 }} />}
      </span>
      {label && <span style={{ fontSize: 13, color: "#0e0e10", lineHeight: 1.4 }}>{label}</span>}
    </label>
  );
}

// ─────────── Modal scaffold ───────────
function Modal({ open, onClose, children, width = 480 }) {
  const [visible, setVisible] = useState(open);
  const [closing, setClosing] = useState(false);
  useEffect(() => {
    if (open) { setVisible(true); setClosing(false); }
    else if (visible) {
      setClosing(true);
      const t = setTimeout(() => { setVisible(false); setClosing(false); }, 160);
      return () => clearTimeout(t);
    }
  }, [open]);
  useEffect(() => {
    if (!visible) return;
    const h = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", h);
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", h); document.body.style.overflow = ""; };
  }, [visible, onClose]);
  if (!visible) return null;
  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 100,
      background: "rgba(20,20,30,.45)", backdropFilter: "blur(2px)",
      display: "flex", alignItems: "center", justifyContent: "center",
      animation: closing ? "fadeOut .16s ease forwards" : "fadeIn .18s ease-out",
    }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: "#fff", borderRadius: 8, width, maxWidth: "calc(100vw - 32px)",
        boxShadow: "0 24px 48px rgba(20,20,30,.20)",
        animation: closing ? "popOut .16s cubic-bezier(.4,0,1,1) forwards" : "popIn .2s cubic-bezier(.16,.9,.3,1)",
      }}>
        {children}
      </div>
      <style>{`
        @keyframes fadeIn  { from{opacity:0}                                       to{opacity:1} }
        @keyframes fadeOut { from{opacity:1}                                       to{opacity:0} }
        @keyframes popIn   { from{opacity:0;transform:scale(.95) translateY(8px)} to{opacity:1;transform:scale(1) translateY(0)} }
        @keyframes popOut  { from{opacity:1;transform:scale(1) translateY(0)}     to{opacity:0;transform:scale(.96) translateY(4px)} }
        @media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:1ms!important;transition-duration:1ms!important}}
      `}</style>
    </div>
  );
}

// ─────────── Toast ───────────
function Toast({ message, onDone }) {
  useEffect(() => {
    if (!message) return;
    const t = setTimeout(() => onDone(), 2400);
    return () => clearTimeout(t);
  }, [message, onDone]);
  if (!message) return null;
  return (
    <div style={{
      position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)",
      background: "#0e0e10", color: "#fff", padding: "12px 20px", borderRadius: 6,
      fontSize: 13, fontWeight: 500, zIndex: 200,
      boxShadow: "0 8px 24px rgba(20,20,30,.30)",
      display: "flex", alignItems: "center", gap: 12,
      animation: "toastIn .25s ease",
    }}>
      <IconCheck size={16} style={{ color: "#3acc7a" }} />
      {message}
      <style>{`@keyframes toastIn{from{opacity:0;transform:translate(-50%, 8px)}to{opacity:1;transform:translate(-50%, 0)}}`}</style>
    </div>
  );
}

Object.assign(window, { Button, TextField, SelectField, PhoneField, Checkbox, Modal, Toast });


