// Contextual "Manage Store" workspace — the bar + icon side-rail that replace
// the global chrome once you drill into a single store. The actual tab content
// is still rendered by <Dashboard embedded>, which owns the side-rail.

// Small round team emblem reused in the store bar + switcher.
function TeamEmblem({ store, size = 30 }) {
  if (store?.teamLogo?.url) {
    return <img src={__asset(store.teamLogo.url)} alt="" style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", flexShrink: 0 }} />;
  }
  const bg = store?.teamLogo?.color || store?.teamColors?.[0] || "#1d3a8a";
  const mono = store?.teamLogo?.mono || (store?.teamName || store?.storeTitle || "T").slice(0, 2).toUpperCase();
  return (
    <span style={{
      width: size, height: size, borderRadius: "50%", background: bg, flexShrink: 0,
      color: (bg || "").toLowerCase() === "#ffffff" ? "#0e0e10" : "#fff",
      display: "inline-flex", alignItems: "center", justifyContent: "center",
      fontWeight: 800, fontSize: size * 0.36,
      border: (bg || "").toLowerCase() === "#ffffff" ? "1px solid #d4d4d8" : "none",
    }}>{mono}</span>
  );
}

// ─────────── Status pill (Active / On hold) ───────────
function StatusDropdown({ status = "active" }) {
  const active = status !== "hold";
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 8,
      background: active ? "#d8f5e3" : "#fdeecb", color: active ? "#1f7a44" : "#92670b",
      borderRadius: 999, padding: "8px 16px",
      fontSize: 14, fontWeight: 700, userSelect: "none",
    }}>
      <span style={{ width: 8, height: 8, borderRadius: "50%", background: active ? "#1f9d55" : "#e0a92b", flexShrink: 0 }} />
      {active ? "Open" : "On Hold"}
    </span>
  );
}

// ─────────── Store switcher ───────────
function StoreSwitcher({ store, stores = [], onSwitchStore }) {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef();
  React.useEffect(() => {
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  const list = stores.length ? stores : [store];
  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button onClick={() => setOpen((v) => !v)} style={{
        display: "inline-flex", alignItems: "center", gap: 12,
        background: "#fff", border: "1px solid #d4d4d8", borderRadius: 8,
        padding: "8px 12px 8px 8px", cursor: "pointer", minWidth: 212, justifyContent: "space-between",
      }}>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 8, minWidth: 0 }}>
          <TeamEmblem store={store} size={24} />
          <span style={{ fontSize: 14.5, fontWeight: 600, color: "#0e0e10", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {store?.teamName || store?.storeTitle || "[Team Name]"}
          </span>
        </span>
        <IconChevron size={16} style={{ color: "#6b6b72", flexShrink: 0, transform: open ? "rotate(180deg)" : "none", transition: "transform .15s" }} />
      </button>
      {open && (
        <div style={{
          position: "absolute", top: "calc(100% + 8px)", right: 0, minWidth: 252, zIndex: 60,
          background: "#fff", border: "1px solid #e8e8ec", borderRadius: 8,
          boxShadow: "0 12px 28px rgba(20,20,30,.12)", padding: 4, maxHeight: 340, overflowY: "auto",
        }}>
          <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: ".08em", color: "#9a9aa1", padding: "8px 12px 8px" }}>SWITCH STORE</div>
          {list.map((s) => {
            const on = s.id === store?.id;
            return (
              <div key={s.id} onClick={() => { setOpen(false); if (!on) onSwitchStore && onSwitchStore(s.id); }}
                style={{ padding: "8px 12px", borderRadius: 5, fontSize: 14, cursor: "pointer", display: "flex", alignItems: "center", gap: 12, background: on ? "#f7f7f8" : "transparent" }}
                onMouseEnter={(e) => { if (!on) e.currentTarget.style.background = "#fafafb"; }}
                onMouseLeave={(e) => { if (!on) e.currentTarget.style.background = "transparent"; }}>
                <TeamEmblem store={s} size={24} />
                <span style={{ flex: 1, fontWeight: on ? 700 : 500, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{s.teamName || s.storeTitle}</span>
                {on && <IconCheck size={15} />}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

