/* ===== Access intake form — business-entity application (no-access flow). =====
// Standalone full-viewport page. Collects business identity + tax/banking,
// validates required fields, then routes to the manual-review pending state. */

function AccessApplyForm({ onSubmit, onCancel }) {
  const RED = "#e1251b";
  const INK = "#0e0e10";
  const [vals, setVals] = React.useState({
    legalName: "", dba: "", entityType: "", address: "",
    ein: "", routing: "", account: "",
  });
  const [errors, setErrors] = React.useState({});
  const set = (k) => (e) => setVals((v) => ({ ...v, [k]: e.target.value }));

  const REQUIRED = ["legalName", "entityType", "address", "ein", "routing", "account"];
  const submit = () => {
    const errs = {};
    REQUIRED.forEach((k) => { if (!vals[k].trim()) errs[k] = true; });
    setErrors(errs);
    if (Object.keys(errs).length === 0) onSubmit(vals);
  };

  const baseField = {
    width: "100%", padding: "12px 16px", fontSize: 14, color: INK,
    background: "#fff", border: "1px solid #d9d9de", borderRadius: 6,
    outline: "none", transition: "border-color .14s ease, box-shadow .14s ease",
  };
  const field = (key, placeholder, opts = {}) => {
    const invalid = errors[key];
    return (
      <input
        value={vals[key]}
        onChange={set(key)}
        placeholder={placeholder}
        style={{
          ...baseField,
          ...(opts.mono ? { fontFamily: '"JetBrains Mono", monospace', letterSpacing: ".02em" } : null),
          borderColor: invalid ? RED : "#d9d9de",
          boxShadow: invalid ? "0 0 0 3px rgba(225,37,27,.12)" : "none",
        }}
        onFocus={(e) => { if (!invalid) { e.target.style.borderColor = RED; e.target.style.boxShadow = "0 0 0 3px rgba(225,37,27,.12)"; } }}
        onBlur={(e) => { if (!invalid) { e.target.style.borderColor = "#d9d9de"; e.target.style.boxShadow = "none"; } }}
      />
    );
  };
  const sectionLabel = (txt) => (
    <div style={{
      fontFamily: '"JetBrains Mono", monospace', fontSize: 11.5, fontWeight: 500,
      letterSpacing: ".2em", textTransform: "uppercase", color: "#9a9aa1", marginBottom: 16,
    }}>{txt}</div>
  );

  return (
    <div style={{
      position: "fixed", inset: 0, overflowY: "auto", background: "#f3f3f5",
      fontFamily: '"Inter", system-ui, sans-serif', color: INK,
    }}>
      <div style={{ maxWidth: 900, margin: "0 auto", padding: "64px 32px 80px" }}>
        {/* header */}
        <div style={{ display: "inline-flex", alignItems: "center", gap: 16, marginBottom: 24 }}>
          <BrandMark variant="black" height={26} />
          <span style={{ width: 1, height: 24, background: "#d4d4d8" }} />
          <span style={{
            fontFamily: '"JetBrains Mono", monospace', fontSize: 11.5, fontWeight: 500,
            letterSpacing: ".22em", textTransform: "uppercase", color: "#6b6b72",
          }}>Business Verification</span>
        </div>

        <h1 style={{
          margin: "0 0 16px", fontFamily: '"Archivo", sans-serif', fontWeight: 900,
          fontSize: "clamp(30px, 4vw, 46px)", lineHeight: 1.02, letterSpacing: "-0.02em",
          textTransform: "uppercase",
        }}>Register Your Organization</h1>
        <p style={{ margin: "0 0 36px", maxWidth: 640, color: "#6b6b72", fontSize: 15.5, lineHeight: 1.5 }}>
          We couldn&apos;t match your email to an existing dealership. Provide your organization&apos;s
          business-entity details &mdash; collected securely through
          <strong style={{ color: INK, fontWeight: 700 }}> Stripe</strong>. Team Stores access opens once your
          organization is approved.
        </p>

        {/* card */}
        <div style={{
          background: "#fff", border: "1px solid #e5e5e9", borderRadius: 10,
          boxShadow: "0 1px 2px rgba(20,20,30,.04)", padding: "36px 40px 40px",
        }}>
          {sectionLabel("Business Identity")}
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            {field("legalName", "Legal business name")}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
              {field("dba", "DBA / trade name (optional)")}
              {field("entityType", "Entity type (LLC, S-Corp…)")}
            </div>
            {field("address", "Registered business address")}
          </div>

          <div style={{ height: 1, background: "#ececf0", margin: "32px 0 28px" }} />

          {sectionLabel("Tax & Banking")}
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
              {field("ein", "EIN (XX-XXXXXXX)", { mono: true })}
              {field("routing", "Bank routing number", { mono: true })}
            </div>
            {field("account", "Bank account number", { mono: true })}
          </div>

          <div style={{
            display: "flex", alignItems: "center", gap: 12, marginTop: 24,
            background: "#f7f7f8", border: "1px solid #ececf0", borderRadius: 6, padding: "12px 16px",
          }}>
            <IconLock size={16} style={{ color: "#1f9d55", flexShrink: 0 }} />
            <span style={{ fontSize: 13, color: "#6b6b72", lineHeight: 1.4 }}>
              Banking &amp; EIN details are encrypted and used only for payout verification.
            </span>
          </div>

          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 32 }}>
            <button onClick={onCancel} style={{
              background: "#fff", border: "1px solid #d4d4d8", color: INK,
              padding: "12px 28px", fontSize: 14, fontWeight: 700, borderRadius: 6, cursor: "pointer",
              transition: "background .14s ease, border-color .14s ease",
            }}
              onMouseEnter={(e) => { e.currentTarget.style.background = "#f7f7f8"; e.currentTarget.style.borderColor = "#b8b8be"; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; e.currentTarget.style.borderColor = "#d4d4d8"; }}>
              Cancel
            </button>
            <button onClick={submit} style={{
              display: "inline-flex", alignItems: "center", gap: 12, background: INK, color: "#fff",
              border: "none", padding: "12px 28px", fontSize: 14, fontWeight: 700, borderRadius: 6,
              cursor: "pointer", transition: "background .14s ease",
            }}
              onMouseEnter={(e) => { e.currentTarget.style.background = "#000"; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = INK; }}>
              Submit &amp; Verify
              <IconArrowRight size={16} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ===== Access pending — manual review waiting state (no-access flow). =====
// Shown for the 24–48 hr admin review window after an application is submitted.
// A returning unverified user lands here until a decision is made. */

function AccessPending({ onApprove, onBack, email }) {
  const RED = "#e1251b";
  return (
    <div style={{
      position: "fixed", inset: 0, overflowY: "auto", background: "#0c0c0e", color: "#fff",
      fontFamily: '"Inter", system-ui, sans-serif',
      display: "flex", alignItems: "center", justifyContent: "center", padding: 40,
    }}>
      <div style={{ textAlign: "center", maxWidth: 620 }}>
        {/* spinner + clock */}
        <div style={{ position: "relative", width: 88, height: 88, margin: "0 auto 40px" }}>
          <div style={{
            position: "absolute", inset: 0, borderRadius: "50%",
            border: "2px solid rgba(255,255,255,.10)",
          }} />
          <div style={{
            position: "absolute", inset: 0, borderRadius: "50%",
            border: "2px solid transparent", borderTopColor: RED, borderRightColor: RED,
            animation: "accSpin 1.1s linear infinite",
          }} />
          <div style={{
            position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center",
            color: RED,
          }}>
            <IconClock size={26} />
          </div>
        </div>

        <div style={{
          fontFamily: '"JetBrains Mono", monospace', fontSize: 12, fontWeight: 500,
          letterSpacing: ".26em", textTransform: "uppercase", color: "rgba(255,255,255,.5)", marginBottom: 20,
        }}>Registration Received</div>

        <h1 style={{
          margin: "0 0 24px", fontFamily: '"Archivo", sans-serif', fontWeight: 900,
          fontSize: "clamp(36px, 5vw, 58px)", lineHeight: 0.98, letterSpacing: "-0.01em",
          textTransform: "uppercase",
        }}>Your Organization Is<br />Awaiting Approval</h1>

        <p style={{
          margin: "0 auto 36px", maxWidth: 520, color: "rgba(255,255,255,.62)",
          fontSize: 16, lineHeight: 1.55, textWrap: "pretty",
        }}>
          Thanks for registering. We&apos;re reviewing your organization&apos;s business entity, EIN, and banking
          details &mdash; this typically takes <strong style={{ color: "#fff", fontWeight: 700 }}>24&ndash;48 hours</strong>.
          You&apos;ll land here each time you sign in until it&apos;s approved, and we&apos;ll email <strong style={{ color: "#fff", fontWeight: 700 }}>{email || "jane@prolook.com"}</strong> the moment a decision is made.
        </p>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 16 }}>
          <button onClick={onBack} style={{
            background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.22)", color: "#fff",
            padding: "12px 28px", fontSize: 14, fontWeight: 700, borderRadius: 6, cursor: "pointer",
            transition: "background .14s ease, border-color .14s ease",
          }}
            onMouseEnter={(e) => { e.currentTarget.style.background = "rgba(255,255,255,.1)"; e.currentTarget.style.borderColor = "rgba(255,255,255,.4)"; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = "rgba(255,255,255,.04)"; e.currentTarget.style.borderColor = "rgba(255,255,255,.22)"; }}>
            Back to PROLOOK
          </button>
          <button onClick={onApprove} style={{
            display: "inline-flex", alignItems: "center", gap: 12, background: RED, color: "#fff",
            border: "none", padding: "12px 28px", fontSize: 14, fontWeight: 700, borderRadius: 6,
            cursor: "pointer", transition: "transform .14s ease, background .14s ease",
          }}
            onMouseEnter={(e) => { e.currentTarget.style.background = "#c41d14"; e.currentTarget.style.transform = "translateY(-1px)"; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = RED; e.currentTarget.style.transform = "none"; }}>
            Continue to Overview
            <IconArrowRight size={16} />
          </button>
        </div>

        <div style={{
          fontFamily: '"JetBrains Mono", monospace', fontSize: 11, letterSpacing: ".14em",
          textTransform: "uppercase", color: "rgba(255,255,255,.32)", marginTop: 32,
        }}>Prototype only &mdash; this button will not exist in production</div>
      </div>
      <style>{`@keyframes accSpin { to { transform: rotate(360deg) } }`}</style>
    </div>
  );
}

/* ===== Stripe verification — automated approval (no-access flow). =====
// Replaces the old manual-review waiting state. Business details are verified
// instantly via Stripe; this brief step animates the check, then hands straight
// off to the dashboard. No 24–48 hr wait. */
function StripeVerifying({ onDone }) {
  const STRIPE = "#635bff";
  const [done, setDone] = React.useState(false);
  React.useEffect(() => {
    const t1 = setTimeout(() => setDone(true), 1500);
    const t2 = setTimeout(() => { onDone && onDone(); }, 2400);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);
  return (
    <div style={{
      position: "fixed", inset: 0, overflowY: "auto", background: "#0c0c0e", color: "#fff",
      fontFamily: '"Inter", system-ui, sans-serif',
      display: "flex", alignItems: "center", justifyContent: "center", padding: 40,
    }}>
      <div style={{ textAlign: "center", maxWidth: 560 }}>
        <div style={{ position: "relative", width: 88, height: 88, margin: "0 auto 40px" }}>
          {!done && (
            <React.Fragment>
              <div style={{ position: "absolute", inset: 0, borderRadius: "50%", border: "2px solid rgba(255,255,255,.10)" }} />
              <div style={{ position: "absolute", inset: 0, borderRadius: "50%", border: "2px solid transparent", borderTopColor: STRIPE, borderRightColor: STRIPE, animation: "accSpin 0.9s linear infinite" }} />
            </React.Fragment>
          )}
          {done && (
            <span style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "#1f9d55", display: "flex", alignItems: "center", justifyContent: "center", animation: "accPop .35s cubic-bezier(.2,1.2,.4,1) both" }}>
              <IconCheck size={38} style={{ strokeWidth: 3 }} />
            </span>
          )}
          {!done && (
            <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", color: STRIPE }}>
              <IconLock size={26} />
            </div>
          )}
        </div>

        <div style={{
          fontFamily: '"JetBrains Mono", monospace', fontSize: 12, fontWeight: 500,
          letterSpacing: ".26em", textTransform: "uppercase", color: "rgba(255,255,255,.5)", marginBottom: 20,
        }}>{done ? "Verified" : "Verifying with Stripe"}</div>

        <h1 style={{
          margin: "0 0 24px", fontFamily: '"Archivo", sans-serif', fontWeight: 900,
          fontSize: "clamp(32px, 4.5vw, 52px)", lineHeight: 0.98, letterSpacing: "-0.01em",
          textTransform: "uppercase",
        }}>{done ? "You're All Set" : "Verifying Your Business"}</h1>

        <p style={{ margin: "0 auto", maxWidth: 460, color: "rgba(255,255,255,.62)", fontSize: 16, lineHeight: 1.55, textWrap: "pretty" }}>
          {done
            ? "Your business is verified. Opening your Team Stores dashboard\u2026"
            : "We\u2019re confirming your business entity and banking details through Stripe. This only takes a moment \u2014 no manual review, no waiting."}
        </p>
      </div>
      <style>{`@keyframes accSpin { to { transform: rotate(360deg) } } @keyframes accPop { from { transform: scale(.3); opacity: 0 } to { transform: scale(1); opacity: 1 } }`}</style>
    </div>
  );
}

Object.assign(window, { AccessApplyForm, AccessPending, StripeVerifying });


/* ===== ASSET 9 : ed813c4c-4804-4e3e-8d11-c83d3eaa34de ===== */
// League feature — Create New League 3-step modal + league filter pills.
// Lets a rep group multiple team stores into an organizational "league".

const LEAGUE_GREEN = "#1f9d55";
const LEAGUE_GREEN_SOFT = "#e7f5ed";

// ─────────── Step indicator ───────────
function LeagueStepper({ step }) {
  const steps = ["Basic Info", "Stores & Groups", "Access"];
  return (
    <div style={{ display: "flex", alignItems: "center", padding: "16px 28px 0" }}>
      {steps.map((label, i) => {
        const n = i + 1;
        const done = step > n;
        const current = step === n;
        const active = done || current;
        return (
          <React.Fragment key={label}>
            <div style={{ display: "flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
              <div style={{
                width: 28, height: 28, borderRadius: "50%", flexShrink: 0,
                display: "inline-flex", alignItems: "center", justifyContent: "center",
                background: active ? LEAGUE_GREEN : "#fff",
                border: `1.5px solid ${active ? LEAGUE_GREEN : "#d4d4d8"}`,
                color: active ? "#fff" : "#9a9aa1",
                fontSize: 13, fontWeight: 700,
                boxShadow: current ? `0 0 0 4px ${LEAGUE_GREEN_SOFT}` : "none",
                transition: "all .15s ease"
              }}>
                {done ? <IconCheck size={15} style={{ strokeWidth: 3 }} /> : n}
              </div>
              <span style={{
                fontSize: 14, fontWeight: 600,
                color: active ? "#0e0e10" : "#9a9aa1", whiteSpace: "nowrap"
              }}>{label}</span>
            </div>
            {i < steps.length - 1 &&
            <div style={{
              flex: 1, height: 1.5, margin: "0 16px",
              background: step > n ? LEAGUE_GREEN : "#e5e5e9",
              transition: "background .2s ease"
            }} />
            }
          </React.Fragment>);

      })}
    </div>);

}

// ─────────── Store row (selectable) ───────────
function StoreSelectRow({ store, checked, onToggle }) {
  const STATE_ABBR = { Louisiana: "LA", California: "CA", Texas: "TX", "New York": "NY", Florida: "FL", Washington: "WA", Oregon: "OR", Nevada: "NV", Arizona: "AZ", Colorado: "CO" };
  const city = store.shipCity || "Carlsbad";
  const stateAbbr = STATE_ABBR[store.shipState] || (store.shipState || "CA").slice(0, 2).toUpperCase();
  const name = store.storeTitle || store.teamName || "Team Store";
  const color = store.teamColors?.[0] || "#1d3a8a";
  const initial = name[0]?.toUpperCase() || "T";
  return (
    <label style={{
      display: "flex", alignItems: "center", gap: 12, padding: "12px 16px",
      borderBottom: "1px solid #f1f1f3", cursor: "pointer",
      background: checked ? "#fafafb" : "#fff", transition: "background .12s"
    }}
    onMouseEnter={(e) => {if (!checked) e.currentTarget.style.background = "#fcfcfd";}}
    onMouseLeave={(e) => {if (!checked) e.currentTarget.style.background = "#fff";}}>
      <Checkbox checked={checked} onChange={onToggle} size={18} />
      <div style={{
        width: 36, height: 36, borderRadius: "50%", flexShrink: 0,
        background: color, color: "#fff", fontWeight: 700, fontSize: 14,
        display: "inline-flex", alignItems: "center", justifyContent: "center"
      }}>{initial}</div>
      <div style={{ minWidth: 0 }}>
        <div style={{ fontSize: 14, fontWeight: 600, color: "#0e0e10" }}>{name}</div>
        <div style={{ fontSize: 12, color: "#9a9aa1" }}>{city}, {stateAbbr}</div>
      </div>
    </label>);

}

// ─────────── The modal ───────────
function CreateLeagueModal({ open, stores, onClose, onCreate }) {
  const [step, setStep] = React.useState(1);
  // step 1
  const [name, setName] = React.useState("");
  const [logo, setLogo] = React.useState(null); // {url}
  // step 2
  const [query, setQuery] = React.useState("");
  const [selected, setSelected] = React.useState({}); // id -> true
  const [groups, setGroups] = React.useState([]);
  const [groupDraft, setGroupDraft] = React.useState("");
  // step 3
  const [invites, setInvites] = React.useState("");
  const [role, setRole] = React.useState("manager");

  // Reset everything when (re)opened
  React.useEffect(() => {
    if (open) {
      setStep(1);setName("");setLogo(null);setQuery("");setSelected({});
      setGroups([]);setGroupDraft("");setInvites("");setRole("manager");
    }
  }, [open]);

  const selectedIds = Object.keys(selected).filter((id) => selected[id]);
  const selectedCount = selectedIds.length;

  const filteredStores = stores.filter((s) => {
    const n = (s.storeTitle || s.teamName || "").toLowerCase();
    return n.includes(query.toLowerCase());
  });

  const fileRef = React.useRef();
  const onFile = (file) => {
    if (!file) return;
    setLogo({ url: URL.createObjectURL(file), name: file.name });
  };

  const addGroup = () => {
    const v = groupDraft.trim();
    if (!v) return;
    setGroups((g) => [...g, v]);
    setGroupDraft("");
  };

  const canContinue1 = name.trim().length > 0;
  const canContinue2 = selectedCount > 0;

  const submit = () => {
    const managerEmails = invites.split(",").map((e) => e.trim()).filter(Boolean);
    onCreate({
      id: "league-" + Date.now(),
      name: name.trim(),
      logo,
      storeIds: selectedIds,
      groups,
      managers: managerEmails,
      role
    });
  };

  if (!open) return null;

  const ROLE_LABEL = {
    manager: "Manager — manage stores & groups",
    admin: "Admin — full league control",
    viewer: "Viewer — read-only access"
  };

  return (
    <Modal open={open} onClose={onClose} width={720}>
      <div style={{ display: "flex", flexDirection: "column", maxHeight: "86vh" }}>
        {/* Header */}
        <div style={{ padding: "28px 28px 0", position: "relative" }}>
          <button onClick={onClose} style={{
            position: "absolute", top: 24, right: 24, width: 32, height: 32,
            border: 0, background: "transparent", borderRadius: 6, cursor: "pointer",
            display: "inline-flex", alignItems: "center", justifyContent: "center", color: "#6b6b72"
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = "#f1f1f3"}
          onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
            <IconX size={18} />
          </button>
          <h2 style={{ fontSize: 22, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Create New League</h2>
          <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 0" }}>
            Set up an organizational container to manage multiple team stores together.
          </p>
        </div>

        <LeagueStepper step={step} />

        <div style={{ height: 1, background: "#ececf0", margin: "16px 0 0" }} />

        {/* Body (scrollable) */}
        <div style={{ padding: "24px 28px", overflowY: "auto", flex: 1 }}>
          {step === 1 &&
          <StepBasic
            name={name} setName={setName}
            logo={logo} fileRef={fileRef} onFile={onFile} setLogo={setLogo} />

          }
          {step === 2 &&
          <StepStores
            query={query} setQuery={setQuery}
            filteredStores={filteredStores} selected={selected}
            onToggle={(id) => setSelected((s) => ({ ...s, [id]: !s[id] }))}
            selectedCount={selectedCount}
            groups={groups} setGroups={setGroups}
            groupDraft={groupDraft} setGroupDraft={setGroupDraft} addGroup={addGroup} />

          }
          {step === 3 &&
          <StepAccess
            invites={invites} setInvites={setInvites}
            role={role} setRole={setRole} roleLabel={ROLE_LABEL}
            summary={{ name: name.trim() || "Untitled League", stores: selectedCount, groups: groups.length }} />

          }
        </div>

        {/* Footer */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "16px 28px", borderTop: "1px solid #ececf0", gap: 12
        }}>
          <div>
            {step > 1 &&
            <button onClick={() => setStep((s) => s - 1)} style={{
              border: 0, background: "transparent", cursor: "pointer",
              fontSize: 14, fontWeight: 600, color: "#0e0e10",
              display: "inline-flex", alignItems: "center", gap: 8, padding: "8px 4px"
            }}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M19 12H5" /><path d="M12 19l-7-7 7-7" /></svg>
                Back
              </button>
            }
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <button onClick={onClose} style={{
              border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10",
              padding: "12px 24px", borderRadius: 6, cursor: "pointer",
              fontSize: 14, fontWeight: 600
            }}>Cancel</button>
            {step < 3 ?
            <GreenButton
              disabled={step === 1 ? !canContinue1 : !canContinue2}
              onClick={() => setStep((s) => s + 1)}>
                Continue
              </GreenButton> :

            <GreenButton onClick={submit}>Create League</GreenButton>
            }
          </div>
        </div>
      </div>
    </Modal>);

}

// Green primary action button (league accent)
function GreenButton({ children, onClick, disabled }) {
  return (
    <button onClick={disabled ? undefined : onClick} disabled={disabled} style={{
      border: 0, borderRadius: 6, padding: "12px 28px",
      background: disabled ? "#a8d8bd" : LEAGUE_GREEN, color: "#fff",
      fontSize: 14, fontWeight: 700, cursor: disabled ? "not-allowed" : "pointer",
      boxShadow: disabled ? "none" : "0 1px 2px rgba(31,157,85,.4)",
      transition: "background .15s"
    }}
    onMouseEnter={(e) => {if (!disabled) e.currentTarget.style.background = "#1b8a4a";}}
    onMouseLeave={(e) => {if (!disabled) e.currentTarget.style.background = LEAGUE_GREEN;}}>
      {children}
    </button>);

}

// ─────────── Step 1: Basic Info ───────────
function StepBasic({ name, setName, logo, fileRef, onFile, setLogo }) {
  const [drag, setDrag] = React.useState(false);
  return (
    <div>
      <FieldLabel>League Name</FieldLabel>
      <input
        autoFocus
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="e.g. Cougars Athletic Association"
        style={{
          width: "100%", padding: "12px 16px", fontSize: 15, borderRadius: 6,
          border: `1.5px solid ${name ? LEAGUE_GREEN : "#d4d4d8"}`, outline: "none",
          boxShadow: name ? `0 0 0 3px ${LEAGUE_GREEN_SOFT}` : "none", transition: "all .12s"
        }}
        onFocus={(e) => {e.target.style.borderColor = LEAGUE_GREEN;e.target.style.boxShadow = `0 0 0 3px ${LEAGUE_GREEN_SOFT}`;}}
        onBlur={(e) => {if (!name) {e.target.style.borderColor = "#d4d4d8";e.target.style.boxShadow = "none";}}} />
      
      <HelpText>This is how your league appears across all dashboards.</HelpText>

      <FieldLabel style={{ marginTop: 24 }}>League Logo</FieldLabel>
      <input ref={fileRef} type="file" accept="image/*" style={{ display: "none" }}
      onChange={(e) => onFile(e.target.files?.[0])} />
      <div
        onClick={() => fileRef.current?.click()}
        onDragOver={(e) => {e.preventDefault();setDrag(true);}}
        onDragLeave={() => setDrag(false)}
        onDrop={(e) => {e.preventDefault();setDrag(false);onFile(e.dataTransfer.files?.[0]);}}
        style={{
          border: `1.5px dashed ${drag ? LEAGUE_GREEN : "#d4d4d8"}`, borderRadius: 8,
          padding: "32px 20px", textAlign: "center", cursor: "pointer",
          background: drag ? LEAGUE_GREEN_SOFT : "#fafafb", transition: "all .12s"
        }}>
        {logo ?
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 12 }}>
            <img src={__asset(logo.url)} alt="" style={{ width: 72, height: 72, objectFit: "contain", borderRadius: 8 }} />
            <div style={{ fontSize: 13, color: "#0e0e10", fontWeight: 600 }}>{logo.name}</div>
            <button onClick={(e) => {e.stopPropagation();setLogo(null);}} style={{
            border: 0, background: "transparent", color: "#b81d14", fontSize: 13, fontWeight: 600, cursor: "pointer",
            display: "inline-flex", alignItems: "center", gap: 8
          }}><IconTrash size={14} /> Remove</button>
          </div> :

        <React.Fragment>
            <div style={{
            width: 48, height: 48, borderRadius: "50%", background: "#ececf0", margin: "0 auto 16px",
            display: "inline-flex", alignItems: "center", justifyContent: "center", color: "#6b6b72"
          }}>
              <IconUpload size={22} />
            </div>
            <div style={{ fontSize: 14, color: "#0e0e10", fontWeight: 500 }}>Drop your logo here, or click to browse</div>
            <div style={{ fontSize: 12, color: "#9a9aa1", marginTop: 4 }}>PNG, JPG or SVG — recommended 512×512px</div>
          </React.Fragment>
        }
      </div>
    </div>);

}

// ─────────── Step 2: Stores & Groups ───────────
function StepStores({ query, setQuery, filteredStores, selected, onToggle, selectedCount, groups, setGroups, groupDraft, setGroupDraft, addGroup }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 28 }}>
      {/* Left: stores */}
      <div>
        <SectionHead title="Add Team Stores" sub="Select stores to include in this league." />
        <div style={{
          position: "relative", border: "1px solid #d4d4d8", borderRadius: 6,
          display: "flex", alignItems: "center", marginBottom: 12
        }}>
          <IconSearch size={16} style={{ position: "absolute", left: 12, color: "#9a9aa1" }} />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search stores..." style={{
            width: "100%", border: 0, outline: 0, background: "transparent", padding: "12px 12px 12px 36px", fontSize: 14
          }} />
        </div>
        <div style={{ border: "1px solid #ececf0", borderRadius: 8, overflow: "hidden", maxHeight: 280, overflowY: "auto" }}>
          {filteredStores.length === 0 ?
          <div style={{ padding: 24, textAlign: "center", color: "#9a9aa1", fontSize: 13 }}>No stores match your search.</div> :
          filteredStores.map((s) =>
          <StoreSelectRow key={s.id} store={s} checked={!!selected[s.id]} onToggle={() => onToggle(s.id)} />
          )}
        </div>
        <div style={{ fontSize: 12, color: "#6b6b72", marginTop: 12 }}>{selectedCount} selected</div>
      </div>

      {/* Right: groups */}
      <div>
        <SectionHead title="Create Groups" sub="Organize stores by sport or season. Optional." />
        <div style={{ display: "flex", gap: 12, marginBottom: 12 }}>
          <input
            value={groupDraft}
            onChange={(e) => setGroupDraft(e.target.value)}
            onKeyDown={(e) => {if (e.key === "Enter") {e.preventDefault();addGroup();}}}
            placeholder="e.g. Boys Basketball"
            style={{ flex: 1, border: "1px solid #d4d4d8", borderRadius: 6, outline: 0, padding: "12px 12px", fontSize: 14 }} />
          
          <button onClick={addGroup} style={{
            border: "1px solid #d4d4d8", background: "#fff", borderRadius: 6, padding: "0 16px",
            fontSize: 14, fontWeight: 600, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 8, color: "#0e0e10"
          }}><IconPlus size={15} /> Add</button>
        </div>
        {groups.length === 0 ?
        <div style={{
          border: "1.5px dashed #d4d4d8", borderRadius: 8, padding: "28px 16px",
          textAlign: "center", color: "#9a9aa1", fontSize: 13
        }}>No groups yet — they're optional.</div> :

        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {groups.map((g, i) =>
          <div key={i} style={{
            display: "flex", alignItems: "center", justifyContent: "space-between",
            border: "1px solid #ececf0", borderRadius: 6, padding: "12px 12px", background: "#fff"
          }}>
                <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 14, color: "#0e0e10" }}>
                  <IconLayers size={15} style={{ color: LEAGUE_GREEN }} /> {g}
                </span>
                <button onClick={() => setGroups((arr) => arr.filter((_, idx) => idx !== i))} style={{
              border: 0, background: "transparent", cursor: "pointer", color: "#9a9aa1", padding: 4,
              display: "inline-flex"
            }}><IconX size={15} /></button>
              </div>
          )}
          </div>
        }
      </div>
    </div>);

}

// ─────────── Step 3: Access ───────────
function StepAccess({ invites, setInvites, role, setRole, roleLabel, summary }) {
  return (
    <div>
      <FieldLabel>Invite League Managers</FieldLabel>
      <textarea
        value={invites}
        onChange={(e) => setInvites(e.target.value)}
        placeholder="jane@example.com, john@example.com"
        rows={3}
        style={{
          width: "100%", border: "1px solid #d4d4d8", borderRadius: 6, outline: 0,
          padding: "12px 16px", fontSize: 14, resize: "vertical", fontFamily: "inherit", lineHeight: 1.5
        }} />
      
      <HelpText>Separate multiple emails with commas. Invitations are sent immediately.</HelpText>

      <FieldLabel style={{ marginTop: 24 }}>Default Role for Invitees</FieldLabel>
      <div style={{ position: "relative" }}>
        <select value={role} onChange={(e) => setRole(e.target.value)} style={{
          width: "100%", border: "1px solid #d4d4d8", borderRadius: 6, outline: 0,
          padding: "12px 40px 12px 16px", fontSize: 14, background: "#fff",
          appearance: "none", cursor: "pointer", color: "#0e0e10"
        }}>
          <option value="manager">{roleLabel.manager}</option>
          <option value="admin">{roleLabel.admin}</option>
          <option value="viewer">{roleLabel.viewer}</option>
        </select>
        <IconChevron size={18} style={{ position: "absolute", right: 16, top: "50%", transform: "translateY(-50%)", color: "#6b6b72", pointerEvents: "none" }} />
      </div>
      <HelpText>You can change individual roles later in League Settings.</HelpText>

      {/* Summary */}
      <div style={{
        marginTop: 24, border: "1px solid #ececf0", borderRadius: 8,
        background: "#fafafb", padding: "16px 16px"
      }}>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 8, fontWeight: 700, fontSize: 14, color: "#0e0e10", marginBottom: 12 }}>
          <IconTrophy size={17} style={{ color: LEAGUE_GREEN }} /> Summary
        </div>
        <SummaryRow label="League:" value={summary.name} />
        <SummaryRow label="Team stores:" value={summary.stores} />
        <SummaryRow label="Groups:" value={summary.groups} />
      </div>
    </div>);

}

function SummaryRow({ label, value }) {
  return (
    <div style={{ fontSize: 14, color: "#6b6b72", marginTop: 4 }}>
      {label} <span style={{ color: "#0e0e10", fontWeight: 600 }}>{value}</span>
    </div>);

}

// ─────────── small helpers ───────────
function FieldLabel({ children, style }) {
  return <div style={{ fontSize: 14, fontWeight: 600, color: "#0e0e10", marginBottom: 8, ...style }}>{children}</div>;
}
function HelpText({ children }) {
  return <div style={{ fontSize: 12.5, color: "#9a9aa1", marginTop: 8 }}>{children}</div>;
}
function SectionHead({ title, sub }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <div style={{ fontSize: 15, fontWeight: 700, color: "#0e0e10" }}>{title}</div>
      <div style={{ fontSize: 12.5, color: "#9a9aa1", marginTop: 2 }}>{sub}</div>
    </div>);

}

// ─────────── League filter pills (shown on the overview once leagues exist) ───────────
function LeaguePills({ leagues, activeLeagueId, onSelect }) {
  if (!leagues.length) return null;
  const pill = (key, label, active, onClick) =>
  <button key={key} onClick={onClick} style={{
    border: `1px solid ${active ? "#0e0e10" : "#d4d4d8"}`,
    background: active ? "#0e0e10" : "#fff",
    color: active ? "#fff" : "#0e0e10",
    borderRadius: 999, padding: "8px 24px", fontSize: 13, fontWeight: 700,
    letterSpacing: ".02em", cursor: "pointer", whiteSpace: "nowrap",
    transition: "all .12s"
  }}>{label}</button>;

  return (
    <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 24 }}>
      {pill("all", "All Stores", !activeLeagueId, () => onSelect(null))}
      {leagues.map((lg) => pill(lg.id, lg.name, activeLeagueId === lg.id, () => onSelect(lg.id)))}
    </div>);

}

Object.assign(window, { CreateLeagueModal, LeaguePills, CreateGroupModal });

// ═══════════════ Create New League Group modal ═══════════════
// Opened from within a league tab. Lets the rep name a group and pick which
// of the league's still-ungrouped team stores belong to it.

function GroupStoreSelectRow({ store, checked, onToggle }) {
  const STATE_ABBR = { Louisiana: "LA", California: "CA", Texas: "TX", "New York": "NY", Florida: "FL", Washington: "WA", Oregon: "OR", Nevada: "NV", Arizona: "AZ", Colorado: "CO" };
  const name = store.storeTitle || store.teamName || "Team Store";
  const sport = store.sport || "Sport";
  const color = store.teamColors?.[0] || "#c9c9cf";
  const initial = (store.teamName || store.storeTitle || "T").slice(0, 2).toUpperCase();
  return (
    <button onClick={onToggle} style={{
      display: "flex", alignItems: "center", gap: 12, width: "100%", textAlign: "left",
      padding: "12px 12px", borderRadius: 8, cursor: "pointer",
      border: `1.5px solid ${checked ? LEAGUE_GREEN : "#e5e5e9"}`,
      background: checked ? LEAGUE_GREEN_SOFT : "#fff",
      transition: "border-color .12s, background .12s",
    }}
      onMouseEnter={(e) => { if (!checked) e.currentTarget.style.borderColor = "#c9c9cf"; }}
      onMouseLeave={(e) => { if (!checked) e.currentTarget.style.borderColor = "#e5e5e9"; }}>
      <div style={{
        width: 40, height: 40, borderRadius: "50%", flexShrink: 0,
        background: color, color: "#fff", fontWeight: 700, fontSize: 13,
        display: "inline-flex", alignItems: "center", justifyContent: "center",
      }}>{initial}</div>
      <div style={{ minWidth: 0, flex: 1 }}>
        <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{name}</div>
        <div style={{ fontSize: 12.5, color: "#9a9aa1" }}>{sport}</div>
      </div>
      <span style={{
        width: 24, height: 24, borderRadius: "50%", flexShrink: 0,
        border: checked ? "none" : "1.5px solid #d4d4d8",
        background: checked ? LEAGUE_GREEN : "#fff",
        display: "inline-flex", alignItems: "center", justifyContent: "center",
        transition: "all .12s",
      }}>
        {checked && <IconCheck size={13} style={{ color: "#fff", strokeWidth: 3.5 }} />}
      </span>
    </button>
  );
}

function CreateGroupModal({ open, league, stores, onClose, onCreate }) {
  const [name, setName] = React.useState("");
  const [selected, setSelected] = React.useState({});

  React.useEffect(() => {
    if (open) { setName(""); setSelected({}); }
  }, [open]);

  if (!open || !league) return null;

  const assignedIds = new Set((league.groups || []).flatMap((g) => g.storeIds || []));
  const available = stores.filter((s) => league.storeIds.includes(s.id) && !assignedIds.has(s.id));

  const selectedIds = Object.keys(selected).filter((id) => selected[id]);
  const count = selectedIds.length;
  const canCreate = name.trim().length > 0 && count > 0;

  const submit = () => {
    if (!canCreate) return;
    onCreate(league.id, { id: "group-" + Date.now(), name: name.trim(), storeIds: selectedIds });
  };

  return (
    <Modal open={open} onClose={onClose} width={760}>
      <div style={{ display: "flex", flexDirection: "column", maxHeight: "86vh" }}>
        {/* Header */}
        <div style={{ padding: "28px 32px 20px", position: "relative" }}>
          <button onClick={onClose} style={{
            position: "absolute", top: 24, right: 24, width: 32, height: 32,
            border: 0, background: "transparent", borderRadius: 6, cursor: "pointer",
            display: "inline-flex", alignItems: "center", justifyContent: "center", color: "#6b6b72",
          }}
            onMouseEnter={(e) => e.currentTarget.style.background = "#f1f1f3"}
            onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
            <IconX size={18} />
          </button>
          <h2 style={{ fontSize: 22, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Create New League Group</h2>
          <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 0", maxWidth: 560, lineHeight: 1.5 }}>
            Groups allow you to organize individual team stores by sport or season within your league.
          </p>
        </div>

        {/* Body */}
        <div style={{ padding: "0 32px 8px", overflowY: "auto", flex: 1 }}>
          <FieldLabel>Group Name</FieldLabel>
          <input
            autoFocus
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Boys Basketball"
            style={{
              width: "100%", padding: "12px 16px", fontSize: 15, borderRadius: 6,
              border: `1.5px solid ${name ? LEAGUE_GREEN : "#d4d4d8"}`, outline: "none",
              boxShadow: name ? `0 0 0 3px ${LEAGUE_GREEN_SOFT}` : "none", transition: "all .12s",
            }}
            onFocus={(e) => { e.target.style.borderColor = LEAGUE_GREEN; e.target.style.boxShadow = `0 0 0 3px ${LEAGUE_GREEN_SOFT}`; }}
            onBlur={(e) => { if (!name) { e.target.style.borderColor = "#d4d4d8"; e.target.style.boxShadow = "none"; } }}
          />

          <div style={{ marginTop: 28 }}>
            <div style={{ fontSize: 16, fontWeight: 800, color: "#0e0e10" }}>Add team stores</div>
            <div style={{ fontSize: 13.5, color: "#9a9aa1", marginTop: 4 }}>
              These stores are currently in <b style={{ color: "#6b6b72" }}>{league.name}</b> but not assigned to any group.
            </div>
          </div>

          <div style={{
            marginTop: 16, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12,
          }}>
            {available.length === 0 ? (
              <div style={{
                gridColumn: "1 / -1", padding: "32px 16px", textAlign: "center",
                color: "#9a9aa1", fontSize: 13.5, border: "1.5px dashed #e5e5e9", borderRadius: 8,
              }}>
                Every store in this league is already assigned to a group.
              </div>
            ) : available.map((s) => (
              <GroupStoreSelectRow
                key={s.id}
                store={s}
                checked={!!selected[s.id]}
                onToggle={() => setSelected((prev) => ({ ...prev, [s.id]: !prev[s.id] }))}
              />
            ))}
          </div>
        </div>

        {/* Footer */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "16px 32px", borderTop: "1px solid #ececf0", gap: 12, marginTop: 16,
        }}>
          <div style={{ fontSize: 14, color: "#6b6b72" }}>
            <b style={{ color: "#0e0e10", fontWeight: 700 }}>{count}</b> selected
          </div>
          <button onClick={submit} disabled={!canCreate} style={{
            border: 0, borderRadius: 6, padding: "12px 28px",
            background: canCreate ? "#0e0e10" : "#e5e5e9",
            color: canCreate ? "#fff" : "#9a9aa1",
            fontSize: 14, fontWeight: 700, cursor: canCreate ? "pointer" : "not-allowed",
            transition: "background .15s",
          }}>Create Group</button>
        </div>
      </div>
    </Modal>
  );
}

/* ===== ASSET 10 : eaddf260-0dfd-4f79-832f-6d421c1464dc ===== */
// League Settings — full-page editor reached from the "League Settings" button
// on a league tab. Edit profile, manage members/roles, and league lifecycle.

const LS_GREEN = "#1f9d55";

// Floating-label outlined input (Material-style notch).
function FloatingField({ label, value, onChange, placeholder }) {
  const [focus, setFocus] = React.useState(false);
  return (
    <div style={{ position: "relative" }}>
      <label style={{
        position: "absolute", top: -8, left: 12, padding: "0 8px",
        background: "#fff", fontSize: 12.5, fontWeight: 500,
        color: focus ? "#0e0e10" : "#6b6b72", letterSpacing: ".01em",
      }}>{label}</label>
      <input
        value={value}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
        onFocus={() => setFocus(true)}
        onBlur={() => setFocus(false)}
        style={{
          width: "100%", padding: "16px 16px", fontSize: 15, borderRadius: 8,
          border: `1.5px solid ${focus ? "#0e0e10" : "#d4d4d8"}`, outline: "none",
          color: "#0e0e10", background: "#fff", transition: "border-color .12s",
        }}
      />
    </div>
  );
}

// Avatar disc with initials (or uploaded image).
function LeagueAvatar({ logo, name, color = "#1d3a8a", size = 110 }) {
  const initials = (name || "League").trim().split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase() || "LG";
  if (logo?.url) {
    return <img src={__asset(logo.url)} alt="" style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover" }} />;
  }
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%", background: color,
      color: "#fff", fontWeight: 700, fontSize: size * 0.3,
      display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
    }}>{initials}</div>
  );
}

// ─── Role badge ───
function RoleBadge({ role }) {
  const map = {
    Owner: { bg: LS_GREEN, color: "#fff" },
    Admin: { bg: "#f1f1f3", color: "#3a3a40" },
    Manager: { bg: "#f1f1f3", color: "#3a3a40" },
    Viewer: { bg: "#f1f1f3", color: "#3a3a40" },
  };
  const s = map[role] || map.Manager;
  return (
    <span style={{
      display: "inline-block", padding: "4px 16px", borderRadius: 999,
      fontSize: 13, fontWeight: 600, background: s.bg, color: s.color,
    }}>{role}</span>
  );
}

// ─── Member row action menu ───
function MemberMenu({ member, onRole, onRemove }) {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef();
  React.useEffect(() => {
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  const isOwner = member.role === "Owner";
  return (
    <div ref={ref} style={{ position: "relative", display: "inline-block" }}>
      <button onClick={() => setOpen((v) => !v)} style={{
        border: 0, background: "transparent", cursor: "pointer", color: "#6b6b72",
        width: 32, height: 32, borderRadius: 6, display: "inline-flex", alignItems: "center", justifyContent: "center",
      }}
        onMouseEnter={(e) => e.currentTarget.style.background = "#f1f1f3"}
        onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
        <span style={{ display: "inline-flex", gap: 4 }}>
          {[0, 1, 2].map((i) => <span key={i} style={{ width: 4, height: 4, borderRadius: "50%", background: "currentColor" }} />)}
        </span>
      </button>
      {open && (
        <div style={{
          position: "absolute", top: 40, right: 0, zIndex: 10,
          background: "#fff", border: "1px solid #ececf0", borderRadius: 8,
          boxShadow: "0 8px 24px rgba(20,20,30,.12)", padding: 4, minWidth: 168,
        }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#9a9aa1", padding: "8px 12px 4px", letterSpacing: ".04em" }}>SET ROLE</div>
          {["Admin", "Manager", "Viewer"].map((r) => (
            <div key={r} onClick={() => { onRole(r); setOpen(false); }} style={{
              padding: "8px 12px", fontSize: 13, cursor: "pointer", borderRadius: 5,
              display: "flex", alignItems: "center", justifyContent: "space-between", color: "#0e0e10",
            }}
              onMouseEnter={(e) => e.currentTarget.style.background = "#fafafb"}
              onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
              {r}
              {member.role === r && <IconCheck size={14} style={{ color: LS_GREEN, strokeWidth: 3 }} />}
            </div>
          ))}
          {!isOwner && (
            <React.Fragment>
              <div style={{ height: 1, background: "#f1f1f3", margin: "4px 0" }} />
              <div onClick={() => { onRemove(); setOpen(false); }} style={{
                padding: "8px 12px", fontSize: 13, cursor: "pointer", borderRadius: 5, color: "#b81d14",
                display: "inline-flex", alignItems: "center", gap: 8, width: "100%",
              }}
                onMouseEnter={(e) => e.currentTarget.style.background = "#fdf2f1"}
                onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
                <IconTrash size={14} /> Remove
              </div>
            </React.Fragment>
          )}
        </div>
      )}
    </div>
  );
}

// ─── Add Manager modal ───
function AddManagerModal({ open, onClose, onAdd }) {
  const [name, setName] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [role, setRole] = React.useState("Manager");
  React.useEffect(() => { if (open) { setName(""); setEmail(""); setRole("Manager"); } }, [open]);
  const canAdd = name.trim() && /\S+@\S+\.\S+/.test(email);
  return (
    <Modal open={open} onClose={onClose} width={460}>
      <div style={{ padding: "28px 28px" }}>
        <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Add Manager</h2>
        <p style={{ fontSize: 13.5, color: "#6b6b72", margin: "8px 0 24px" }}>Invite someone to help manage this league.</p>
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <FloatingField label="Full Name" value={name} onChange={setName} placeholder="Jane Smith" />
          <FloatingField label="Email" value={email} onChange={setEmail} placeholder="jane@example.com" />
          <div style={{ position: "relative" }}>
            <label style={{ position: "absolute", top: -8, left: 12, padding: "0 8px", background: "#fff", fontSize: 12.5, color: "#6b6b72" }}>Role</label>
            <select value={role} onChange={(e) => setRole(e.target.value)} style={{
              width: "100%", padding: "16px 40px 16px 16px", fontSize: 15, borderRadius: 8,
              border: "1.5px solid #d4d4d8", outline: "none", appearance: "none", background: "#fff", cursor: "pointer",
            }}>
              <option>Admin</option>
              <option>Manager</option>
              <option>Viewer</option>
            </select>
            <IconChevron size={18} style={{ position: "absolute", right: 16, top: "50%", transform: "translateY(-50%)", color: "#6b6b72", pointerEvents: "none" }} />
          </div>
        </div>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 28 }}>
          <button onClick={onClose} style={{
            border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10",
            padding: "12px 24px", borderRadius: 6, cursor: "pointer", fontSize: 14, fontWeight: 600,
          }}>Cancel</button>
          <button onClick={() => canAdd && onAdd({ name: name.trim(), email: email.trim(), role })} disabled={!canAdd} style={{
            border: 0, borderRadius: 6, padding: "12px 24px",
            background: canAdd ? "#0e0e10" : "#e5e5e9", color: canAdd ? "#fff" : "#9a9aa1",
            fontSize: 14, fontWeight: 700, cursor: canAdd ? "pointer" : "not-allowed",
          }}>Send Invite</button>
        </div>
      </div>
    </Modal>
  );
}

// ─── Card shell ───
function SettingsCard({ children, danger, style }) {
  return (
    <div style={{
      background: "#fff", border: `1px solid ${danger ? "#f3c9c5" : "#ececf0"}`, borderRadius: 14,
      padding: "32px 36px", boxShadow: "0 1px 2px rgba(20,20,30,.03)", ...style,
    }}>{children}</div>
  );
}

// ─────────── Main page ───────────
function LeagueSettings({ league, onBack, onSave, onDelete, onToast }) {
  const [name, setName] = React.useState(league?.name || "");
  const [location, setLocation] = React.useState(league?.location || "Perrisville, CA");
  const [logo, setLogo] = React.useState(league?.logo || null);
  const [members, setMembers] = React.useState(league?.members || []);
  const [showAdd, setShowAdd] = React.useState(false);
  const [confirmDelete, setConfirmDelete] = React.useState(false);
  const fileRef = React.useRef();

  React.useEffect(() => {
    setName(league?.name || "");
    setLocation(league?.location || "Perrisville, CA");
    setLogo(league?.logo || null);
    setMembers(league?.members || []);
  }, [league?.id]);

  if (!league) return null;

  const dirty = name !== league.name || location !== (league.location || "Perrisville, CA") || logo !== league.logo;

  const persistMembers = (next) => { setMembers(next); onSave(league.id, { members: next }, true); };
  const setRole = (id, role) => persistMembers(members.map((m) => m.id === id ? { ...m, role } : m));
  const removeMember = (id) => persistMembers(members.filter((m) => m.id !== id));
  const addMember = (m) => {
    persistMembers([...members, { id: "m-" + Date.now(), ...m }]);
    setShowAdd(false);
    onToast(`Invite sent to ${m.email}`);
  };

  const save = () => { onSave(league.id, { name: name.trim() || league.name, location, logo }); onToast("League profile updated"); };
  const cancel = () => { setName(league.name); setLocation(league.location || "Perrisville, CA"); setLogo(league.logo || null); };

  return (
    <div style={{ flex: 1, padding: "28px 40px 120px", background: "#fafafb" }}>
      {/* Back link */}
      <button onClick={onBack} style={{
        border: 0, background: "transparent", cursor: "pointer", color: "#6b6b72",
        display: "inline-flex", alignItems: "center", gap: 8, fontSize: 14, fontWeight: 500, padding: 0, marginBottom: 16,
      }}
        onMouseEnter={(e) => e.currentTarget.style.color = "#0e0e10"}
        onMouseLeave={(e) => e.currentTarget.style.color = "#6b6b72"}>
        <IconChevronLeft size={18} /> Back to League Page
      </button>

      <h1 style={{ fontSize: 30, fontWeight: 800, margin: 0, color: "#0e0e10" }}>League Settings</h1>
      <p style={{ fontSize: 15, color: "#6b6b72", margin: "8px 0 0" }}>
        Manage {league.name} preferences, members, and lifecycle.
      </p>

      <div style={{ maxWidth: 1180, margin: "32px auto 0", display: "flex", flexDirection: "column", gap: 28 }}>
        {/* ─── League Profile ─── */}
        <SettingsCard>
          <h2 style={{ fontSize: 21, fontWeight: 800, margin: 0, color: "#0e0e10" }}>League Profile</h2>
          <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 28px" }}>Update your league's public identity.</p>

          <div style={{ display: "grid", gridTemplateColumns: "auto 1fr", gap: 36, alignItems: "start" }}>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 16 }}>
              <LeagueAvatar logo={logo} name={name} color={league.avatarColor || "#1d3a8a"} />
              <input ref={fileRef} type="file" accept="image/*" style={{ display: "none" }}
                onChange={(e) => { const f = e.target.files?.[0]; if (f) setLogo({ url: URL.createObjectURL(f), name: f.name }); }} />
              <button onClick={() => fileRef.current?.click()} style={{
                border: "1px solid #d4d4d8", background: "#fff", borderRadius: 8, padding: "8px 16px",
                fontSize: 14, fontWeight: 600, cursor: "pointer", color: "#0e0e10",
                display: "inline-flex", alignItems: "center", gap: 8,
              }}>
                <IconUpload size={15} /> Change
              </button>
              {logo && (
                <button onClick={() => setLogo(null)} style={{
                  border: 0, background: "transparent", color: "#b81d14", fontSize: 14, fontWeight: 600, cursor: "pointer", padding: 0,
                }}>Remove</button>
              )}
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
              <FloatingField label="League Name" value={name} onChange={setName} placeholder="League name" />
              <FloatingField label="Location" value={location} onChange={setLocation} placeholder="City, State" />
              <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 4 }}>
                <button onClick={cancel} disabled={!dirty} style={{
                  border: "1px solid #d4d4d8", background: "#fff", color: dirty ? "#0e0e10" : "#9a9aa1",
                  padding: "12px 28px", borderRadius: 8, cursor: dirty ? "pointer" : "default", fontSize: 14, fontWeight: 600,
                }}>Cancel</button>
                <button onClick={save} disabled={!dirty} style={{
                  border: 0, borderRadius: 8, padding: "12px 28px",
                  background: dirty ? "#0e0e10" : "#e5e5e9", color: dirty ? "#fff" : "#9a9aa1",
                  fontSize: 14, fontWeight: 700, cursor: dirty ? "pointer" : "default",
                }}>Save Changes</button>
              </div>
            </div>
          </div>
        </SettingsCard>

        {/* ─── Member Management ─── */}
        <SettingsCard>
          <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 24 }}>
            <div>
              <h2 style={{ fontSize: 21, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Member Management</h2>
              <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 0" }}>League managers can configure stores and invite others.</p>
            </div>
            <button onClick={() => setShowAdd(true)} style={{
              border: 0, background: "#0e0e10", color: "#fff", borderRadius: 8, padding: "12px 20px",
              fontSize: 14, fontWeight: 700, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 8, flexShrink: 0,
            }}>
              <IconPlus size={16} style={{ strokeWidth: 2.4 }} /> Add Manager
            </button>
          </div>

          <div style={{ border: "1px solid #ececf0", borderRadius: 12, overflow: "hidden" }}>
            {/* Table header */}
            <div style={{
              display: "grid", gridTemplateColumns: "1.4fr 1.6fr .8fr 80px", gap: 12,
              padding: "16px 24px", background: "#fafafb", borderBottom: "1px solid #ececf0",
              fontSize: 14, fontWeight: 600, color: "#6b6b72",
            }}>
              <div>User</div><div>Email</div><div>Role</div><div style={{ textAlign: "right" }}>Actions</div>
            </div>
            {members.length === 0 ? (
              <div style={{ padding: "28px", textAlign: "center", color: "#9a9aa1", fontSize: 14 }}>No members yet.</div>
            ) : members.map((m, i) => (
              <div key={m.id} style={{
                display: "grid", gridTemplateColumns: "1.4fr 1.6fr .8fr 80px", gap: 12, alignItems: "center",
                padding: "16px 24px", borderBottom: i < members.length - 1 ? "1px solid #f1f1f3" : "none",
              }}>
                <div style={{ display: "inline-flex", alignItems: "center", gap: 16, minWidth: 0 }}>
                  <div style={{
                    width: 44, height: 44, borderRadius: "50%", flexShrink: 0,
                    background: m.color || "#1d3a8a", color: "#fff", fontWeight: 700, fontSize: 14,
                    display: "inline-flex", alignItems: "center", justifyContent: "center",
                  }}>{m.name.split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase()}</div>
                  <span style={{ fontSize: 15, fontWeight: 700, color: "#0e0e10" }}>{m.name}</span>
                </div>
                <div style={{ fontSize: 14.5, color: "#6b6b72", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{m.email}</div>
                <div><RoleBadge role={m.role} /></div>
                <div style={{ textAlign: "right" }}>
                  <MemberMenu member={m} onRole={(r) => setRole(m.id, r)} onRemove={() => removeMember(m.id)} />
                </div>
              </div>
            ))}
          </div>
        </SettingsCard>

        {/* ─── Danger Zone ─── */}
        <SettingsCard danger>
          <h2 style={{ fontSize: 21, fontWeight: 800, margin: 0, color: "#b81d14" }}>Danger Zone</h2>
          <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 0" }}>
            Deleting a league is permanent. Its team stores are kept but moved back to All Stores.
          </p>
          <div style={{
            display: "flex", alignItems: "center", justifyContent: "space-between",
            marginTop: 20, padding: "16px 24px", border: "1px solid #f3c9c5", borderRadius: 10, background: "#fdf6f5",
          }}>
            <div>
              <div style={{ fontSize: 15, fontWeight: 700, color: "#0e0e10" }}>Delete this league</div>
              <div style={{ fontSize: 13.5, color: "#6b6b72", marginTop: 2 }}>Removes {league.name} and all of its groups.</div>
            </div>
            {confirmDelete ? (
              <div style={{ display: "inline-flex", gap: 12, alignItems: "center" }}>
                <span style={{ fontSize: 13.5, color: "#6b6b72" }}>Are you sure?</span>
                <button onClick={() => setConfirmDelete(false)} style={{
                  border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10", borderRadius: 8, padding: "12px 16px",
                  fontSize: 14, fontWeight: 600, cursor: "pointer",
                }}>Cancel</button>
                <button onClick={() => onDelete(league.id)} style={{
                  border: 0, background: "#b81d14", color: "#fff", borderRadius: 8, padding: "12px 16px",
                  fontSize: 14, fontWeight: 700, cursor: "pointer",
                }}>Yes, delete</button>
              </div>
            ) : (
              <button onClick={() => setConfirmDelete(true)} style={{
                border: "1px solid #e1251b", background: "#fff", color: "#b81d14", borderRadius: 8, padding: "12px 24px",
                fontSize: 14, fontWeight: 700, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 8, flexShrink: 0,
              }}>
                <IconTrash size={15} /> Delete League
              </button>
            )}
          </div>
        </SettingsCard>
      </div>

      <AddManagerModal open={showAdd} onClose={() => setShowAdd(false)} onAdd={addMember} />
    </div>
  );
}

Object.assign(window, { LeagueSettings });


/* ===== ASSET 11 : 2ce2edef-0aeb-49d8-987b-1358931f03ea ===== */
// Stores — high-density card grid of every team store the admin manages.
// Doubles as the drill-down view when a single league is opened from Leagues.

const STATE_ABBR = { Louisiana: "LA", California: "CA", Texas: "TX", "New York": "NY", Florida: "FL", Washington: "WA", Oregon: "OR", Nevada: "NV", Arizona: "AZ", Colorado: "CO", Illinois: "IL", Massachusetts: "MA", Georgia: "GA", Ohio: "OH", Michigan: "MI", "North Carolina": "NC", "South Carolina": "SC", Virginia: "VA", Pennsylvania: "PA" };

function StoreList({ stores, onAdd, onAddLeague, onAddGroup, onManage, onArchive, onCreateTemplate, leagues = [], activeLeagueId, onSelectLeague, activeGroupId, onOpenGroup, onCloseGroup, onOpenSettings, onBackToLeagues, zeroState = false }) {
  // Zero-state usability test: strip the top-level stores landing to a true
  // first-run milestone — no cards, pills, org labels or ownership counts.
  const zeroTop = zeroState && !activeLeagueId;
  const [ownership, setOwnership] = React.useState("all");
  const [sort, setSort] = React.useState("Name (A-Z)");
  const [filter, setFilter] = React.useState("All");
  const [search, setSearch] = React.useState("");

  const activeLeague = leagues.find((l) => l.id === activeLeagueId);
  const groups = activeLeague?.groups || [];
  const activeGroup = activeGroupId ? groups.find((g) => g.id === activeGroupId) : null;

  const leagueStores = activeLeague ? stores.filter((s) => activeLeague.storeIds.includes(s.id)) : stores;

  let visibleStores;
  if (activeGroup) {
    visibleStores = leagueStores.filter((s) => activeGroup.storeIds.includes(s.id));
  } else if (activeLeague) {
    const grouped = new Set(groups.flatMap((g) => g.storeIds || []));
    visibleStores = leagueStores.filter((s) => !grouped.has(s.id));
  } else {
    visibleStores =
      ownership === "mine" ? stores.filter((s) => s.ownership === "mine") :
      ownership === "joined" ? stores.filter((s) => s.ownership === "joined") :
      stores; // "all" — every storefront accessible to the logged-in user
  }

  // ─── Toolbar sort + filter ───
  // Options are derived from the stores currently in scope so a choice never
  // points at data that isn't present.
  const scopePool = activeLeague ? leagueStores : stores;
  const nameOf = (s) => (s.storeTitle || s.teamName || "").toLowerCase();
  const sportsPresent = [...new Set(scopePool.map((s) => s.sport).filter(Boolean))].sort();
  const citiesPresent = [...new Set(scopePool.map((s) => s.shipCity).filter(Boolean))].sort();
  const hasHold = scopePool.some((s) => (s.status || "active") === "hold");

  const storeSortOptions = ["Name (A-Z)", "Name (Z-A)", "Revenue (high to low)", "Revenue (low to high)"];
  const storeFilterOptions = [
    "All",
    { label: "Status", sub: hasHold ? ["Open", "On Hold"] : ["Open"] },
    ...(sportsPresent.length ? [{ label: "Sport", sub: sportsPresent }] : []),
    ...(citiesPresent.length ? [{ label: "Location", sub: citiesPresent }] : []),
  ];
  const matchesFilter = (s) => {
    switch (filter) {
      case "All": return true;
      case "Open": return (s.status || "active") !== "hold";
      case "On Hold": return (s.status || "active") === "hold";
      default:
        if (sportsPresent.includes(filter)) return (s.sport || "") === filter;
        if (citiesPresent.includes(filter)) return (s.shipCity || "") === filter;
        return true;
    }
  };
  const applySort = (arr) => {
    const a = [...arr];
    if (sort === "Name (A-Z)") a.sort((x, y) => nameOf(x).localeCompare(nameOf(y)));
    else if (sort === "Name (Z-A)") a.sort((x, y) => nameOf(y).localeCompare(nameOf(x)));
    else if (sort === "Revenue (high to low)") a.sort((x, y) => (y.revenue || 0) - (x.revenue || 0));
    else if (sort === "Revenue (low to high)") a.sort((x, y) => (x.revenue || 0) - (y.revenue || 0));
    return a;
  };
  const matchesSearch = (s) => {
    const q = search.trim().toLowerCase();
    if (!q) return true;
    return [s.storeTitle, s.teamName, s.sport, s.shipCity].some((v) => (v || "").toLowerCase().includes(q));
  };
  const finalStores = zeroTop ? [] : applySort(visibleStores.filter(matchesFilter).filter(matchesSearch));

  const storeToolbar = (
    <ListToolbar
      searchPlaceholder="Search Team Stores"
      searchValue={search}
      onSearch={setSearch}
      filter={{ value: filter, options: storeFilterOptions, onChange: setFilter, width: 232 }}
      sort={{ value: sort, options: storeSortOptions, onChange: setSort, width: 224 }} />
  );

  const scopeStores = activeGroup ? visibleStores : leagueStores;
  const totalRevenue = (activeLeague ? scopeStores : finalStores).reduce((sum, s) => sum + (s.revenue || 0), 0);
  const storeCount = activeLeague ? scopeStores.length : finalStores.length;

  return (
    <div style={{ flex: 1, minWidth: 0, padding: "28px max(32px, calc((100% - 1376px)/2)) 120px", background: "#fbfbfc", position: "relative" }}>
      {/* Header */}
      {activeLeague ? (
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 24, gap: 16, flexWrap: "wrap" }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, fontSize: 13 }}>
              <button onClick={onBackToLeagues} style={{ border: 0, background: "transparent", padding: 0, cursor: "pointer", color: "#9a9aa1", fontWeight: 700, letterSpacing: ".04em" }}>LEAGUES</button>
              <IconChevronRight size={14} style={{ color: "#c9c9cf" }} />
              {activeGroup ? (
                <React.Fragment>
                  <button onClick={onCloseGroup} style={{ border: 0, background: "transparent", padding: 0, cursor: "pointer", color: "#9a9aa1", fontWeight: 700, letterSpacing: ".04em" }}>{(activeLeague.name || "LEAGUE").toUpperCase()}</button>
                  <IconChevronRight size={14} style={{ color: "#c9c9cf" }} />
                  <span style={{ fontWeight: 800, color: "#0e0e10" }}>{activeGroup.name.toUpperCase()}</span>
                </React.Fragment>
              ) : (
                <span style={{ fontWeight: 800, color: "#0e0e10" }}>{activeLeague.name.toUpperCase()}</span>
              )}
            </div>
            <h1 style={{ fontFamily: "Archivo, sans-serif", fontSize: 24, fontWeight: 800, margin: 0, color: "#0e0e10", letterSpacing: "-.3px" }}>{activeGroup ? activeGroup.name : activeLeague.name}</h1>
            <div style={{ display: "flex", gap: 24, alignItems: "center", color: "#6b6b72", fontSize: 13.5, marginTop: 8 }}>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><IconStore size={16} /> {storeCount} {storeCount === 1 ? "Store" : "Stores"}</span>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><IconDollar size={16} style={{ color: "#1f9d55" }} /><span style={{ color: "#1f9d55", fontWeight: 700 }}>${totalRevenue.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}</span></span>
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            {!activeGroup && (
              <button onClick={onOpenSettings} style={{ border: "1px solid #d8d8de", background: "#fff", color: "#0e0e10", borderRadius: 8, padding: "12px 16px", cursor: "pointer", fontSize: 13.5, fontWeight: 600, display: "inline-flex", alignItems: "center", gap: 8 }}>
                <IconSettings size={17} /> League Settings
              </button>
            )}
            {storeToolbar}
          </div>
        </div>
      ) : (
        <ListPageHeader title="Stores" subtitle={(() => { const inLeague = new Set(leagues.flatMap((l) => l.storeIds || [])); const teamN = stores.filter((s) => !inLeague.has(s.id)).length; return `${teamN} Team Stores \u2022 ${stores.length - teamN} League Stores`; })()}>
          <button onClick={onAdd} style={{ display: "inline-flex", alignItems: "center", gap: 8, background: "#0e0e10", border: 0, borderRadius: 8, padding: "12px 16px", cursor: "pointer", fontSize: 13.5, fontWeight: 700, color: "#fff", whiteSpace: "nowrap" }}>
            <IconPlus size={16} style={{ strokeWidth: 2.4 }} /> Add Store
          </button>
          {storeToolbar}
        </ListPageHeader>
      )}

      {/* Ownership filter — only at the top-level stores view */}
      {!activeLeague && !zeroTop && (
        <SegmentedPills value={ownership} onChange={setOwnership} style={{ marginBottom: 24 }} items={[
          { id: "all", label: "All Stores", count: stores.length },
          { id: "mine", label: "My Stores", count: stores.filter((s) => s.ownership === "mine").length },
          { id: "joined", label: "Joined Stores", count: stores.filter((s) => s.ownership === "joined").length },
        ]} />
      )}

      {/* Cards grid */}
      {zeroTop ? (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: "92px 20px 40px" }}>
          <div style={{ width: 152, height: 152, borderRadius: "50%", background: "#f5f5f7", border: "1px solid #ececf0", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 32 }}>
            <svg width="78" height="78" viewBox="0 0 64 64" fill="none" stroke="#a1a1aa" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              {/* Storefront awning + shutter — empty retail rack */}
              <path d="M8 24 L12 12 H52 L56 24" />
              <path d="M8 24 v28 a2 2 0 0 0 2 2 h44 a2 2 0 0 0 2 -2 V24" />
              <path d="M8 24 h48" />
              <path d="M20 24 v-3 M32 24 v-3 M44 24 v-3" opacity="0.55" />
              <path d="M24 54 V38 a8 8 0 0 1 16 0 V54" />
            </svg>
          </div>
          <h2 style={{ fontFamily: "Archivo, sans-serif", fontSize: 24, fontWeight: 800, color: "#0e0e10", margin: "0 0 12px", letterSpacing: "-.01em" }}>You don&rsquo;t have any Team Stores yet.</h2>
          <p style={{ fontSize: 15, color: "#6b6b72", lineHeight: 1.6, maxWidth: 460, margin: "0 0 28px" }}>Create an always-on locker or a temporary pop-up store to start assigning customized gear collections to your teams.</p>
          <button onClick={onAdd} style={{ display: "inline-flex", alignItems: "center", gap: 8, background: "#0e0e10", color: "#fff", border: 0, borderRadius: 8, padding: "16px 28px", fontSize: 15, fontWeight: 700, cursor: "pointer" }}
            onMouseEnter={(e) => (e.currentTarget.style.background = "#1f1f22")}
            onMouseLeave={(e) => (e.currentTarget.style.background = "#0e0e10")}>
            <IconPlus size={18} style={{ strokeWidth: 2.6 }} /> Create Your First Store
          </button>
        </div>
      ) : (
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(248px, 1fr))", gap: 16 }}>
        {activeLeague && !activeGroup && groups.map((g) => <GroupCard key={g.id} group={g} onOpen={() => onOpenGroup(g.id)} />)}
        {finalStores.map((s) => <StoreCard key={s.id} store={s} onManage={() => onManage(s.id)} onArchive={() => onArchive && onArchive(s.id)} onCreateTemplate={onCreateTemplate} />)}
        {finalStores.length === 0 && !(activeLeague && !activeGroup && groups.length) && (
          <div style={{ gridColumn: "1 / -1", padding: "92px 20px", textAlign: "center", color: "#9a9aa1", fontSize: 14 }}>
            {filter !== "All" ? `No stores match “${filter}”.` :
             ownership === "mine" ? "You haven’t created any stores yet." : ownership === "joined" ? "No stores have been shared with you yet." : "No stores here yet."}
          </div>
        )}
      </div>
      )}

      {/* Floating actions — Add Group only (Add Store moved to toolbar) */}
      {activeLeague && (
        <div style={{ position: "fixed", bottom: 28, right: 36, zIndex: 40, display: "flex", alignItems: "center", gap: 12 }}>
          <button onClick={onAddGroup} style={{ background: "#fff", color: "#0e0e10", border: "1px solid #d4d4d8", padding: "16px 24px", borderRadius: 8, cursor: "pointer", fontSize: 13, fontWeight: 800, letterSpacing: ".06em", display: "inline-flex", alignItems: "center", gap: 8, boxShadow: "0 8px 20px rgba(20,20,30,.12)" }}>
            <IconGroupAdd size={17} /> Add Group
          </button>
        </div>
      )}
    </div>
  );
}

// Group card — sits at the front of a league grid; opens the group's stores.
function GroupCard({ group, onOpen }) {
  const count = (group.storeIds || []).length;
  return (
    <div style={{ background: "#fff", border: "1px solid #ececf0", borderRadius: 10, overflow: "hidden", boxShadow: "0 1px 2px rgba(20,20,30,.03)", display: "flex", flexDirection: "column", transition: "box-shadow .15s ease, border-color .15s ease" }}
      onMouseEnter={(e) => { e.currentTarget.style.boxShadow = "0 8px 22px rgba(20,20,30,.09)"; e.currentTarget.style.borderColor = "#d4d4d8"; }}
      onMouseLeave={(e) => { e.currentTarget.style.boxShadow = "0 1px 2px rgba(20,20,30,.03)"; e.currentTarget.style.borderColor = "#ececf0"; }}>
      <div style={{ position: "relative", background: "#fafafb", padding: "20px", minHeight: 172, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ position: "absolute", top: 16, left: 16, background: "#e3edff", color: "#2657c4", padding: "4px 12px", borderRadius: 999, fontSize: 11, fontWeight: 700 }}>Group</div>
        <div style={{ width: 92, height: 92, borderRadius: "50%", background: "#ececf0", color: "#6b6b72", display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
          <IconGrid size={32} stroke={1.7} />
        </div>
      </div>
      <div style={{ padding: "16px 16px 16px", textAlign: "center" }}>
        <div style={{ fontSize: 15, fontWeight: 800, marginBottom: 4, color: "#0e0e10" }}>{group.name}</div>
        <div style={{ fontSize: 12.5, color: "#9a9aa1" }}>{count} {count === 1 ? "team" : "teams"}</div>
      </div>
      <div style={{ borderTop: "1px solid #ececf0", padding: 16 }}>
        <button onClick={onOpen} style={{ width: "100%", background: "#fff", border: "1px solid #0e0e10", color: "#0e0e10", padding: "12px 16px", borderRadius: 6, fontSize: 13, fontWeight: 700, cursor: "pointer", transition: "all .12s" }}
          onMouseEnter={(e) => { e.currentTarget.style.background = "#0e0e10"; e.currentTarget.style.color = "#fff"; }}
          onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; e.currentTarget.style.color = "#0e0e10"; }}>
          Open Group
        </button>
      </div>
    </div>
  );
}

function ArchiveStoreModal({ open, store, onClose, onConfirm }) {
  if (!store) return null;
  return (
    <Modal open={open} onClose={onClose} width={480}>
      <div style={{ padding: "28px 28px 8px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
          <span style={{ width: 40, height: 40, borderRadius: "50%", background: "#fbe3e1", color: "#b81d14", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <IconAlert size={19} style={{ strokeWidth: 2.2 }} />
          </span>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>Archive {store.teamName || store.storeTitle}?</h2>
        </div>
        <p style={{ margin: "0 0 12px", fontSize: 13.5, color: "#6b6b72", lineHeight: 1.6 }}>Archiving a store will:</p>
        <ul style={{ margin: "0 0 4px", paddingLeft: 20, fontSize: 13.5, color: "#0e0e10", lineHeight: 1.85 }}>
          <li>Hide the storefront from all buyers immediately</li>
          <li>Stop all new orders and close any active ordering window</li>
          <li>Remove it from your active stores list</li>
        </ul>
        <p style={{ margin: "12px 0 0", fontSize: 13, color: "#6b6b72", lineHeight: 1.6 }}>Order history and reports are retained. This can be undone by support.</p>
      </div>
      <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
        <Button variant="secondary" onClick={onClose}>Cancel</Button>
        <button onClick={onConfirm} style={{
          display: "inline-flex", alignItems: "center", gap: 8, background: "#e1251b", border: 0,
          borderRadius: 6, padding: "12px 20px", fontSize: 14, fontWeight: 700, color: "#fff", cursor: "pointer", fontFamily: "inherit",
        }}>
          <IconTrash size={14} style={{ strokeWidth: 2.2 }} /> Archive Store
        </button>
      </div>
    </Modal>
  );
}

function RestoreStoreModal({ open, store, onClose, onConfirm }) {
  if (!store) return null;
  return (
    <Modal open={open} onClose={onClose} width={480}>
      <div style={{ padding: "28px 28px 8px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
          <span style={{ width: 40, height: 40, borderRadius: "50%", background: "#e7f5ed", color: "#1f7a44", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <IconCheck size={19} style={{ strokeWidth: 2.4 }} />
          </span>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>Restore {store.teamName || store.storeTitle}?</h2>
        </div>
        <p style={{ margin: "0 0 12px", fontSize: 13.5, color: "#6b6b72", lineHeight: 1.6 }}>Restoring this store will:</p>
        <ul style={{ margin: "0 0 4px", paddingLeft: 20, fontSize: 13.5, color: "#0e0e10", lineHeight: 1.85 }}>
          <li>Move it back into your active stores list</li>
          <li>Return it as a draft so you can review before re-opening</li>
          <li>Keep all retained order history and reports intact</li>
        </ul>
        <p style={{ margin: "12px 0 0", fontSize: 13, color: "#6b6b72", lineHeight: 1.6 }}>The storefront stays closed to buyers until you re-open it.</p>
      </div>
      <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
        <Button variant="secondary" onClick={onClose}>Cancel</Button>
        <button onClick={onConfirm} style={{
          display: "inline-flex", alignItems: "center", gap: 8, background: "#0e0e10", border: 0,
          borderRadius: 6, padding: "12px 20px", fontSize: 14, fontWeight: 700, color: "#fff", cursor: "pointer", fontFamily: "inherit",
        }}>
          <IconCheck size={15} style={{ strokeWidth: 2.4 }} /> Restore Store
        </button>
      </div>
    </Modal>
  );
}

