  const [filter, setFilter] = useStateCF("all"); // "all" | "favorites" | "recent"

  useEffectCF(() => {
    if (!open) return;
    const h = (e) => {if (e.key === "Escape") onClose();};
    window.addEventListener("keydown", h);
    document.body.style.overflow = "hidden";
    return () => {window.removeEventListener("keydown", h);document.body.style.overflow = "";};
  }, [open, onClose]);

  if (!open) return null;

  const handleFile = (file) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    const next = { id: "up-" + Date.now(), name: file.name.replace(/\.[^.]+$/, ""), url, favorite: false, recent: true };
    setLogos((l) => [next, ...l]);
    onSelect({ name: next.name, url });
  };

  const toggleFav = (id) => setLogos((l) => l.map((x) => x.id === id ? { ...x, favorite: !x.favorite } : x));

