function LogoDropZone({ logo, onChange }) {
  const [drag, setDrag] = useStateCF(false);
  const [libOpen, setLibOpen] = useStateCF(false);
  const handleFile = (file) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    onChange({ name: file.name, url });
  };
  return (
    <>
    <div
        onClick={!logo ? () => setLibOpen(true) : undefined}
        onDragOver={(e) => {e.preventDefault();setDrag(true);}}
        onDragLeave={() => setDrag(false)}
        onDrop={(e) => {e.preventDefault();setDrag(false);handleFile(e.dataTransfer.files[0]);}}
        style={{
          width: 56, height: 56, borderRadius: 4,
          border: `1px ${logo ? "solid" : "dashed"} ${drag ? "#0e0e10" : logo ? "#d4d4d8" : "#9a9aa1"}`,
          background: drag ? "#fafafb" : logo ? "#fff" : "#fff",
          display: "inline-flex", alignItems: "center", justifyContent: "center",
          cursor: "pointer", position: "relative", overflow: "hidden"
        }}>
      {logo ?
        <>
          {logo.url ?
          <img src={__asset(logo.url)} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> :

          <div style={{
            width: "100%", height: "100%", background: logo.color || "#0e0e10", color: "#fff",
            display: "inline-flex", alignItems: "center", justifyContent: "center",
            fontSize: 18, fontWeight: 800
          }}>{logo.mono || "?"}</div>
          }
          <button onClick={(e) => {e.stopPropagation();onChange(null);}} title="Remove logo" style={{
            position: "absolute", top: -8, right: -8, width: 16, height: 16,
            borderRadius: "50%", background: "#0e0e10", color: "#fff",
            border: "1.5px solid #fff", padding: 0,
            display: "inline-flex", alignItems: "center", justifyContent: "center",
            cursor: "pointer"
          }}>
            <IconX size={10} />
          </button>
        </> :

        <IconPlus size={18} style={{ color: "#6b6b72" }} />
        }
    </div>
    <MyLogosModal
        open={libOpen}
        onClose={() => setLibOpen(false)}
        onSelect={(l) => {onChange(l);setLibOpen(false);}} />
    </>);

}


// ───────────────────────── 6-step wizard shell ─────────────────────────
// Reusable card wrapper (kept for back-compat with any callers).
function Section({ title, intro, children, action }) {
  return (
    <div style={{
      background: "#fff", border: "1px solid #ececf0", borderRadius: 8,
      padding: 28, marginBottom: 24, boxShadow: "0 1px 2px rgba(20,20,30,.03)"
    }}>
      <div style={{ marginBottom: 24, display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 24 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <h2 style={{ fontSize: 16, fontWeight: 700, margin: 0, marginBottom: 8, color: "#0e0e10" }}>{title}</h2>
          {intro && <p style={{ fontSize: 13, color: "#6b6b72", margin: 0, lineHeight: 1.55 }}>{intro}</p>}
        </div>
        {action && <div style={{ flexShrink: 0 }}>{action}</div>}
      </div>
      {children}
    </div>);

}

function buildWizardData(presetData) {
  const p = presetData || {};
  return {
    // Core branching flag — "league" (Multi-Team Hub) unlocks the division →
    // team canvas, product-to-team assignment, and team-manager mapping. "single"
    // (Single-Team Locker) enforces one roster and the streamlined flow.
    storeType: p.storeType || "",
    rosterAssignments: p.rosterAssignments || {},
    fundraisingEnabled: p.fundraisingEnabled ?? false,
    // existing store fields (carried through to finalize / dashboard)
    storeTitle: p.storeTitle || "",
    teamName: p.teamName || "",
    teamColors: p.teamColors || [],
    teamLogo: p.teamLogo || null,
    sport: p.sport || "",
    contactPref: p.contactPref || "Email & Phone",
    email: p.email || "",
    phone: p.phone || "",
    storeOpenMode: p.storeOpenMode || "set-window",
    storeOpenStart: p.storeOpenStart || "",
    storeOpenEnd: p.storeOpenEnd || "",
    // team + sport
    connectedTeam: p.connectedTeam || "",
    sports: p.sports || [],
    // store point of contact
    contactEmailMode: p.contactEmailMode || "",
    contactEmailSalesperson: p.contactEmailSalesperson || "",
    contactEmailCustom: p.contactEmailCustom || "",
    contactPhoneMode: p.contactPhoneMode || "",
    contactPhoneSalesperson: p.contactPhoneSalesperson || "",
    contactPhoneCustom: p.contactPhoneCustom || "",
    shipName: p.shipName || "",
    shipStreet: p.shipStreet || "",
    shipCity: p.shipCity || "",
    shipState: p.shipState || "",
    shipZip: p.shipZip || "",
    shipCountry: p.shipCountry || "United States",
    shipOption: p.shipOption || "",
    collectTax: p.collectTax !== false,
    taxRate: p.taxRate || "",
    // new wizard fields
    distributionFormat: p.distributionFormat || "",
    storeSlug: p.storeSlug || slugify(p.storeTitle || ""),
    _slugTouched: !!p.storeSlug,
    managerName: p.managerName || p.shipName || "",
    urgencyTimers: p.urgencyTimers != null ? p.urgencyTimers : true,
    distributionModel: p.distributionModel || "",
    curatedProducts: p.curatedProducts || [],
    // Step 1 additions — none are required; all have working defaults.
    allowDuplicateNumbers: p.allowDuplicateNumbers ?? false,
    numberSelection: p.numberSelection || "manager",
    additionalManagers: p.additionalManagers || [],
    shipApt: p.shipApt || "",
    // League Step 2 — Divisions & Teams (same shape as the workspace org).
    leagueStructure: p.leagueStructure || { groups: [], loose: [] },
    collectPlayerName: p.collectPlayerName != null ? p.collectPlayerName : true,
    collectRosterNumber: p.collectRosterNumber != null ? p.collectRosterNumber : true,
    taxMode: p.taxMode || (p.collectTax === false ? "exempt" : "zip"),
    flatTaxRate: p.flatTaxRate || "",
    taxState: p.taxState || "",
    taxLiabilityAgreed: p.taxLiabilityAgreed != null ? p.taxLiabilityAgreed : false,
    heroTheme: p.heroTheme || "pitch",
    primaryColor: p.primaryColor || p.teamColors && p.teamColors[1] || "#e1251b",
    announcement: p.announcement || "",
    // User-generated-template flow markers (Path B)
    _fromUserTemplate: !!p._fromUserTemplate,
    _templateName: p._templateName || "",
    _templateBlocks: p._templateBlocks || null,
    // Vault-launch flow marker (Stock Vault → "Start store with selected")
    _fromVault: !!p._fromVault
  };
}

function CreateForm({ onCancel, onSubmit, presetData, accent = "#e1251b", athletes = 30, templateMode = false, liveStores }) {
  const [data, setData] = useStateCF(() => buildWizardData(presetData));
  // One source of truth for every step number, badge, and label: the list is
  // store-type dependent (League = 4 steps, Individual = 3). No hardcoded totals.
  const baseSteps = wizardStepsFor(data.storeType);
  const STEPS = (templateMode || data._skipProducts) ? baseSteps.filter((s) => s.key !== "products") : baseSteps;
  // Divisions & Teams structure (League Step 2) — same shape as the workspace org.
  const setStructure = (fn) => setData((d) => {
    const cur = d.leagueStructure || { groups: [], loose: [] };
    const next = typeof fn === "function" ? fn(cur) : fn;
    return { ...d, leagueStructure: { groups: next.groups || [], loose: next.loose || [] } };
  });
  // Keep indices valid when the step list shrinks (League → Individual).
  React.useEffect(() => {
    if (step > STEPS.length - 1) setStep(STEPS.length - 1);
    if (maxReached > STEPS.length - 1) setMaxReached(STEPS.length - 1);
  }, [STEPS.length]);
  // A store started from another store lands on Review & Deploy with every earlier step reachable.
  const [step, setStep] = useStateCF(() => data._startAt === "review" ? STEPS.length - 1 : 0);
  // Vault launches arrive with Step 2 already complete — reachable + review-optional.
  const [maxReached, setMaxReached] = useStateCF(() => data._startAt === "review" ? STEPS.length - 1 : (presetData && presetData._fromVault ? 1 : 0));
  const [errors, setErrors] = useStateCF({});
  const set = (patch) => setData((d) => ({ ...d, ...patch }));

  const scrollTop = () => {
    const el = document.getElementById("wizard-scroll");
    if (el && el.scrollHeight > el.clientHeight + 4) el.scrollTo({ top: 0, behavior: "smooth" });
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const validateStep = (s) => {
    const e = {};
    if ((STEPS[s] || {}).key === "basics") {
      if (!data.storeTitle || !data.storeTitle.trim()) e.storeTitle = "Store name is required";
      if (!data.storeSlug || !data.storeSlug.trim()) e.storeSlug = "Web address is required";
      // Team Manager is the default point-of-contact source — any channel left on
      // that mode makes the corresponding record field required (error lands HERE).
      const emMode = data.contactEmailMode === "service" ? "teammanager" : (data.contactEmailMode || "");
      const phMode = data.contactPhoneMode === "service" ? "teammanager" : (data.contactPhoneMode || "");
      if (!emMode) e.contactEmailMode = "Select an email point of contact";
      if (!phMode) e.contactPhoneMode = "Select a phone point of contact";
      if (!data.storeType) e.storeType = "Select a store type";
      if (!data.distributionFormat) e.distributionFormat = "Select a store schedule";
      if (!data.distributionModel) e.distributionModel = "Select a fulfillment method";
      if (emMode === "teammanager" && !isValidEmail(data.email)) e.email = "Required — the store's point of contact follows this record";
      if (phMode === "teammanager" && !isValidPhone(data.phone)) e.phone = "Enter a 10-digit phone — the store's point of contact follows this record";
      if (data.distributionFormat === "popup") {
        if (!data.storeOpenStart) e.storeOpenStart = "Launch date is required";
        if (!data.storeOpenEnd) e.storeOpenEnd = "Closing date is required";
      }
      if (data.collectTax) {
        if (!data.taxRate || isNaN(parseFloat(data.taxRate))) e.taxRate = "Enter a rate or select a state";
        if (!data.taxLiabilityAgreed) e.taxLiability = "You must accept the tax liability agreement to continue";
      }
    }
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const goTo = (s) => {
    if (s <= maxReached) {setStep(s);setErrors({});scrollTop();}
  };

  const next = () => {
    if (!validateStep(step)) return;
    const n = Math.min(step + 1, STEPS.length - 1);
    setStep(n);
    setMaxReached((m) => Math.max(m, n));
    scrollTop();
  };
  const back = () => {setStep((s) => Math.max(0, s - 1));setErrors({});scrollTop();};

  const deploy = () => {
    if (!validateStep(step)) return;
    const SP = [
    { value: "braeden-stokes", email: "braeden@stokesathletics.com", phone: "208-654-8619" },
    { value: "maria-lopez", email: "maria@prolook.com", phone: "801-555-0142" },
    { value: "devon-pierce", email: "devon@prolook.com", phone: "801-555-0188" }];

    const findSp = (v) => SP.find((s) => s.value === v) || {};
    // Team Manager mode inherits the manager record; salesperson/custom override.
    const derivedEmail = data.contactEmailMode === "salesperson" ? findSp(data.contactEmailSalesperson).email || data.email :
    data.contactEmailMode === "custom" ? data.contactEmailCustom || data.email :
    data.email;
    const derivedPhone = data.contactPhoneMode === "salesperson" ? findSp(data.contactPhoneSalesperson).phone || data.phone :
    data.contactPhoneMode === "custom" ? data.contactPhoneCustom || data.phone :
    data.phone;
    const mapped = {
      ...data,
      email: derivedEmail || data.email,
      phone: derivedPhone || data.phone,
      teamName: data.teamName || (TEAMS_TO_CONNECT.find((t) => t.value === data.connectedTeam) || {}).label || data.teamName,
      collectTax: !!data.collectTax,
      taxRate: data.collectTax ? data.taxRate || "0" : "0",
      taxState: data.collectTax ? data.taxState : "",
      taxMode: data.collectTax ? "flat" : "exempt",
      shipName: data.managerName || data.shipName,
      shipOption: data.distributionModel === "home" ? "Ship to each Player" : "Ship to Coach",
      storeOpenMode: data.distributionFormat === "locker" ? "stay-open" : "set-window",
      teamColors: data.teamColors && data.teamColors.length ? data.teamColors : [data.primaryColor, "#0e0e10", "#ffffff"]
    };
    onSubmit(mapped);
  };

  const isLast = step === STEPS.length - 1;
  const stepProps = { data, set, errors, accent, liveStores, stepNum: step + 1 };

  return (
    <div id="wizard-scroll" style={{ flex: 1, background: "#fbfbfc" }}>
      {/* Full-width header band — title, step badge, and the cross-viewport stepper */}
      <div style={{ background: "#fff", borderBottom: "1px solid #ececf0", padding: "28px 48px 4px" }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 20, marginBottom: 24 }}>
          <div>
            <div style={{ fontSize: 12, fontWeight: 800, letterSpacing: ".12em", color: "#9a9aa1", textTransform: "uppercase", marginBottom: 8 }}>
              Team Store Setup
            </div>
            <h1 style={{ fontSize: 30, fontWeight: 800, margin: 0, letterSpacing: ".005em", color: "#0e0e10", fontFamily: "Archivo, sans-serif" }}>
              {templateMode ? "Finish Your Template Store" : "Create a Team Store"}
            </h1>
            {data._dupSource && (
              <div style={{ display: "inline-flex", alignItems: "center", gap: 8, marginTop: 12, fontSize: 12.5, color: "#52525b", background: "#f6f6f8", borderRadius: 999, padding: "6px 12px" }}>
                <IconLayers size={13} style={{ strokeWidth: 2 }} />
                <span>{data._dupSource.mode === "full" ? "Duplicated from " : "Products from "}<strong style={{ color: "#0e0e10" }}>{data._dupSource.sourceName}</strong> · {(data.curatedProducts || []).length} product{(data.curatedProducts || []).length === 1 ? "" : "s"}{!data._dupSource.mine && data._dupSource.owner ? " · " + data._dupSource.owner + "’s store" : ""}</span>
              </div>
            )}
          </div>
          <span style={{
            flexShrink: 0, marginTop: 8, border: `1.5px solid ${accent}`, color: accent,
            borderRadius: 999, padding: "8px 16px", fontSize: 12, fontWeight: 800, letterSpacing: ".06em",
            textTransform: "uppercase", background: "#fff"
          }}>Step {step + 1} of {STEPS.length}</span>
        </div>

        <WizardStepper current={step} maxReached={maxReached} onJump={goTo} accent={accent} steps={STEPS} preDone={data._fromVault ? ["products"] : []} />
      </div>

      {/* Centered, shadowed workspace container */}
      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "32px 40px 152px" }}>
        <div style={{
          background: "#fff", border: "1px solid #ececf0", borderRadius: 14,
          boxShadow: "0 16px 44px rgba(20,20,30,.09)", padding: "36px 36px",
        }}>
          {STEPS[step].key === "basics" && <Step1Basics {...stepProps} />}
          {STEPS[step].key === "structure" && <Step2Structure data={data} setStructure={setStructure} accent={accent} stepNum={step + 1} />}
          {STEPS[step].key === "products" && <Step3Products {...stepProps} />}
          {STEPS[step].key === "review" && <Step6Review data={data} accent={accent} athletes={athletes} stepNum={step + 1} onEditBasics={() => goTo(0)} onEditProducts={STEPS.some((x) => x.key === "products") ? () => goTo(STEPS.findIndex((x) => x.key === "products")) : null} onRemoveProduct={(i) => set({ curatedProducts: (data.curatedProducts || []).filter((_, j) => j !== i) })} />}
        </div>
      </div>

      {/* Footer actions */}
      <div style={{
        position: "fixed", bottom: 0, left: 0, right: 0,
        background: "#fff", borderTop: "1px solid #ececf0",
        padding: "16px 28px", display: "flex", alignItems: "center", justifyContent: "space-between",
        boxShadow: "0 -2px 8px rgba(20,20,30,.04)", zIndex: 60
      }}>
        <Button variant="ghost" onClick={onCancel}>CANCEL</Button>
        <div style={{ display: "flex", gap: 16, alignItems: "center" }}>
          {!isLast && Object.keys(errors).length > 0 && (
            <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13, fontWeight: 700, color: "#b81d14" }}>
              <IconAlert size={15} style={{ strokeWidth: 2.2, flexShrink: 0 }} /> Please complete the required fields above
            </span>
          )}
          {step > 0 &&
          <Button variant="secondary" onClick={back}>
              <IconChevronLeft size={15} /> BACK
            </Button>
          }
          {isLast ?
          <button onClick={deploy} style={{
            display: "inline-flex", alignItems: "center", gap: 8, border: 0, borderRadius: 4,
            padding: "12px 28px", fontSize: 13, fontWeight: 800, letterSpacing: ".02em",
            color: "#fff", background: "#0e0e10", cursor: "pointer"
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = "#1f1f22"}
          onMouseLeave={(e) => e.currentTarget.style.background = "#0e0e10"}>
              <IconCheck size={16} style={{ strokeWidth: 3 }} /> SAVE AS DRAFT
            </button> :

          <Button variant="primary" onClick={next}>
              CONTINUE <IconChevronRight size={15} />
            </Button>
          }
        </div>
      </div>
    </div>);

}

Object.assign(window, { CreateForm, Section });

/* ═══════════════════ USE AS TEMPLATE — start a new store from an existing one ═══════════════════ */
// No template entity: the source is always a real store in the rep's list. Both
// paths enter the create wizard; they differ only in how much arrives pre-filled.
function uatStatusLabel(s) {
  if (s.archived) return "Archived";
  if (!s.live) return "Draft";
  const end = s.storeOpenEnd;
  if (s.storeOpenMode !== "stay-open" && end && new Date(end + "T23:59:59") < new Date()) return "Closed";
  return "Open";
}
function uatOwner(s) { return (s && (s.createdBy || s.createdByName)) || ""; }
function uatIsMine(s, viewer) { return !!s && (s.ownership === "mine" || (!!uatOwner(s) && uatOwner(s) === viewer)); }
function uatManagers(s) {
  const out = [];
  const primaryName = s.managerName || [s.shipFirstName, s.shipLastName].filter(Boolean).join(" ") || s.shipName || "";
  if (primaryName || s.email) out.push({ id: "primary", name: primaryName || "Team manager", email: s.email || "", phone: s.phone || "", primary: true });
  (s.additionalManagers || []).forEach((m, i) => {
    const n = [m.firstName, m.lastName].filter(Boolean).join(" ") || m.name || "";
    if (n || m.email) out.push({ id: m.id || "mgr-" + i, name: n || "Manager", email: m.email || "", phone: m.phone || "" });
  });
  return out;
}
function uatProducts(s) { return ((s && s.products) || []).filter((p) => !p.__autoStock); }
function uatCopyName(base, stores) {
  const names = new Set((stores || []).map((x) => String(x.storeTitle || x.teamName || "").trim().toLowerCase()));
  let n = base + " Copy", i = 2;
  while (names.has(n.toLowerCase())) { n = base + " Copy " + i; i++; }
  return n;
}
// Divisions and teams copy; players don't — every team arrives with an empty roster.
function uatStructure(s) {
  const org = typeof makeRosterOrg === "function" ? makeRosterOrg(s, false) : { groups: [], loose: [] };
  const strip = (r) => ({ ...r, players: 0 });
  return { groups: (org.groups || []).map((g) => ({ ...g, rosters: (g.rosters || []).map(strip) })), loose: (org.loose || []).filter((r) => r.id !== "single-roster").map(strip) };
}
function uatStructureCounts(s) {
  const st = uatStructure(s);
  return { divisions: st.groups.length, teams: st.groups.reduce((n, g) => n + (g.rosters || []).length, 0) + st.loose.length };
}
function uatBuildPreset(src, { mode, name, managerIds, viewer }) {
  const products = uatProducts(src).map((p) => { const { id, ...rest } = p; return { ...rest, srcId: p.srcId || id }; });
  const prov = { mode, sourceName: src.storeTitle || src.teamName || "Store", owner: uatOwner(src), mine: uatIsMine(src, viewer), viewer, count: products.length, sourceType: src.storeType || "single" };
  if (mode === "products") return { ...makePrefill(), curatedProducts: products, _dupSource: prov, _skipProducts: true };
  const mgrs = uatManagers(src).filter((m) => (managerIds || []).includes(m.id));
  const primary = mgrs.find((m) => m.primary) || null;
  const split = (n) => { const w = String(n || "").trim().split(/\s+/); return { first: w[0] || "", last: w.slice(1).join(" ") }; };
  const additional = mgrs.filter((m) => !m.primary).map((m) => ({ id: m.id, firstName: split(m.name).first, lastName: split(m.name).last, email: m.email, phone: m.phone }));
  const { id, products: _p, pendingProducts, orders, revenue, archived, live, status, storeSlug, storeOpenStart, storeOpenEnd, __fresh, __userCreated, ownership, createdBy, createdByName, seeded, managerName, shipName, shipFirstName, shipLastName, email, phone, additionalManagers, firstName, lastName, ...rest } = src;
  const pn = primary ? split(primary.name) : { first: "", last: "" };
  return {
    ...rest,
    storeTitle: name, storeSlug: slugify(name), _slugTouched: false,
    storeOpenStart: "", storeOpenEnd: "",
    distributionFormat: src.distributionFormat || (src.storeOpenMode === "stay-open" ? "locker" : "popup"),
    distributionModel: src.distributionModel || "coach",
    contactEmailMode: src.contactEmailMode || "teammanager", contactPhoneMode: src.contactPhoneMode || "teammanager",
    firstName: pn.first, lastName: pn.last,
    managerName: primary ? primary.name : "", shipName: primary ? primary.name : "",
    shipFirstName: pn.first, shipLastName: pn.last,
    email: primary ? primary.email : "", phone: primary ? primary.phone : "",
    additionalManagers: additional,
    curatedProducts: products,
    leagueStructure: (src.storeType === "league") ? uatStructure(src) : { groups: [], loose: [] },
    _dupSource: prov, _startAt: "review",
  };
}

function UseAsTemplateModal({ store, stores, viewer, simulateFail = false, onClose, onConfirm }) {
  const [phase, setPhase] = React.useState("choose");   // choose | confirm | working | failed
  const [mode, setMode] = React.useState("full");
  const [name, setName] = React.useState("");
  const [mgrSel, setMgrSel] = React.useState([]);
  const timer = React.useRef(null);
  React.useEffect(() => {
    if (!store) return;
    setPhase("choose"); setMode("full");
    setName(uatCopyName(store.storeTitle || store.teamName || "Store", stores));
    const mine = uatIsMine(store, viewer);
    setMgrSel(mine ? uatManagers(store).map((m) => m.id) : []);
    return () => { if (timer.current) clearTimeout(timer.current); };
  }, [store && store.id]);
  if (!store) return <Modal open={false} onClose={onClose} width={620} />;
  const isLeague = store.storeType === "league";
  const mine = uatIsMine(store, viewer);
  const owner = uatOwner(store);
  const products = uatProducts(store);
  const managers = uatManagers(store);
  const counts = isLeague ? uatStructureCounts(store) : null;
  const status = uatStatusLabel(store);
  const nameTaken = (stores || []).some((x) => String(x.storeTitle || x.teamName || "").trim().toLowerCase() === name.trim().toLowerCase());
  const run = () => {
    setPhase("working");
    timer.current = setTimeout(() => {
      if (simulateFail) { setPhase("failed"); return; }
      onConfirm(uatBuildPreset(store, { mode, name: name.trim(), managerIds: mgrSel, viewer }));
    }, 1700);
  };
  const optionCard = (key, title, body, disabled, note) => {
    const on = mode === key && !disabled;
    return (
      <button type="button" disabled={disabled} onClick={() => !disabled && setMode(key)} style={{ textAlign: "left", background: "#fff", border: "1.5px solid " + (on ? "#0e0e10" : "#e4e4e7"), borderRadius: 10, padding: "16px 18px", cursor: disabled ? "not-allowed" : "pointer", fontFamily: "inherit", opacity: disabled ? .55 : 1, display: "flex", gap: 14, alignItems: "flex-start", boxShadow: on ? "0 0 0 3px rgba(14,14,16,.08)" : "none" }}>
        <span style={{ width: 18, height: 18, borderRadius: 999, border: "2px solid " + (on ? "#0e0e10" : "#d4d4d8"), background: on ? "#0e0e10" : "#fff", boxShadow: on ? "inset 0 0 0 3px #fff" : "none", flexShrink: 0, marginTop: 1 }} />
        <span style={{ minWidth: 0 }}>
          <span style={{ display: "block", fontSize: 14.5, fontWeight: 800, color: "#0e0e10", fontFamily: "Archivo, sans-serif" }}>{title}</span>
          <span style={{ display: "block", fontSize: 12.5, color: "#52525b", lineHeight: 1.55, marginTop: 5 }}>{body}</span>
          {note && <span style={{ display: "block", fontSize: 12, color: "#b81d14", fontWeight: 700, marginTop: 6 }}>{note}</span>}
        </span>
      </button>
    );
  };
  const sourceLine = (
    <div style={{ display: "flex", alignItems: "center", gap: 12, background: "#f6f6f8", borderRadius: 10, padding: "12px 14px" }}>
      <span style={{ width: 38, height: 38, borderRadius: "50%", background: (store.teamLogo && store.teamLogo.color) || (store.teamColors && store.teamColors[0]) || "#1d3a8a", color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 12.5, fontFamily: "Archivo, sans-serif", flexShrink: 0 }}>{(store.teamLogo && store.teamLogo.mono) || (store.teamName || store.storeTitle || "T").slice(0, 2).toUpperCase()}</span>
      <span style={{ flex: 1, minWidth: 0 }}>
        <span style={{ display: "block", fontSize: 13.5, fontWeight: 800, color: "#0e0e10", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{store.storeTitle || store.teamName}</span>
        <span style={{ display: "block", fontSize: 12, color: "#6b6b72", marginTop: 2 }}>{isLeague ? "League Store" : "Individual Team Store"} · {status}{owner ? " · " + (mine ? "Your store" : owner + "’s store") : ""}</span>
      </span>
    </div>
  );
  const H = ({ title, desc }) => (
    <div style={{ marginBottom: 18 }}>
      <h2 style={{ margin: 0, fontSize: 20, fontWeight: 800, fontFamily: "Archivo, sans-serif", color: "#0e0e10" }}>{title}</h2>
      {desc && <p style={{ margin: "6px 0 0", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>{desc}</p>}
    </div>
  );
  const fullBody = isLeague
    ? <React.Fragment>Products, branding, settings, and your league’s divisions and teams come across. <strong style={{ color: "#0e0e10" }}>Players don’t</strong> — every team starts with an empty roster. You’ll land on the final review step with everything else filled in.</React.Fragment>
    : <React.Fragment>Products, branding, and settings come across. <strong style={{ color: "#0e0e10" }}>Players don’t</strong> — the roster starts empty. You’ll land on the final review step with everything else filled in.</React.Fragment>;
  const productsBody = isLeague
    ? "Just the product catalog. Divisions, teams, and per-team product assignments don’t come across — you’ll set up branding, structure, rosters, and settings yourself."
    : "Just the product catalog. You’ll set up branding, structure, rosters, and settings yourself.";
  return (
    <Modal open={!!store} onClose={phase === "working" ? () => {} : onClose} width={620}>
      {phase === "choose" && (
        <div style={{ padding: "28px 32px 24px" }}>
          <H title="Use as Template" desc="Start a new store from this one. Nothing is created until you confirm." />
          {sourceLine}
          <div style={{ display: "grid", gap: 10, marginTop: 16 }}>
            {optionCard("full", "Duplicate the whole store", fullBody, false)}
            {optionCard("products", "Use only the products", productsBody, products.length === 0, products.length === 0 ? "This store has no products, so there’s nothing to copy on its own." : null)}
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 24 }}>
            <Button variant="secondary" onClick={onClose}>Cancel</Button>
            <Button variant="primary" onClick={() => setPhase("confirm")}>Continue</Button>
          </div>
        </div>
      )}
      {phase === "confirm" && (
        <div style={{ padding: "28px 32px 24px" }}>
          <H title={mode === "full" ? "Duplicate the whole store" : "Use only the products"} desc={mode === "full" ? "Review what comes across, then name the new store." : "The catalog comes across. Everything else you’ll set up in the wizard."} />
          {sourceLine}
          <label style={{ display: "block", marginTop: 16 }}>
            <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#0e0e10", marginBottom: 6 }}>New store name</span>
            <input value={name} onChange={(e) => setName(e.target.value)} style={{ width: "100%", height: 40, boxSizing: "border-box", border: "1px solid " + (nameTaken || !name.trim() ? "#b81d14" : "#d4d4d8"), borderRadius: 6, padding: "0 12px", fontSize: 13.5, fontFamily: "inherit", outline: "none" }} />
            <span style={{ display: "block", fontSize: 11.5, color: nameTaken || !name.trim() ? "#b81d14" : "#9a9aa1", marginTop: 6 }}>{!name.trim() ? "A name is required." : nameTaken ? "A store with this name already exists — pick a different one." : "Most reps rename this to the new season — e.g. “2026 Season”."}</span>
          </label>
          {mode === "full" && managers.length > 0 && (
            <div style={{ marginTop: 18 }}>
              <div style={{ fontSize: 12, fontWeight: 700, color: "#0e0e10", marginBottom: 8 }}>Copy managers?</div>
              <div style={{ border: "1px solid #e4e4e7", borderRadius: 8, overflow: "hidden" }}>
                {managers.map((m, i) => {
                  const on = mgrSel.includes(m.id);
                  return (
                    <label key={m.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "11px 14px", borderTop: i ? "1px solid #f1f1f3" : "none", cursor: "pointer", background: "#fff" }}>
                      <input type="checkbox" checked={on} onChange={(e) => setMgrSel((s) => e.target.checked ? [...s, m.id] : s.filter((x) => x !== m.id))} style={{ width: 16, height: 16, accentColor: "#0e0e10", cursor: "pointer" }} />
                      <span style={{ fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{m.name}</span>
                      {m.email && <span style={{ fontSize: 12.5, color: "#6b6b72" }}>· {m.email}</span>}
                    </label>
                  );
                })}
              </div>
              <div style={{ fontSize: 12, color: "#6b6b72", lineHeight: 1.5, marginTop: 8 }}>Copying a manager creates a contact record only — it does not grant them access to the new store.</div>
            </div>
          )}
          <div style={{ marginTop: 18, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
            <div style={{ background: "#f6f6f8", borderRadius: 10, padding: "12px 14px" }}>
              <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".08em", color: "#1f7a44", textTransform: "uppercase", marginBottom: 6 }}>Comes across</div>
              <ul style={{ margin: 0, paddingLeft: 16, fontSize: 12.5, color: "#0e0e10", lineHeight: 1.7 }}>
                <li>{products.length} product{products.length === 1 ? "" : "s"} with pricing, decoration &amp; visibility</li>
                {mode === "full" && <li>Team logo, colors &amp; store theme</li>}
                {mode === "full" && isLeague && <li>{counts.divisions} division{counts.divisions === 1 ? "" : "s"} &amp; {counts.teams} team{counts.teams === 1 ? "" : "s"} — rosters empty</li>}
                {mode === "full" && <li>Fulfillment, fundraising &amp; announcement</li>}
                {mode === "full" && <li>Team binding in the Team Database</li>}
                {mode === "full" && mgrSel.length > 0 && <li>{mgrSel.length} manager contact{mgrSel.length === 1 ? "" : "s"}</li>}
              </ul>
            </div>
            <div style={{ background: "#fdf4f3", borderRadius: 10, padding: "12px 14px" }}>
              <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".08em", color: "#b81d14", textTransform: "uppercase", marginBottom: 6 }}>Doesn’t</div>
              <ul style={{ margin: 0, paddingLeft: 16, fontSize: 12.5, color: "#0e0e10", lineHeight: 1.7 }}>
                <li>Players</li><li>Orders</li><li>Portal access</li>
                {mode === "full" && <li>Web address &amp; ordering window</li>}
                {mode === "products" && <li>Branding, structure &amp; settings</li>}
              </ul>
            </div>
          </div>
          <div style={{ fontSize: 12, color: "#9a9aa1", marginTop: 12 }}>The new store starts as a <strong style={{ color: "#0e0e10" }}>Draft</strong> owned by you{!mine && owner ? ", not " + owner : ""}.</div>
          {mode === "products" && products.length > 0 && (() => {
            const max = 6;
            const shown = products.length > max ? products.slice(0, max - 1) : products;
            const rest = products.length - shown.length;
            return (
              <div style={{ marginTop: 18 }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: "#0e0e10", marginBottom: 8 }}>Products coming across</div>
                <div style={{ display: "flex", gap: 8, flexWrap: "nowrap", overflow: "hidden" }}>
                  {shown.map((p, i) => (
                    <div key={p.id || i} title={p.title || p.name || ""} style={{ width: 56, height: 72, flexShrink: 0, background: "#f1f2f4", borderRadius: 6, padding: 4, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
                      <img src={__asset(orderPhotoFor(p))} alt={p.title || p.name || "Product"} style={{ width: "100%", height: "100%", objectFit: "contain", display: "block" }} />
                    </div>
                  ))}
                  {rest > 0 && (
                    <div style={{ width: 56, height: 72, flexShrink: 0, background: "#fff", border: "1px dashed #d4d4d8", borderRadius: 6, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 800, color: "#52525b", fontFamily: "Archivo, sans-serif" }}>+{rest}</div>
                  )}
                </div>
              </div>
            );
          })()}
          <div style={{ display: "flex", justifyContent: "space-between", gap: 12, marginTop: 22 }}>
            <Button variant="ghost" onClick={() => setPhase("choose")}>Back</Button>
            <div style={{ display: "flex", gap: 12 }}>
              <Button variant="secondary" onClick={onClose}>Cancel</Button>
              <Button variant="primary" disabled={!name.trim() || nameTaken} onClick={run}>{mode === "full" ? "Duplicate store" : "Use these products"}</Button>
            </div>
          </div>
        </div>
      )}
      {phase === "working" && (
        <div style={{ padding: "48px 32px 44px", textAlign: "center" }}>
          <span style={{ display: "inline-block", width: 34, height: 34, borderRadius: "50%", border: "3px solid #e4e4e7", borderTopColor: "#0e0e10", animation: "uatSpin .8s linear infinite" }} />
          <style>{"@keyframes uatSpin{to{transform:rotate(360deg)}}"}</style>
          <div style={{ fontSize: 16, fontWeight: 800, fontFamily: "Archivo, sans-serif", color: "#0e0e10", marginTop: 18 }}>Setting up your new store</div>
          <div style={{ fontSize: 13, color: "#6b6b72", marginTop: 6 }}>This takes a few seconds.</div>
        </div>
      )}
      {phase === "failed" && (
        <div style={{ padding: "28px 32px 24px" }}>
          <H title="We couldn’t set up the store" desc={"Copying from " + (store.storeTitle || store.teamName) + " timed out before it finished. Nothing was created — " + (store.storeTitle || store.teamName) + " is unchanged and no new store was added to your list."} />
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 8 }}>
            <Button variant="secondary" onClick={onClose}>Cancel</Button>
            <Button variant="primary" onClick={run}>Try again</Button>
          </div>
        </div>
      )}
    </Modal>
  );
}

// Review & Deploy additions when the wizard was started from another store.
function UatReviewExtras({ data, onEditBasics }) {
  const prov = data._dupSource;
  if (!prov) return null;
  const reqs = [];
  if (data.distributionFormat !== "locker" && !(data.storeOpenStart && data.storeOpenEnd)) reqs.push({ k: "Set the ordering window", d: "The source store’s dates weren’t copied — last season’s close date doesn’t belong on this store.", fix: true });
  reqs.push({ k: "Confirm the web address", d: "prolookstores.com/" + (data.storeSlug || "—") + " was generated from the new name.", fix: true });
  if (!data.email) reqs.push({ k: "Add a point of contact", d: "No manager contact was copied, so the store has no email or phone yet.", fix: true });
  const team = (WIZARD_TEAMS.find((t) => t.value === data.connectedTeam) || {}).label || data.teamName || "—";
  const logoColor = (data.teamLogo && data.teamLogo.color) || (data.teamColors && data.teamColors[0]) || "#1d3a8a";
  return (
    <React.Fragment>
      {prov.mode === "full" && (
        <WizardPanel label="Connected Team" hint="Copied from the source — change it if this store is for a different team" style={{ marginBottom: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            {data.teamLogo && data.teamLogo.url
              ? <img src={__asset(data.teamLogo.url)} alt="" style={{ width: 44, height: 44, objectFit: "contain" }} />
              : <span style={{ width: 44, height: 44, borderRadius: "50%", background: logoColor, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 14, fontFamily: "Archivo, sans-serif" }}>{(data.teamLogo && data.teamLogo.mono) || String(team).slice(0, 2).toUpperCase()}</span>}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 15, fontWeight: 800, color: "#0e0e10" }}>{team}</div>
              <div style={{ fontSize: 12.5, color: "#6b6b72", marginTop: 2 }}>Same team as {prov.sourceName}{prov.mine ? "" : " (" + prov.owner + "’s store)"} · owned by you{prov.viewer ? " — " + prov.viewer : ""}</div>
            </div>
            <Button variant="secondary" onClick={onEditBasics}>Change team</Button>
          </div>
        </WizardPanel>
      )}
      <WizardPanel label="Before this store can deploy" hint={reqs.length + (reqs.length === 1 ? " requirement" : " requirements")} style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", flexDirection: "column" }}>
          {reqs.map((r, i) => (
            <div key={r.k} style={{ display: "flex", alignItems: "flex-start", gap: 12, padding: "10px 0", borderTop: i ? "1px solid #f1f1f3" : "none" }}>
              <span style={{ width: 8, height: 8, borderRadius: 999, background: "#b06f1e", flexShrink: 0, marginTop: 6 }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>{r.k}</div>
                <div style={{ fontSize: 12.5, color: "#6b6b72", marginTop: 2, lineHeight: 1.5 }}>{r.d}</div>
              </div>
              {r.fix && <button type="button" onClick={onEditBasics} style={{ border: 0, background: "none", color: "#0e0e10", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", textDecoration: "underline", textUnderlineOffset: 3, flexShrink: 0 }}>Edit in Basics</button>}
            </div>
          ))}
          {prov.mode === "full" && (
            <div style={{ display: "flex", alignItems: "flex-start", gap: 12, padding: "10px 0", borderTop: "1px solid #f1f1f3" }}>
              <span style={{ width: 8, height: 8, borderRadius: 999, background: "#d4d4d8", flexShrink: 0, marginTop: 6 }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>Rosters are empty</div>
                <div style={{ fontSize: 12.5, color: "#6b6b72", marginTop: 2, lineHeight: 1.5 }}>Players never copy. Rosters are optional — the store can deploy without them, and you can add players from My Team(s) anytime.</div>
              </div>
            </div>
          )}
        </div>
      </WizardPanel>
    </React.Fragment>
  );
}




