// Pick a vivid brand color for the live-branding overlay (skip near-white/black/grey).
function tplPrimary(colors) {
  const list = colors || [];
  const lum = (hex) => {
    const h = (hex || "").replace("#", "");
    if (h.length < 6) return 0.5;
    const r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
    return (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  };
  const sat = (hex) => {
    const h = (hex || "").replace("#", "");
    if (h.length < 6) return 0;
    const r = parseInt(h.slice(0, 2), 16) / 255, g = parseInt(h.slice(2, 4), 16) / 255, b = parseInt(h.slice(4, 6), 16) / 255;
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    return mx === 0 ? 0 : (mx - mn) / mx;
  };
  const vivid = list.find((c) => { const l = lum(c); return l > 0.14 && l < 0.86 && sat(c) > 0.28; });
  return vivid || list[1] || "#e1251b";
}

