// Live-branding overlay drawn on top of a product photo.
function TplBrandOverlay({ name, logo, primary, role }) {
  const on = !!(name || logo);
  const mono = (name || "T").replace(/[^A-Za-z0-9 ]/g, "").split(/\s+/).map((w) => w[0]).join("").slice(0, 2).toUpperCase() || "T";
  return (
    <React.Fragment>
      {/* team-color trim bar */}
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 8, background: on ? primary : "transparent", transition: "background .3s" }} />
      {/* logo chip + role tag, top-left row */}
      <div style={{ position: "absolute", top: 12, left: 12, display: "flex", alignItems: "center", gap: 8 }}>
        <div style={{ opacity: on ? 1 : 0, transform: on ? "translateY(0)" : "translateY(-6px)", transition: "opacity .3s, transform .3s" }}>
          {logo && logo.url
            ? <img src={__asset(logo.url)} alt="" style={{ width: 36, height: 36, borderRadius: 7, objectFit: "cover", boxShadow: "0 2px 6px rgba(0,0,0,.18)", background: "#fff", display: "block" }} />
            : <span style={{ width: 36, height: 36, borderRadius: 7, background: primary, color: "#fff", fontSize: 13, fontWeight: 800, fontFamily: "Archivo, sans-serif", display: "inline-flex", alignItems: "center", justifyContent: "center", boxShadow: "0 2px 6px rgba(0,0,0,.18)" }}>{mono}</span>}
        </div>
        {role && (
          <span style={{ background: "#0e0e10", color: "#fff", fontSize: 10, fontWeight: 800, letterSpacing: ".1em", padding: "4px 8px", borderRadius: 999 }}>{role}</span>
        )}
      </div>
      {/* name ribbon */}
      {name && (
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, padding: "20px 12px 12px", background: "linear-gradient(to top, rgba(14,14,16,.72), transparent)", opacity: on ? 1 : 0, transition: "opacity .3s" }}>
          <div style={{ color: "#fff", fontSize: 14, fontWeight: 800, letterSpacing: ".04em", textTransform: "uppercase", fontFamily: "Archivo, sans-serif", textShadow: "0 1px 3px rgba(0,0,0,.4)" }}>{name}</div>
        </div>
      )}
    </React.Fragment>
  );
}

// One product card in the catalog grid — storefront-style: large image tile + info block.
function TplProductCard({ id, included, locked, onToggle, brand, accent, compact }) {
  const p = TPL_PRODUCTS[id];
  const [hover, setHover] = React.useState(false);
  const primary = brand.primary;
  const selectable = !locked;
  const active = included || locked;
  return (
    <div
      onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}
      style={{ display: "flex", flexDirection: "column" }}>
      {/* Image tile */}
      <div
        onClick={selectable ? onToggle : undefined}
        style={{
          position: "relative", aspectRatio: "1 / 1.18", background: "#f4f4f5", borderRadius: 10, overflow: "hidden",
          display: "flex", alignItems: "center", justifyContent: "center", padding: 12,
          cursor: selectable ? "pointer" : "default",
          outline: active ? `2.5px solid ${accent}` : "2.5px solid transparent", outlineOffset: -2.5,
          boxShadow: hover && selectable && !active ? "0 8px 22px rgba(20,20,30,.10)" : "none",
          transition: "outline-color .16s, box-shadow .16s",
        }}>
        <img src={__asset(`assets/products/${p.photo}.png`)} alt={p.title} style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain", display: "block" }} />
        {/* team-color trim + role tag (photos ship pre-branded) */}
        {p.role && (
          <span style={{ position: "absolute", top: 12, left: 12, background: "#0e0e10", color: "#fff", fontSize: 10, fontWeight: 800, letterSpacing: ".1em", padding: "4px 8px", borderRadius: 999 }}>{p.role}</span>
        )}
        {/* selection badge */}
        {active && (
          <span style={{ position: "absolute", top: 12, right: 12, width: 28, height: 28, borderRadius: "50%", background: accent, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", boxShadow: "0 2px 6px rgba(0,0,0,.2)" }}>
            <IconCheck size={15} style={{ strokeWidth: 3.4 }} />
          </span>
        )}
        {/* hover add affordance */}
        {selectable && !included && hover && (
          <span style={{ position: "absolute", left: 12, bottom: 12, display: "inline-flex", alignItems: "center", gap: 8, background: "#0e0e10", color: "#fff", fontSize: 11.5, fontWeight: 800, letterSpacing: ".04em", padding: "8px 12px", borderRadius: 999 }}>
            <IconPlus size={13} style={{ strokeWidth: 2.8 }} /> ADD TO STORE
          </span>
        )}
      </div>
      {/* Info block */}
      <div style={{ padding: "12px 2px 0" }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: 8 }}>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#0e0e10", lineHeight: 1.25, fontFamily: "Archivo, sans-serif" }}>{p.title}</div>
          <span style={{ flexShrink: 0, background: "#ececee", color: "#52525b", fontSize: 11, fontWeight: 600, padding: "4px 8px", borderRadius: 6 }}>{p.tag}</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, color: "#3f3f46", marginBottom: 4 }}>
          <span style={{ width: 16, height: 16, borderRadius: "50%", background: "conic-gradient(from 0deg,#e1251b,#f5b400,#1f9d55,#2563eb,#7c3aed,#e1251b)", flexShrink: 0 }} />
          {p.fulfill}
        </div>
        <div style={{ fontSize: 13.5, color: "#9a9aa1", marginBottom: 4 }}>{p.ships}</div>
        <div style={{ fontSize: 13.5, color: "#0e0e10" }}>
          <strong style={{ fontWeight: 800 }}>MSRP ${p.msrp}</strong> <span style={{ color: "#6b6b72" }}>- Team Pricing Available</span>
        </div>
        {/* include control */}
        {locked ? (
          <div style={{ marginTop: 12, display: "inline-flex", alignItems: "center", gap: 8, fontSize: 11.5, fontWeight: 800, letterSpacing: ".04em", color: accent }}>
            <IconCheck size={14} style={{ strokeWidth: 3.2 }} /> BASELINE · INCLUDED
          </div>
        ) : (
          <button type="button" onClick={onToggle} style={{
            marginTop: 12, height: 40, width: "100%", borderRadius: 8, cursor: "pointer", fontSize: 12, fontWeight: 800, letterSpacing: ".04em",
            border: included ? `1.5px solid ${accent}` : "1.5px solid #d4d4d8",
            background: included ? `${accent}0d` : "#fff", color: included ? accent : "#0e0e10",
            display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, transition: "all .14s",
          }}
            onMouseEnter={(e) => { if (!included) e.currentTarget.style.borderColor = "#0e0e10"; }}
            onMouseLeave={(e) => { if (!included) e.currentTarget.style.borderColor = "#d4d4d8"; }}>
            {included ? <React.Fragment><IconCheck size={14} style={{ strokeWidth: 3.2 }} /> IN STORE</React.Fragment> : <React.Fragment><IconPlus size={14} style={{ strokeWidth: 2.6 }} /> ADD TO STORE</React.Fragment>}
          </button>
        )}
      </div>
    </div>
  );
}

