// Native date input, styled to match the field set.
function DateInput({ value, onChange }) {
  const [focus, setFocus] = React.useState(false);
  return (
    <input
      type="date"
      value={value || ""}
      onChange={(e) => onChange(e.target.value)}
      onFocus={() => setFocus(true)}
      onBlur={() => setFocus(false)}
      style={{
        width: "100%", boxSizing: "border-box", padding: "12px 12px",
        border: `1px solid ${focus ? "#0e0e10" : "#d4d4d8"}`, borderRadius: 4,
        fontSize: 14, fontFamily: "inherit", color: "#0e0e10", outline: "none",
        background: "#fff",
      }} />
  );
}

