function formatStoreDate(iso) {
  if (!iso) return "—";
  // Accept "YYYY-MM-DD" → "MM/DD/YYYY"
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
  if (m) return `${m[2]}/${m[3]}/${m[1]}`;
  return iso;
}

