/* ===== ASSET 20 : bb8dea27-db64-4569-b0c1-4c9a0ff0db38 ===== */
// Products flow — configure a pending product, then list drafts/published.

// ─────────── Draft / Ready status badge ───────────
// A product is a "Draft" until its logo application sizes are confirmed; once
// they are, it becomes "Ready" to publish to parents. Used on the configure
// card and on each product card in the Drafts list.
function ProductStatusBadge({ ready, size = "md" }) {
  const sm = size === "sm";
  const c = ready ?
  { bg: "#e7f5ed", ink: "#1f8a55", label: "READY" } :
  { bg: "#fff4e0", ink: "#b5760a", label: "DRAFT" };
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: sm ? 5 : 6,
      background: c.bg, color: c.ink, borderRadius: 999,
      padding: sm ? "3px 9px" : "5px 11px",
      fontSize: sm ? 10 : 11, fontWeight: 800, letterSpacing: ".06em"
    }}>
      <span style={{ width: sm ? 5 : 6, height: sm ? 5 : 6, borderRadius: "50%", background: c.ink, display: "inline-block" }} />
      {c.label}
    </span>);

}

// ─────────── Configure a pending product (the "pre-add" page) ───────────
// Fully controlled — parent owns config so multiple items can be configured in parallel.
function ConfigureProduct({ product, store, config, onConfigChange, onProductChange, onDelete, index, total }) {
  const teamSetting = config.teamSetting;
  const pricing = config.pricing;
  const sizesConfirmed = config.sizesConfirmed;
  const showSizesModal = config.showSizesModal;
  const applicationSizes = config.applicationSizes;
  const [editingName, setEditingName] = React.useState(false);
  const nameInputRef = React.useRef(null);
  React.useEffect(() => {
    if (editingName && nameInputRef.current) {
      nameInputRef.current.focus();
      nameInputRef.current.select();
    }
  }, [editingName]);

  const patch = (p) => onConfigChange({ ...config, ...p });
  const setTeamSetting = (v) => patch({ teamSetting: v });
  const setShowSizesModal = (v) => patch({ showSizesModal: v });
  const setApplicationSizes = (v) => patch({ applicationSizes: v });

  const updatePricing = (size, field, value) => {
    const next = { ...pricing, [size]: { ...pricing[size], [field]: value } };
    const baseNum = parseFloat(next[size].base) || 0;
    const dealerNum = parseFloat(next[size].dealer) || 0;
    const fundNum = parseFloat(next[size].fund) || 0;
    const dealerAmt = next[size].dealerUnit === "$" ? dealerNum : baseNum * dealerNum / 100;
    const fundAmt = next[size].fundUnit === "$" ? fundNum : baseNum * fundNum / 100;
    next[size].retail = (baseNum + dealerAmt + ((next.fundraisingOn ?? (store?.fundraisingEnabled === true)) ? fundAmt : 0)).toFixed(2);
    patch({ pricing: next });
  };
  const fundOn = store?.fundraisingEnabled === true;
  const priceGridCols = fundOn ? "60px 80px 1fr 1fr 1fr 80px" : "60px 80px 1fr 1fr 80px";

  return (
    <div>
      <div style={{
        background: "#fff", border: "1px solid #ececf0", borderRadius: 12,
        boxShadow: "0 1px 2px rgba(20,20,30,.03)", padding: 28
      }}>
        {/* Top row: product name + actions */}
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 24, gap: 16 }}>
          <div style={{ minWidth: 0, flex: 1 }}>
            {editingName ?
            <input
              ref={nameInputRef}
              value={product.title || ""}
              placeholder="[product name]"
              onChange={(e) => onProductChange && onProductChange({ ...product, title: e.target.value })}
              onBlur={() => setEditingName(false)}
              onKeyDown={(e) => {if (e.key === "Enter" || e.key === "Escape") setEditingName(false);}}
              style={{
                fontSize: 20, fontWeight: 700, color: "#0e0e10",
                border: "1px solid #d4d4d8", borderRadius: 6, padding: "4px 12px",
                outline: 0, background: "#fff", width: "100%", maxWidth: 460,
                fontFamily: "inherit"
              }} /> :


            <button
              onClick={() => setEditingName(true)}
              title="Edit product name"
              style={{
                background: "transparent", border: 0, padding: 0, cursor: "text",
                display: "inline-flex", alignItems: "center", gap: 12,
                color: "#0e0e10"
              }}>
                <h2 style={{ fontSize: 20, fontWeight: 700, margin: 0, color: "#0e0e10" }}>
                  {product.title || "[product name]"}
                </h2>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#6b6b72" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
                  <path d="M12 20h9" />
                  <path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z" />
                </svg>
              </button>
            }
            <div style={{ fontSize: 13, color: "#6b6b72", marginTop: 4 }}>
              {product.styleName || "Set-in Faux, Full button Jersey"}
            </div>
            <div style={{ marginTop: 12 }}>
              <ProductStatusBadge ready={sizesConfirmed} />
            </div>
            {total > 1 &&
            <div style={{ fontSize: 11, color: "#9a9aa1", fontWeight: 700, letterSpacing: ".10em", marginTop: 8 }}>
                ITEM {index + 1} OF {total}
              </div>
            }
          </div>

          <div style={{ display: "inline-flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
            <button
              onClick={onDelete}
              style={{
                background: "#fff", color: "#0e0e10",
                border: "1px solid #d4d4d8", borderRadius: 6, padding: "12px 16px",
                fontSize: 13, fontWeight: 600, cursor: "pointer",
                display: "inline-flex", alignItems: "center", gap: 8
              }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="3 6 5 6 21 6" />
                <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
                <path d="M10 11v6" />
                <path d="M14 11v6" />
                <path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2" />
              </svg>
              Delete Product
            </button>
            {pteRestricted(product) && <button data-tour={sizesConfirmed ? undefined : "confirm-sizes"} onClick={() => setShowSizesModal(true)} style={{
              background: sizesConfirmed ? "#1f9d55" : "#0e0e10", color: "#fff",
              border: 0, borderRadius: 6, padding: "12px 24px",
              fontSize: 13, fontWeight: 700, cursor: "pointer",
              display: "inline-flex", alignItems: "center", gap: 8
            }}>
              {sizesConfirmed && <IconCheck size={14} style={{ strokeWidth: 3 }} />}
              {sizesConfirmed ? "Application Sizes Confirmed" : "Confirm Application Sizes"}
            </button>}
          </div>
        </div>

        {/* Made-to-order notice — restricted sources only */}
        {pteRestricted(product) && (
        <div style={{ display: "flex", gap: 10, alignItems: "flex-start", background: "#fff8ef", border: "1px solid #f2e2c9", borderRadius: 8, padding: "10px 14px", marginBottom: 16 }}>
          <span style={{ color: "#b06f1e", display: "inline-flex", marginTop: 1 }}><IconAlert size={15} /></span>
          <span style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.5 }}><strong style={{ color: "#0e0e10" }}>This item is made to order.</strong> Its design cannot be changed after it is added to the store, and no changes can be made after its first order.</span>
        </div>
        )}

        {/* Main three-column row */}
        <div style={{ display: "grid", gridTemplateColumns: "260px 320px 1fr", gap: 16, alignItems: "stretch" }}>
          {/* Image */}
          <div style={{
            background: "#f1f2f4", borderRadius: 8,
            display: "flex", alignItems: "center", justifyContent: "center",
            padding: 24
          }}>
            <div style={{ width: 160, aspectRatio: "2 / 3", maxHeight: "100%" }}>
              {product.thumbnail || <DefaultProductThumb store={store} product={product} />}
            </div>
          </div>

          {/* Product Options */}
          <div style={{ border: "1px solid #ececf0", borderRadius: 8, padding: 24, display: "flex", flexDirection: "column" }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10", marginBottom: 16 }}>
              Product Options
            </div>
            <div style={{ flex: 1 }}>
              {[
              { key: "optRequired", label: "Team Required", tipTitle: "Team Required", tipBody: "Mandatory gear that rostered players must purchase to participate (e.g., home/away uniforms, warm-ups). The player is responsible for covering the full cost of these items at checkout." },
              { key: "optSupplied", label: "Team Supplied", tipTitle: "Team Supplied", tipBody: "Mandatory participation gear that has already been paid for collectively (e.g., through team sign-up fees or fundraisers). Players must still select their sizes, but they will pay $0 for these items at checkout." }].
              map((opt) =>
              <div key={opt.key} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 0" }}>
                  <BundleToggle on={!!config[opt.key]} onChange={(v) => patch(
                  // A product is Team Required OR Team Supplied — never both. Toggling
                  // on locks Category to Team Gear; both off clears it (selection required).
                  v ?
                  { optRequired: opt.key === "optRequired", optSupplied: opt.key === "optSupplied", storeCategory: "Team Gear", storeSubcategory: "", catError: false } :
                  { [opt.key]: false, storeCategory: "", storeSubcategory: "" }
                )} />
                  <span style={{ fontSize: 14, color: "#0e0e10" }}>{opt.label}</span>
                  <InfoTooltip title={opt.tipTitle} body={opt.tipBody} />
                </div>
              )}
              {(() => {
                const tOn = !!(config.optRequired || config.optSupplied);
                const subs = (((window.__prodCats || []).find((c) => c.name === (tOn ? "Team Gear" : config.storeCategory))) || {}).subs || [];
                return (
                  <div style={{ marginTop: 10, display: "grid", gap: 8 }}>
                    {tOn ?
                    <div style={{ display: "flex", alignItems: "center", gap: 8, height: 36, boxSizing: "border-box", border: "1px solid #ececf0", borderRadius: 6, padding: "0 10px", fontSize: 12.5, background: "#fafafb", color: "#0e0e10", fontWeight: 600 }}>Team Gear<span style={{ marginLeft: "auto", display: "inline-flex", color: "#9a9aa1" }}><IconLock size={12} /></span></div> :
                    <select value={config.storeCategory || ""} onChange={(e) => patch({ storeCategory: e.target.value, storeSubcategory: "", catError: false })} style={{ width: "100%", height: 36, boxSizing: "border-box", border: "1px solid " + (config.catError ? "#e1251b" : "#d4d4d8"), borderRadius: 6, padding: "0 10px", fontSize: 12.5, fontFamily: "inherit", outline: "none", background: "#fff", color: "#0e0e10" }}>
                      <option value="">Select a category *</option>
                      {(window.__prodCats || []).map((c) => <option key={c.id} value={c.name}>{c.name}</option>)}
                    </select>}
                    <select value={config.storeSubcategory || ""} onChange={(e) => patch({ storeSubcategory: e.target.value })} disabled={subs.length === 0} style={{ width: "100%", height: 36, boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 10px", fontSize: 12.5, fontFamily: "inherit", outline: "none", background: "#fff", color: "#0e0e10" }}>
                      <option value="">{subs.length === 0 ? "No subcategories" : "No subcategory"}</option>
                      {subs.map((s) => <option key={s} value={s}>{s}</option>)}
                    </select>
                    {config.catError && <div style={{ fontSize: 11.5, color: "#e1251b", fontWeight: 600 }}>Category is required — items no longer default to Fan Gear.</div>}
                    {store?.storeType === "league" && (
                      <RosterAssignField variant="dropdown" direction="down" value={config.rosters || []} onChange={(ids) => patch({ rosters: ids })} accent="#e1251b" minOne={tOn} store={store} />
                    )}
                  </div>
                );
              })()}
            </div>
            <div style={{ marginTop: 20 }}>
              <button style={{
                width: "100%",
                background: "#fff", border: "1px solid #ececf0", borderRadius: 6,
                padding: "12px", fontSize: 13, color: "#0e0e10", cursor: "pointer",
                display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, fontWeight: 500
              }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                  <path d="M4 14L14 4l3 3-10 10H4z" fill="#3acc7a" />
                  <path d="M14 4l3 3 3-3-3-3z" fill="#e1251b" />
                  <path d="M17 7l3-3" stroke="#2563eb" strokeWidth="1.5" />
                </svg>
                Customize
              </button>
            </div>
          </div>

          {/* Price settings — shared Governing-rule-3 card ($ / % mode) */}
          <PriceSettingsCard
            pricing={pricing}
            onChange={(next) => patch({ pricing: next })}
            fundOn={fundOn}
            covered={teamSetting === "team-supplied"} />
        </div>
      </div>

            {/* Sizes confirmation modal */}
      <ConfirmSizesModal
        open={showSizesModal}
        product={product}
        store={store}
        rows={applicationSizes}
        onChange={setApplicationSizes}
        onClose={() => setShowSizesModal(false)}
        onConfirm={() => patch({ sizesConfirmed: true, showSizesModal: false })} />
      
    </div>);

}

