// ─────────── Unpublish warning modals ───────────
// Two variants:
//  - "locked": at least one rostered player has already ordered. Offers
//    "Keep Published for Now" + "Go to Pending Orders" (routes to the order).
//  - "confirm": no one has ordered yet — confirmation w/ Cancel + Unpublish.
function UnpublishWarningModal({ open, variant = "confirm", onClose, onConfirm, onGoToPending }) {
  const isLocked = variant === "locked";
  return (
    <Modal open={open} onClose={onClose} width={480}>
      <div style={{ padding: "20px 28px 28px", position: "relative" }}>
        <button onClick={onClose} aria-label="Close" style={{
          position: "absolute", top: 16, right: 16,
          background: "transparent", border: 0, cursor: "pointer",
          padding: 4, color: "#6b6b72", display: "inline-flex"
        }}>
          <IconX size={20} />
        </button>

        <div style={{
          display: "flex", flexDirection: "column", alignItems: "center",
          padding: "28px 8px 12px"
        }}>
          <div style={{
            width: 72, height: 72, borderRadius: "50%",
            background: isLocked ? "#fdecec" : "#f4f4f6",
            color: isLocked ? "#e1251b" : "#6b6b72",
            display: "inline-flex", alignItems: "center", justifyContent: "center",
            marginBottom: 24
          }}>
            {isLocked ?
            <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <rect x="4" y="11" width="16" height="10" rx="2" />
                <path d="M8 11V8a4 4 0 0 1 8 0v3" />
              </svg> :

            <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="3 6 5 6 21 6" />
                <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
                <path d="M10 11v6" />
                <path d="M14 11v6" />
                <path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2" />
              </svg>
            }
          </div>

          <h3 style={{
            fontSize: 20, fontWeight: 700, margin: 0, marginBottom: 16,
            color: "#0e0e10", textAlign: "center"
          }}>
            {isLocked ? "Active Orders Exist for This Item" : "Unpublish Required Product?"}
          </h3>
          <p style={{
            fontSize: 14, color: "#6b6b72", lineHeight: 1.55,
            textAlign: "center", margin: 0, maxWidth: 420
          }}>
            {isLocked ?
            "This item has already been ordered by at least one rostered player. To prevent uniform mismatch issues with the manufacturer, you must cancel the existing pending orders before unpublishing or changing this product." :
            "This is a Team Required item, but since no rostered players have ordered it yet, it can be safely hidden. Your configurations will be saved, but you must republish it to make it available again."}
          </p>
        </div>

        <div style={{
          display: "flex", gap: 12, marginTop: 28,
          justifyContent: "stretch"
        }}>
          {isLocked ?
          <React.Fragment>
            <button onClick={onClose} style={{
              flex: 1, background: "#fff", color: "#0e0e10",
              border: "1px solid #d4d4d8", borderRadius: 6,
              padding: "12px 24px", fontSize: 14, fontWeight: 600, cursor: "pointer"
            }}>Keep Published for Now</button>
            <button onClick={onGoToPending} style={{
              flex: 1, background: "#0e0e10", color: "#fff",
              border: 0, borderRadius: 6, padding: "16px 24px",
              fontSize: 14, fontWeight: 700, cursor: "pointer"
            }}>Go to Pending Orders</button>
          </React.Fragment> :

          <React.Fragment>
              <button onClick={onClose} style={{
              flex: 1, background: "#fff", color: "#0e0e10",
              border: "1px solid #d4d4d8", borderRadius: 6,
              padding: "12px 24px", fontSize: 14, fontWeight: 600, cursor: "pointer"
            }}>Cancel</button>
              <button onClick={onConfirm} style={{
              flex: 1, background: "#0e0e10", color: "#fff",
              border: 0, borderRadius: 6, padding: "16px 24px",
              fontSize: 14, fontWeight: 700, cursor: "pointer"
            }}>Unpublish</button>
            </React.Fragment>
          }
        </div>
      </div>
    </Modal>);

}

