// Real uniform photos, grouped by garment type, mapped deterministically so a
// given product always shows the same thumbnail.
const ORDER_JERSEY_PHOTOS = [
"assets/products/jersey-grizzlies.png",
"assets/products/jersey-lancers.png",
"assets/products/jersey-padres.png",
"assets/products/jersey-warriors.png",
"assets/products/jersey-asteroid.png"];

const ORDER_PANTS_PHOTOS = ["assets/products/pants-navy.png", "assets/products/pants-orange.png"];
const ORDER_SHORTS_PHOTOS = ["assets/products/shorts-green.png", "assets/products/shorts-navy.png"];

function orderPhotoFor(product) {
  const kind = product?.kind;
  const title = (product?.title || "").toLowerCase();
  let pool;
  if (kind === "shorts") {
    pool = title.includes("pant") ? ORDER_PANTS_PHOTOS : ORDER_SHORTS_PHOTOS;
  } else {
    // jersey, backpack, and anything else fall back to the jersey set
    pool = ORDER_JERSEY_PHOTOS;
  }
  const key = String(product?.title || product?.thumbLabel || "uniform");
  let h = 0;
  for (let i = 0; i < key.length; i++) h = h * 31 + key.charCodeAt(i) >>> 0;
  return pool[h % pool.length];
}

function OrderThumb({ product, size = "row" }) {
  const big = size === "big";
  const w = big ? 180 : 50;
  const h = big ? 240 : 66;
  return (
    <div style={{
      width: w, height: h, background: "#f1f2f4", borderRadius: big ? 8 : 6,
      display: "flex", alignItems: "center", justifyContent: "center",
      flexShrink: 0, overflow: "hidden", padding: big ? 12 : 4
    }}>
      <img
        src={__asset(orderPhotoFor(product))}
        alt={product?.title || "Uniform"}
        style={{ width: "100%", height: "100%", objectFit: "contain", display: "block" }} />
      
    </div>);

}

function ProductThumbPair({ product, store, kind, variant }) {
  const merged = { ...(product || {}), kind: product?.kind || kind };
  return <OrderThumb product={merged} />;
}

function ProductCell({ product, store }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 16, minWidth: 0 }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4, flexShrink: 0 }}>
        <ProductThumbPair product={product} store={store} kind={product.kind} />
        <div style={{ fontSize: 9, color: "#9a9aa1", fontWeight: 500, letterSpacing: ".02em", textAlign: "center", lineHeight: 1.2, maxWidth: 124 }}>
          {product.title?.toUpperCase()}
        </div>
      </div>
    </div>);

}

// ─────────── Sub-tab pill row ───────────
// Clean segmented control — gray track, raised white active segment (inspo: dashboard-inspo-1).
function SegmentedControl({ tabs, value, onChange, anchor }) {
  return (
    <div style={{ display: "inline-flex", alignItems: "center", alignSelf: "flex-start", gap: 2, background: "#f4f4f5", border: "1px solid #e4e4e7", borderRadius: 10, padding: 3 }} data-comment-anchor={anchor}>
      {tabs.map((t) => {
        const active = value === t.id;
        return (
          <button key={t.id} onClick={() => onChange(t.id)} style={{
            display: "inline-flex", alignItems: "center", gap: 8, height: 32, boxSizing: "border-box",
            padding: "0 20px", borderRadius: 7, border: 0, cursor: "pointer", fontFamily: "inherit",
            background: active ? "#fff" : "transparent",
            color: active ? "#0e0e10" : "#6b6b72",
            fontSize: 13, fontWeight: 600, whiteSpace: "nowrap",
            boxShadow: active ? "0 1px 3px rgba(20,20,30,.12), 0 0 0 1px #e4e4e7" : "none",
            transition: "background .12s, color .12s, box-shadow .12s"
          }}
          onMouseEnter={(e) => { if (!active) e.currentTarget.style.color = "#0e0e10"; }}
          onMouseLeave={(e) => { if (!active) e.currentTarget.style.color = "#6b6b72"; }}>
            {t.label}
            {t.count != null && <span style={{ fontSize: 11.5, fontWeight: 700, fontVariantNumeric: "tabular-nums", borderRadius: 5, padding: "2px 6px", background: active ? "#f4f4f5" : "#e9e9ec", color: active ? "#52525b" : "#8e8e96" }}>{t.count}</span>}
          </button>);
      })}
    </div>);
}

// Shared sub-nav chip row — single source of truth for the Products / Orders /
// Settings tab pills. tabs: [{ id, label, Icon?, count? }]
function SubNavChips({ tabs, value, onChange, anchor }) {
  return (
    <div style={{ display: "flex", gap: 12 }} data-comment-anchor={anchor}>
      {tabs.map((t) => {
        const active = value === t.id;
        const pillBg = active ? "#0e0e10" : "#fff";
        return (
          <button key={t.id} onClick={() => onChange(t.id)} style={{
            background: pillBg,
            color: active ? "#fff" : "#0e0e10",
            border: `1px solid ${active ? "#0e0e10" : "#d4d4d8"}`,
            padding: "8px 24px", borderRadius: 999,
            fontSize: 13, fontWeight: 600, cursor: "pointer",
            display: "inline-flex", alignItems: "center", gap: 8,
            whiteSpace: "nowrap", transition: "all .12s", fontFamily: "inherit"
          }}>
            {t.Icon && <t.Icon size={16} color={active ? "#fff" : "#0e0e10"} bg={pillBg} />}
            {t.label}{t.count != null && <CountBadge n={t.count} active={active} />}
          </button>);
      })}
    </div>);
}

// Small count badge (gray circle) used in sub-tab pills.
