// ─────────── Rows-per-page + pagination footer ───────────
function AllOrdersPager({ total, page, pageSize, onPage, onPageSize }) {
  const pageCount = Math.max(1, Math.ceil(total / pageSize));
  const from = total === 0 ? 0 : page * pageSize + 1;
  const to = Math.min(total, (page + 1) * pageSize);
  const nums = [];
  for (let i = 0; i < pageCount; i++) {
    if (i === 0 || i === pageCount - 1 || Math.abs(i - page) <= 1) nums.push(i);else
    if (nums[nums.length - 1] !== "…") nums.push("…");
  }
  const navBtn = { width: 32, height: 32, borderRadius: 8, border: "1px solid #e4e4e7", background: "#fff", fontSize: 13, cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", color: "#18181b" };
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, marginTop: 16, flexWrap: "wrap" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, fontSize: 13, color: "#71717a" }}>
        <span>Rows per page</span>
        <select value={pageSize} onChange={(e) => onPageSize(Number(e.target.value))} style={{
          height: 36, border: "1px solid #e4e4e7", borderRadius: 8, padding: "0 8px", fontSize: 13, background: "#fff", color: "#18181b", cursor: "pointer"
        }}>
          {[10, 25, 50, 100].map((n) => <option key={n} value={n}>{n}</option>)}
        </select>
        <span style={{ marginLeft: 8 }}>{from}–{to} of {total}</span>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <button style={{ ...navBtn, opacity: page === 0 ? .4 : 1 }} disabled={page === 0} onClick={() => onPage(page - 1)}><IconChevronLeft size={16} /></button>
        {nums.map((n, i) => n === "…" ?
        <span key={"e" + i} style={{ padding: "0 4px", color: "#a1a1aa" }}>…</span> :
        <button key={n} onClick={() => onPage(n)} style={{
          ...navBtn, background: n === page ? "#18181b" : "#fff", color: n === page ? "#fff" : "#18181b",
          fontWeight: n === page ? 700 : 500, borderColor: n === page ? "#18181b" : "#e4e4e7"
        }}>{n + 1}</button>
        )}
        <button style={{ ...navBtn, opacity: page >= pageCount - 1 ? .4 : 1 }} disabled={page >= pageCount - 1} onClick={() => onPage(page + 1)}><IconChevronRight size={16} /></button>
      </div>
    </div>);

}

// ─────────── Shared All Orders experience ───────────
// Owns search / sort / filter / date / column-visibility / selection /
// pagination and renders the toolbar + rich table + pager. Used by both the
// workspace Orders → All Orders tab and the cross-store Overview All Orders page.
function AllOrdersExperience({ orders, columns, store, onOpen, storeFor, toolbarLeft, csvName, exportApi }) {
  const [search, setSearch] = React.useState("");
  const [sort, setSort] = React.useState("none");
  const [filter, setFilter] = React.useState("none");
  const [range, setRange] = React.useState({ start: "", end: "", due: "" });
  const [hidden, setHidden] = React.useState({});
  const [selected, setSelected] = React.useState({});
  const [page, setPage] = React.useState(0);
  const [pageSize, setPageSize] = React.useState(25);
  const [toast, setToast] = React.useState(null);

  const keyFor = (o) => (o.__store?.id ? o.__store.id + "-" : "") + o.id;

  const matches = (o) => {
    if (!search) return true;
    const q = search.toLowerCase();
    return [o.__store?.teamName, o.__store?.storeTitle, o.organization, o.customer, o.rep,
    o.webOrderNum, o.factoryOrderNum, o.cartName, o.orderNum, o.sport, o.shippingGroup, o.product?.title].
    filter(Boolean).some((v) => String(v).toLowerCase().includes(q));
  };

  const view = React.useMemo(() => {
    let out = orders.filter((o) => matches(o) && orderMatchesFilter(o, filter));
    if (range.start) out = out.filter((o) => parseOrderDate(o.dueDate) >= new Date(range.start).getTime());
    if (range.end) out = out.filter((o) => parseOrderDate(o.dueDate) <= new Date(range.end).getTime());
    if (range.due) out = out.filter((o) => parseOrderDate(o.dueDate) === new Date(range.due).getTime());
    if (sort !== "none") {
      out = [...out].sort((a, b) => {
        const va = orderSortValue(a, sort),bv = orderSortValue(b, sort);
        if (typeof va === "number" && typeof bv === "number") return va - bv;
        return String(va).localeCompare(String(bv));
      });
    }
    return out;
    // eslint-disable-next-line
  }, [orders, search, filter, sort, range]);

  // Keep the page in range when the result set shrinks.
  const pageCount = Math.max(1, Math.ceil(view.length / pageSize));
  React.useEffect(() => {if (page > pageCount - 1) setPage(0);}, [pageCount, page]);
  const paged = view.slice(page * pageSize, page * pageSize + pageSize);

  const visibleCols = columns.filter((c) => !hidden[c.key]);
  const selCount = Object.values(selected).filter(Boolean).length;

  const toCSV = (rows) => {
    const head = visibleCols.map((c) => '"' + c.label + '"').join(",");
    const cell = (o, c) => {
      let v;
      if (c.csv) v = c.csv(o, storeFor ? storeFor(o) : store);else
      if (c.key === "status") v = STATUS_STYLES[o.status]?.label || o.status;else
      if (c.key === "store") v = o.__store?.teamName || o.__store?.storeTitle || "";else
      if (c.key === "product") v = o.product?.title || "";else
      v = o[c.key] ?? "";
      return '"' + String(v).replace(/"/g, '""') + '"';
    };
    const body = rows.map((o) => visibleCols.map((c) => cell(o, c)).join(",")).join("\n");
    return head + "\n" + body;
  };
  const download = (rows, name) => {
    try {
      const blob = new Blob([toCSV(rows)], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;a.download = name;
      document.body.appendChild(a);a.click();a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      setToast(`Exported ${rows.length} order${rows.length === 1 ? "" : "s"}`);
    } catch (e) {setToast("Export failed");}
  };

  const selectedRows = view.filter((o) => selected[keyFor(o)]);
  // Lets an embedding view (the Store Close Report) fire the same CSV export,
  // honoring the current column-visibility selection.
  if (exportApi) exportApi.current = () => download(view, csvName || "all-orders.csv");

  // All line items that belong to the same web order (used by the Order View).
  const siblingsOf = (o) => {
    const sib = orders.filter((x) => x.webOrderNum === o.webOrderNum && (x.__store?.id || "") === (o.__store?.id || ""));
    return sib.length ? sib : [o];
  };
  const openWith = (o, initialView) => onOpen({ ...o, __initialView: initialView, __siblings: siblingsOf(o) });

  return (
    <div>
      <div style={{ marginBottom: 16, display: "flex", alignItems: "center", gap: 24, flexWrap: "wrap" }}>
        {toolbarLeft}
        <AllOrdersToolbar
          sort={sort} onSort={setSort}
          filter={filter} onFilter={setFilter}
          range={range} onRange={setRange}
          search={search} onSearch={setSearch}
          onExport={() => download(view, csvName || "all-orders.csv")} />
      </div>

      <AllOrdersBulkBar
        count={selCount}
        onExport={() => download(selectedRows, "selected-orders.csv")}
        onClear={() => setSelected({})} />

      {view.length === 0 ?
      <OrdersEmpty sub="all" search={search} /> :
      <React.Fragment>
        <AllOrdersRichTable
          columns={visibleCols} rows={paged} keyFor={keyFor}
          store={store} onOpen={(o) => openWith(o, "item")} onOpenOrderView={(o) => openWith(o, "order")} storeFor={storeFor}
          allColumns={columns} hidden={hidden}
          onToggleCol={(k) => setHidden((h) => ({ ...h, [k]: !h[k] }))}
          onRestoreCols={() => setHidden({})}
          selected={selected}
          onToggleRow={(k) => setSelected((s) => ({ ...s, [k]: !s[k] }))}
          onToggleAll={() => {
            const allOn = paged.length > 0 && paged.every((r) => selected[keyFor(r)]);
            setSelected((s) => {
              const next = { ...s };
              paged.forEach((r) => {next[keyFor(r)] = !allOn;});
              return next;
            });
          }} />
        <AllOrdersPager
          total={view.length} page={page} pageSize={pageSize}
          onPage={setPage} onPageSize={(n) => {setPageSize(n);setPage(0);}} />
      </React.Fragment>}

      <Toast message={toast} onDone={() => setToast(null)} />
    </div>);

}

// ─────────── Table primitives ───────────
const ORDERS_TABLE_MIN_WIDTH = 1480;

function OrdersTable({ columns, children, footer }) {
  // columns: [{ key, label, w }]
  const [statusInfoOpen, setStatusInfoOpen] = React.useState(false);
  const gridTemplate = columns.map((c) => c.w || "1fr").join(" ") + " 36px";
  return (
    <div style={{
      background: "#fafafb", border: "1px solid #ececf0", borderRadius: 10,
      padding: "4px", overflowX: "auto"
    }}>
      <div style={{ minWidth: ORDERS_TABLE_MIN_WIDTH }}>
        {/* header */}
        <div style={{
          display: "grid", gridTemplateColumns: gridTemplate, gap: 16,
          padding: "16px 24px", fontSize: 11, fontWeight: 700, color: "#9a9aa1",
          letterSpacing: ".08em", textTransform: "uppercase", alignItems: "end",
          borderBottom: "1px solid transparent"
        }}>
          {columns.map((c) =>
          c.key === "status" ?
          <div key={c.key} style={{ textAlign: c.align || "left", display: "inline-flex", alignItems: "center", gap: 4 }}>
            {c.label}
            <button onClick={() => setStatusInfoOpen(true)} title="What do these statuses mean?" aria-label="Status definitions" style={{
              display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 0,
              background: "transparent", border: 0, color: "#9a9aa1", cursor: "pointer", lineHeight: 0
            }}
              onMouseEnter={(e) => e.currentTarget.style.color = "#0e0e10"}
              onMouseLeave={(e) => e.currentTarget.style.color = "#9a9aa1"}>
              <IconInfo size={14} />
            </button>
          </div> :
          <div key={c.key} style={{ textAlign: c.align || "left" }}>{c.label}</div>
          )}
          <div style={{ display: "inline-flex", justifyContent: "flex-end", color: "#9a9aa1", cursor: "pointer" }} title="Add column">
            <IconPlus size={14} />
          </div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 12, paddingBottom: 4 }}>
          {children}
        </div>
        {footer}
      </div>
      <Modal open={statusInfoOpen} onClose={() => setStatusInfoOpen(false)} width={520}>
        <div style={{ padding: "28px 28px" }}>
          <h2 style={{ margin: "0 0 4px", fontSize: 19, fontWeight: 800, color: "#0e0e10", letterSpacing: ".01em" }}>Order Status Guide</h2>
          <p style={{ margin: "0 0 20px", fontSize: 13.5, color: "#6b6b72", lineHeight: 1.5 }}>Each order moves through these stages from placement to delivery.</p>
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            {STATUS_DEFINITIONS.map((d) => {
              const s = STATUS_STYLES[d.key];
              return (
                <div key={d.key} style={{ display: "grid", gridTemplateColumns: "150px 1fr", gap: 16, alignItems: "start" }}>
                  <span style={{
                    display: "inline-flex", alignItems: "center", justifySelf: "start",
                    background: s.bg, color: s.fg, border: `1px solid ${s.border}`,
                    borderRadius: 999, padding: "4px 12px", fontSize: 12, fontWeight: 600, whiteSpace: "nowrap"
                  }}>{s.label}</span>
                  <span style={{ fontSize: 13, color: "#3f3f46", lineHeight: 1.5 }}>{d.desc}</span>
                </div>
              );
            })}
          </div>
        </div>
      </Modal>
    </div>);

}

function OrdersRow({ columns, order, store, onOpen, accent }) {
  const gridTemplate = columns.map((c) => c.w || "1fr").join(" ") + " 36px";
  return (
    <div
      onClick={() => onOpen && onOpen(order)}
      style={{
        display: "grid", gridTemplateColumns: gridTemplate, gap: 16,
        padding: "16px 24px", alignItems: "center",
        background: accent === "highlight" ? "#fcecec" : "#fff",
        borderRadius: 8, cursor: "pointer",
        transition: "background .12s, transform .12s"
      }}
      onMouseEnter={(e) => {if (accent !== "highlight") e.currentTarget.style.background = "#fafafb";}}
      onMouseLeave={(e) => {if (accent !== "highlight") e.currentTarget.style.background = "#fff";}}>
      {columns.map((c) =>
      <div key={c.key} style={{
        fontSize: 13, color: "#0e0e10", minWidth: 0,
        textAlign: c.align || "left",
        overflow: c.noClip ? "visible" : "hidden",
        textOverflow: "ellipsis",
        whiteSpace: c.wrap ? "normal" : "nowrap"
      }}>
          {c.render ? c.render(order, store) : order[c.key] ?? "—"}
        </div>
      )}
      <div />
    </div>);

}

// ─────────── Column definitions ───────────
function commonRightCols({ onOpen }) {
  return [
  { key: "sport", label: "Sport", w: ".9fr" },
  { key: "quantity", label: "Quantity", w: ".7fr", render: (o) => <span style={{ fontVariantNumeric: "tabular-nums" }}>{o.quantity}</span> },
  { key: "shippingGroup", label: "Shipping Group", w: ".9fr" },
  { key: "dueDate", label: "Due/Ship Date", w: "1.2fr", render: (o) => <DueDateCell date={o.dueDate} status={o.status} /> },
  { key: "status", label: "Status", w: "1.3fr", render: (o) => <StatusBadge status={o.status} tracking={o.tracking} refund={o.refund} /> }];

}

// "All Orders" merges rep-placed (My) and fan-placed (Fan) orders into one
// table. It carries both the Rep and Customer columns; rep-placed rows show
// "—" for Customer since there's no external buyer.
function makeAllOrdersColumns() {
  return [
  { key: "product", label: "Product", w: "1.5fr", alwaysOn: true, render: (o, store) => <ProductCell product={o.product} store={store} />, csv: (o) => o.product?.title || "" },
  { key: "organization", label: "Organization", w: "1.1fr", render: (o) =>
    <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span>{o.organization}</span>
      </div>
  },
  { key: "factoryOrderNum", label: "Factory Order #", w: "1fr", render: (o) => <BlueLink>{o.factoryOrderNum}</BlueLink> },
  { key: "webOrderNum", label: "Web Order #", w: "1fr", render: (o) => <BlueLink>{o.webOrderNum}</BlueLink> },
  { key: "cartName", label: "Cart Name", w: "1fr" },
  { key: "customer", label: "Customer", w: "1fr", render: (o) => o.customer || "—" },
  { key: "rep", label: "Rep", w: ".9fr" },
  ...commonRightCols({})];

}

function ReorderBadge() {
  return (
    <span style={{
      display: "inline-flex", padding: "2px 8px", borderRadius: 999,
      background: "#f1f1f3", color: "#6b6b72", fontSize: 11, fontWeight: 600,
      width: "fit-content"
    }}>Reorder</span>);

}

// Distinguishes rep-placed ("My") vs fan-placed ("Fan") rows inside All Orders.
function OrderTypeBadge({ type }) {
  const fan = type === "fan";
  return (
    <span style={{
      display: "inline-flex", padding: "4px 12px", borderRadius: 999,
      background: fan ? "#eef3fb" : "#f1f1f3", color: fan ? "#1e40af" : "#52525a",
      fontSize: 11, fontWeight: 700, letterSpacing: ".02em", width: "fit-content"
    }}>{fan ? "Fan" : "My Order"}</span>);

}

function BlueLink({ children }) {
  return (
    <a href="#" onClick={(e) => {e.preventDefault();e.stopPropagation();}} style={{
      color: "#2563eb", textDecoration: "none", fontVariantNumeric: "tabular-nums"
    }}>{children}</a>);

}

// ─────────── Lists ───────────
function AllOrdersList({ orders, store, onOpen }) {
  const cols = makeAllOrdersColumns();
  return (
    <OrdersTable columns={cols}>
      {orders.map((o) =>
      <OrdersRow key={o.id} columns={cols} order={o} store={store} onOpen={onOpen} accent={o.highlight ? "highlight" : undefined} />
      )}
    </OrdersTable>);

}

// ─────────── Pending Orders ───────────
function MinQuantityRing({ pct, size = 36, strokeWidth = 4, track = "#f1d4d4", color = "#e1251b" }) {
  const r = (size - strokeWidth) / 2;
  const c = 2 * Math.PI * r;
  const dash = c * (pct / 100);
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={track} strokeWidth={strokeWidth} />
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={strokeWidth}
      strokeDasharray={`${dash} ${c - dash}`} strokeDashoffset={c * 0.25}
      transform={`rotate(-90 ${size / 2} ${size / 2})`} strokeLinecap="round" />
    </svg>);

}

function PendingOrdersList({ groups, store, org, onOpen, onSubmit }) {
  // groups: [{ shippingGroup, title, subtitle, pct, fee, rows: [...] }]
  // Containers key off parent-or-team: league stores get one container per
  // division plus one per unassigned team; single-team stores get one container.
  const cols = [
  { key: "check", label: "", w: "24px" },
  { key: "item", label: "Item", w: "1.4fr" },
  { key: "orderDate", label: "Order Date", w: "1fr" },
  { key: "customer", label: "Customer", w: "1.4fr" },
  { key: "teamInfo", label: "Team Info", w: "1.2fr" },
  { key: "player", label: "Player", w: "1fr" },
  { key: "type", label: "Type", w: ".8fr" },
  { key: "size", label: "Size", w: ".6fr" },
  { key: "factory", label: "Factory", w: ".7fr" }];

  const gridTemplate = cols.map((c) => c.w || "1fr").join(" ");
  const [checked, setChecked] = React.useState({});

  // Normalize a pending row into a submission line item.
  const toLine = (r) => ({ id: r.id, product: r.product, size: r.size, qty: r.quantity || 1, customer: r.customer });
  // Where this container's orders ship, from the group's fulfillment mode.
  const shipLabel = (g) => {
    const key = String(g.shippingGroup || "").toLowerCase();
    const grp = ((org && org.groups) || []).find((x) => x.id.toLowerCase() === key);
    if (!grp) return "Shipping to league manager"; // unassigned teams
    const mode = ((org && org.modes) || {})[grp.id] || "league";
    return mode === "teams" ? "Shipping to team managers" : "Shipping to league manager";
  };
  // Build submission groups (dropping empty groups) from a row-predicate.
  const buildGroups = (keep) =>
  groups.
  map((g) => ({ shippingGroup: g.shippingGroup, title: g.title, fee: g.fee, pct: g.pct, rows: g.rows.filter(keep).map(toLine) })).
  filter((g) => g.rows.length > 0);

  const selectedCount = Object.values(checked).filter(Boolean).length;
  const submitRow = (r) => onSubmit && onSubmit(buildGroups((x) => x.id === r.id));
  const submitGroup = (g) => onSubmit && onSubmit([{ shippingGroup: g.shippingGroup, title: g.title, fee: g.fee, pct: g.pct, rows: g.rows.map(toLine) }]);
  const submitSelected = () => onSubmit && onSubmit(buildGroups((x) => checked[x.id]));
  const submitAll = () => onSubmit && onSubmit(buildGroups(() => true));

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 24, paddingBottom: 80 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, background: "#fafafb", border: "1px solid #ececf0", borderRadius: 8, padding: "12px 16px" }}>
        <span style={{ width: 30, height: 30, borderRadius: 7, flexShrink: 0, background: "#fdf6e7", color: "#8a5f10", display: "inline-flex", alignItems: "center", justifyContent: "center" }}><IconBankInbox size={15} /></span>
        <span style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.5 }}>Containers are keyed to a division or team. Team-gear orders here also create <strong style={{ color: "#0e0e10" }}>bank-zone captures</strong> — review and commit proposed players in the My Teams tab.</span>
      </div>
      {groups.map((g) => {
        const allChecked = g.rows.every((r) => checked[r.id]);
        return (
          <div key={g.shippingGroup} style={{
            background: "#fff", border: "1px solid #d4d4d8", borderRadius: 8,
            overflow: "hidden"
          }}>
            {/* group header — team code + rosters */}
            <div style={{ padding: "16px 24px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 24, flexWrap: "wrap" }}>
              <div style={{ display: "flex", flexDirection: "column", gap: 8, minWidth: 240 }}>
                <div style={{ fontSize: 14, fontWeight: 700, letterSpacing: ".03em", color: "#09090b", textTransform: "uppercase" }}>
                  {g.title || `SHIPPING GROUP: ${g.shippingGroup}`}
                </div>
                {g.subtitle && g.subtitle !== "Unassigned team" &&
                <div style={{ fontSize: 14, fontWeight: 500, letterSpacing: ".03em", color: "#71717a" }}>{g.subtitle}</div>
                }
                <div style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12, fontWeight: 700, color: "#52525a" }}>
                  <IconVan size={15} style={{ flexShrink: 0, color: "#71717a" }} />
                  {shipLabel(g)}
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 24 }}>
                {g.pct < 100 &&
                <div style={{ display: "flex", alignItems: "flex-start", gap: 4 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <MinQuantityRing pct={g.pct} size={16} strokeWidth={4} track="#e5e7eb" color="#f87171" />
                    <div style={{ display: "flex", flexDirection: "column" }}>
                      <span style={{ fontSize: 12, fontWeight: 500, lineHeight: "16px", letterSpacing: ".03em", color: "#f87171", whiteSpace: "nowrap" }}>Minimum Quantity</span>
                      <span style={{ fontSize: 10, color: "#f87171" }}>{g.pct}%</span>
                    </div>
                  </div>
                  <span title={`Below the factory minimum — a $${(g.fee || 0).toFixed(2)} fee applies.`} style={{
                    width: 16, height: 16, borderRadius: "50%", background: "#fff",
                    border: "1px solid #09090b", color: "#09090b", flexShrink: 0,
                    display: "inline-flex", alignItems: "center", justifyContent: "center",
                    fontSize: 9, fontWeight: 800, cursor: "help"
                  }}>i</span>
                </div>
                }
                <button onClick={() => submitGroup(g)} style={{
                  background: "#0e0e10", color: "#fff", border: 0, borderRadius: 6, height: 36,
                  padding: "0 20px", fontSize: 13, fontWeight: 700, letterSpacing: ".02em",
                  cursor: "pointer", whiteSpace: "nowrap", transition: "background .12s"
                }}
                  onMouseEnter={(e) => e.currentTarget.style.background = "#e1251b"}
                  onMouseLeave={(e) => e.currentTarget.style.background = "#0e0e10"}>Submit Group</button>
              </div>
            </div>

            {/* column headers */}
            <div style={{
              display: "grid", gridTemplateColumns: gridTemplate, gap: 12,
              padding: "8px 24px", borderBottom: "1px solid #f4f4f5",
              background: "#fff", fontSize: 11, fontWeight: 700, color: "#71717a",
              letterSpacing: ".06em", textTransform: "uppercase", alignItems: "center"
            }}>
              <Checkbox
                checked={allChecked}
                onChange={(v) => {
                  setChecked((c) => {
                    const n = { ...c };
                    g.rows.forEach((r) => {n[r.id] = v;});
                    return n;
                  });
                }} />
              
              {cols.slice(1).map((c) =>
              <div key={c.key} style={{ textAlign: c.align || "left" }}>{c.label}</div>
              )}
            </div>

            {/* rows */}
            <div style={{ background: "#fff" }}>
              {g.rows.map((r, i) =>
              <div key={r.id}
              onClick={() => onOpen && onOpen(r)}
              style={{
                display: "grid", gridTemplateColumns: gridTemplate, gap: 12,
                padding: "16px 24px", alignItems: "center",
                borderTop: i === 0 ? "none" : "1px solid #f4f4f5",
                cursor: "pointer", transition: "background .12s"
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = "#fafafb"}
              onMouseLeave={(e) => e.currentTarget.style.background = "#fff"}>
                  <div onClick={(e) => e.stopPropagation()}>
                    <Checkbox checked={!!checked[r.id]} onChange={(v) => setChecked((c) => ({ ...c, [r.id]: v }))} />
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, maxWidth: 150 }}>
                    <ProductThumbPair product={r.product} store={store} kind={r.product?.kind || "jersey"} />
                    <div style={{ textAlign: "center" }}>
                      <div style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".03em", color: "#09090b", lineHeight: "16px" }}>{r.itemName || r.product?.title}</div>
                      {r.itemName &&
                      <div style={{ fontSize: 12, color: "#71717a", lineHeight: "16px", letterSpacing: ".01em", marginTop: 2 }}>{r.product?.title}</div>
                      }
                    </div>
                  </div>
                  <div style={{ fontSize: 13, color: "#71717a" }}>{r.orderDate}</div>
                  <div style={{ fontSize: 12 }}>
                    <div style={{ fontWeight: 700, color: "#09090b", letterSpacing: ".03em" }}>{r.customer}</div>
                    <div style={{ color: "#71717a", marginTop: 2 }}>{r.customerEmail}</div>
                  </div>
                  <div style={{ fontSize: 12 }}>
                    <div style={{ fontWeight: 700, color: "#09090b", letterSpacing: ".03em" }}>{r.teamInfo || store?.teamName}</div>
                    {r.teamRoster && <div style={{ color: "#71717a", marginTop: 2 }}>{r.teamRoster}</div>}
                  </div>
                  <div style={{ fontSize: 13, color: "#71717a" }}>{r.player || "—"}</div>
                  <div>{(() => {
                    const t = r.type || "Team Gear";
                    const meta = { "Team Required": ["REQUIRED", PTE_C.ink, "#fff"], "Team Supplied": ["SUPPLIED", PTE_C.z100, PTE_C.z700], "Fan Gear": ["FAN GEAR", "#fff", PTE_C.z500, { border: "1px solid " + PTE_C.z200 }] }[t] || ["TEAM GEAR", PTE_C.z100, PTE_C.z700];
                    return <span style={pteChip(meta[1], meta[2], meta[3])}>{meta[0]}</span>;
                  })()}</div>
                  <div style={{ fontSize: 13, color: "#71717a" }}>{r.size}</div>
                  <div style={{ fontSize: 13, color: "#71717a" }}>{r.factory}</div>
                </div>
              )}
            </div>
          </div>);

      })}

      <FloatingActionBar>
        {selectedCount > 0 &&
        <button onClick={submitSelected} style={{
          background: "#fff", color: "#0e0e10", border: "1px solid #0e0e10", borderRadius: 6,
          padding: "12px 24px", fontSize: 13, fontWeight: 700, letterSpacing: ".04em",
          cursor: "pointer", whiteSpace: "nowrap"
        }}>Submit Selected ({selectedCount})</button>
        }
        <button onClick={submitAll} style={{
          background: "#0e0e10", color: "#fff", border: 0, borderRadius: 6,
          padding: "12px 24px", fontSize: 13, fontWeight: 700, letterSpacing: ".04em",
          cursor: "pointer", whiteSpace: "nowrap"
        }}>Submit All</button>
      </FloatingActionBar>
    </div>);

}

// ─────────── Submit Order modal ───────────
// Scalable order-review modal shown when a Rep submits one pending order or all
// of them. `groups` is an array of { shippingGroup, fee, rows:[{product,size,qty}] }.
const SUBMIT_UNIT_PRICE = (p) =>
p?.kind === "jersey" ? 48.95 :
p?.kind === "shorts" ? 32.00 :
p?.kind === "backpack" ? 40.00 : 45.00;

function SubmitOrderModal({ open, groups = [], store, onClose, onConfirm }) {
  const [po, setPo] = React.useState("8084640218");
  if (!open || !groups.length) return null;

  const groupSubtotal = (g) => g.rows.reduce((s, r) => s + SUBMIT_UNIT_PRICE(r.product) * (r.qty || 1), 0);
  const subtotal = groups.reduce((s, g) => s + groupSubtotal(g), 0);
  const feeTotal = groups.reduce((s, g) => s + (g.fee || 0), 0);
  const total = subtotal + feeTotal;
  const itemCount = groups.reduce((s, g) => s + g.rows.reduce((n, r) => n + (r.qty || 1), 0), 0);
  const fmt = (n) => `$${n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}`;
  const plural = itemCount === 1 ? "order" : "orders";

  const shipName = store?.contactName || "George Harrison";

  const label = { fontSize: 12, fontWeight: 800, letterSpacing: ".10em", color: "#0e0e10", textTransform: "uppercase" };
  const subLabel = { fontSize: 12, fontWeight: 700, letterSpacing: ".06em", color: "#9a9aa1", fontStyle: "italic", textTransform: "uppercase" };

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 120,
      background: "rgba(20,20,30,.5)",
      display: "flex", alignItems: "center", justifyContent: "center", padding: 24,
      animation: "fadeIn .15s ease"
    }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: "#fff", borderRadius: 12, width: 1080, maxWidth: "100%", maxHeight: "92vh",
        display: "flex", flexDirection: "column", overflow: "hidden",
        boxShadow: "0 28px 64px rgba(20,20,30,.28)", animation: "popIn .18s cubic-bezier(.2,.9,.3,1.2)"
      }}>
        {/* Header */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "24px 32px", borderBottom: "1px solid #ececf0", flexShrink: 0
        }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 16 }}>
            <h2 style={{ fontFamily: "Archivo, sans-serif", fontSize: 21, fontWeight: 800, margin: 0, letterSpacing: "-.01em" }}>
              Submit {groups.length > 1 ? "Orders" : "Order"}
            </h2>
            <span style={{ fontSize: 13, color: "#6b6b72", fontWeight: 500 }}>
              {itemCount} {itemCount === 1 ? "item" : "items"} · {groups.length} shipping {groups.length === 1 ? "group" : "groups"}
            </span>
          </div>
          <button onClick={onClose} aria-label="Close" style={{
            width: 36, height: 36, borderRadius: 8, border: 0, background: "transparent",
            cursor: "pointer", color: "#6b6b72", display: "inline-flex", alignItems: "center", justifyContent: "center"
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = "#f4f4f6"}
          onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
            <IconX size={20} />
          </button>
        </div>

        {/* Body */}
        <div style={{ display: "grid", gridTemplateColumns: "320px 1fr", gap: 0, flex: 1, minHeight: 0 }}>
          {/* Left rail — shipping / payment / billing */}
          <div style={{ padding: "28px 28px 28px 32px", borderRight: "1px solid #ececf0", overflowY: "auto" }}>
            <div style={{ ...label, marginBottom: 16 }}>Shipping Details</div>
            <div style={{ display: "flex", alignItems: "flex-start", gap: 12, marginBottom: 32 }}>
              <div style={{ fontSize: 14, lineHeight: 1.6, fontWeight: 700, color: "#0e0e10" }}>
                {shipName}<br />
                <span style={{ fontWeight: 600 }}>101760 Beatle Dr.</span><br />
                <span style={{ fontWeight: 600 }}>Bakersfield, CA 90564</span>
              </div>
              <button aria-label="Edit shipping" style={{
                background: "transparent", border: 0, cursor: "pointer", color: "#9a9aa1",
                padding: 2, marginTop: 2, display: "inline-flex"
              }}
              onMouseEnter={(e) => e.currentTarget.style.color = "#0e0e10"}
              onMouseLeave={(e) => e.currentTarget.style.color = "#9a9aa1"}>
                <IconEdit size={15} />
              </button>
            </div>

            <div style={{ ...label, marginBottom: 12 }}>Payment Method</div>
            <label style={{ display: "block", fontSize: 13, color: "#6b6b72", marginBottom: 8 }}>PO Number</label>
            <input value={po} onChange={(e) => setPo(e.target.value)} style={{
              width: "100%", border: "1px solid #d4d4d8", borderRadius: 6, padding: "12px 12px",
              fontSize: 14, color: "#0e0e10", outline: "none", marginBottom: 32
            }}
            onFocus={(e) => e.currentTarget.style.borderColor = "#0e0e10"}
            onBlur={(e) => e.currentTarget.style.borderColor = "#d4d4d8"} />

            <div style={{ ...label, marginBottom: 12 }}>Billing Address</div>
            <div style={{ fontSize: 13.5, lineHeight: 1.6, color: "#6b6b72" }}>
              Same as shipping address
            </div>
          </div>

          {/* Right rail — summary + grouped details */}
          <div style={{ display: "flex", flexDirection: "column", minHeight: 0 }}>
            <div style={{ padding: "28px 32px 16px", borderBottom: "1px solid #f1f1f3", flexShrink: 0 }}>
              <div style={{ ...label, marginBottom: 16 }}>Order Summary</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <SummaryLine label="Subtotal" value={fmt(subtotal)} />
                {feeTotal > 0 && <SummaryLine label="Minimum Quantity Fee" value={fmt(feeTotal)} accent />}
                <div style={{ borderTop: "1px solid #ececf0", margin: "4px 0" }} />
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                  <span style={{ fontSize: 15, fontWeight: 800, color: "#0e0e10" }}>TOTAL</span>
                  <span style={{ fontSize: 19, fontWeight: 800, color: "#0e0e10", fontVariantNumeric: "tabular-nums" }}>{fmt(total)}</span>
                </div>
              </div>
            </div>

            <div style={{ padding: "20px 32px 28px", overflowY: "auto", flex: 1, minHeight: 0 }}>
              <div style={{ ...label, marginBottom: 16 }}>Order Details</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                {groups.map((g) =>
                <div key={g.shippingGroup} style={{
                  border: "1px solid #ececf0", borderRadius: 10, overflow: "hidden", background: "#fff"
                }}>
                    <div style={{
                    display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
                    padding: "16px 16px", background: "#fafafb", borderBottom: "1px solid #f1f1f3"
                  }}>
                      <div>
                        <div style={subLabel}>Shipping Group</div>
                        <div style={{ fontSize: 15, fontWeight: 800, color: "#0e0e10", marginTop: 2, textTransform: "uppercase" }}>{g.title || g.shippingGroup}</div>
                      </div>
                      {g.fee > 0 &&
                    <div style={{ textAlign: "right" }}>
                          <span style={{ fontSize: 11.5, fontWeight: 700, color: "#e1251b", marginRight: 8 }}>Minimum Quantity Fee</span>
                          <span style={{ fontSize: 15, fontWeight: 800, color: "#e1251b", fontVariantNumeric: "tabular-nums" }}>{fmt(g.fee)}</span>
                        </div>
                    }
                    </div>
                    <div>
                      {g.rows.map((r, i) =>
                    <div key={r.id || i} style={{
                      display: "grid", gridTemplateColumns: "1fr 52px 36px 88px", gap: 16,
                      alignItems: "center", padding: "16px 16px",
                      borderTop: i === 0 ? "none" : "1px solid #f3f3f4"
                    }}>
                          <div style={{ display: "flex", alignItems: "center", gap: 12, minWidth: 0 }}>
                            <OrderThumb product={r.product} store={store} />
                            <div style={{ fontSize: 11, fontWeight: 700, color: "#0e0e10", letterSpacing: ".02em", lineHeight: 1.35 }}>
                              {(r.product?.title || "Item").toUpperCase()}
                            </div>
                          </div>
                          <div style={{ fontSize: 13, color: "#6b6b72", textAlign: "center" }}>{r.size || "—"}</div>
                          <div style={{ fontSize: 13, color: "#6b6b72", textAlign: "center", fontVariantNumeric: "tabular-nums" }}>{r.qty || 1}</div>
                          <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10", textAlign: "right", fontVariantNumeric: "tabular-nums" }}>
                            {fmt(SUBMIT_UNIT_PRICE(r.product) * (r.qty || 1))}
                          </div>
                        </div>
                    )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 16,
          padding: "16px 32px", borderTop: "1px solid #ececf0", flexShrink: 0
        }}>
          <button onClick={onClose} style={{
            background: "transparent", border: 0, cursor: "pointer",
            fontSize: 13.5, fontWeight: 700, letterSpacing: ".04em", color: "#0e0e10", padding: "12px 16px"
          }}>Cancel</button>
          <button onClick={() => onConfirm && onConfirm({ po, total, itemCount, groups })} style={{
            background: "#0e0e10", color: "#fff", border: 0, borderRadius: 6,
            padding: "12px 32px", fontSize: 13.5, fontWeight: 700, letterSpacing: ".04em", cursor: "pointer",
            display: "inline-flex", alignItems: "center", gap: 8
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = "#26262b"}
          onMouseLeave={(e) => e.currentTarget.style.background = "#0e0e10"}>
            Confirm · {fmt(total)}
          </button>
        </div>
        <style>{`
          @keyframes fadeIn { from { opacity:0 } to { opacity:1 } }
          @keyframes popIn { from { opacity:0; transform: translateY(12px) scale(.98) } to { opacity:1; transform: translateY(0) scale(1) } }
        `}</style>
      </div>
    </div>);

}

function SummaryLine({ label, value, accent }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
      <span style={{ fontSize: 13.5, fontWeight: 700, color: accent ? "#e1251b" : "#0e0e10" }}>{label}</span>
      <span style={{ fontSize: 13.5, fontWeight: 700, color: accent ? "#e1251b" : "#0e0e10", fontVariantNumeric: "tabular-nums" }}>{value}</span>
    </div>);

}

// ─────────── Order detail drawer ───────────
function OrderDetailDrawer({ order, store, onClose }) {
  const [view, setView] = React.useState(order?.__initialView || "item"); // 'order' or 'item'
  const [activeItem, setActiveItem] = React.useState(order);
  // Sync when a different order is opened (new object each time the drawer opens).
  React.useEffect(() => {
    setView(order?.__initialView || "item");
    setActiveItem(order);
  }, [order]);
  if (!order) return null;
  const items = order.__siblings && order.__siblings.length ? order.__siblings : [activeItem];
  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 90,
      background: "rgba(20,20,30,.4)",
      display: "flex", justifyContent: "flex-end",
      animation: "drawerFade .2s ease"
    }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        width: "min(944px, calc(100vw - 80px))", height: "100%",
        background: "#fff", overflowY: "auto",
        boxShadow: "-12px 0 32px rgba(20,20,30,.18)",
        animation: "drawerSlide .25s cubic-bezier(.2,.9,.3,1)"
      }}>
        <DrawerHeader order={order} onClose={onClose} />
        <DrawerCrumbs view={view} onView={setView} />
        {view === "order" ?
        <DrawerOrderView order={order} items={items} store={store} onOpenItem={(it) => {setActiveItem(it);setView("item");}} /> :
        <DrawerBody order={activeItem || order} store={store} />}
        <DrawerActions order={order} />
      </div>
      <style>{`
        @keyframes drawerFade { from { opacity: 0 } to { opacity: 1 } }
        @keyframes drawerSlide { from { transform: translateX(40px); opacity: .4 } to { transform: translateX(0); opacity: 1 } }
      `}</style>
    </div>);

}

function DrawerHeader({ order, onClose }) {
  return (
    <div style={{ padding: "28px 36px 16px", position: "relative" }}>
      <button onClick={onClose} style={{
        position: "absolute", top: 24, right: 28,
        background: "transparent", border: 0, cursor: "pointer", color: "#0e0e10", padding: 8
      }} title="Close (Esc)">
        <IconX size={22} />
      </button>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        <div style={{ fontSize: 22, fontWeight: 700 }}>
          Web Order #:{" "}
          <a href="#" onClick={(e) => e.preventDefault()} style={{ color: "#2563eb", textDecoration: "none" }}>{order.webOrderNum}</a>
        </div>
        <div style={{ fontSize: 16, fontWeight: 600 }}>
          Factory Order #:{" "}
          <a href="#" onClick={(e) => e.preventDefault()} style={{ color: "#2563eb", textDecoration: "none" }}>{order.factoryOrderNum}</a>
        </div>
        <div style={{ marginTop: 12, fontSize: 18, fontWeight: 700, color: "#0e0e10" }}>{order.organization}</div>
        <div style={{ fontSize: 13, color: "#6b6b72" }}>
          <span style={{ fontWeight: 600, color: "#0e0e10" }}>Cart Name:</span> {order.cartName}
        </div>
      </div>
    </div>);

}

function DrawerCrumbs({ view, onView }) {
  return (
    <div style={{ padding: "0 36px 16px", display: "flex", alignItems: "center", gap: 8, fontSize: 13 }}>
      {view === "item" ?
      <React.Fragment>
        <a href="#" onClick={(e) => {e.preventDefault();onView("order");}} style={{
          color: "#6b6b72", textDecoration: "none", fontWeight: 500
        }}>Order View</a>
        <IconChevronRight size={14} style={{ color: "#9a9aa1" }} />
        <span style={{ color: "#0e0e10", fontWeight: 700 }}>Item View</span>
      </React.Fragment> :
      <span style={{ color: "#0e0e10", fontWeight: 700 }}>Order View</span>}
    </div>);

}

// ─────────── Order View (whole web order: summary + grouped line items) ───────────
function OrderSummaryCell({ label, value, info }) {
  return (
    <div>
      <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10", display: "inline-flex", alignItems: "center", gap: 8 }}>
        {label}{info && <IconInfo size={14} style={{ color: "#0e0e10" }} />}
      </div>
      <div style={{ fontSize: 14, color: "#0e0e10", marginTop: 4 }}>{value || "—"}</div>
    </div>);

}

function DrawerOrderView({ order, items, store, onOpenItem }) {
  // Group the web order's line items by shipping group, in first-seen order.
  const groups = [];
  const byKey = {};
  (items || []).forEach((it) => {
    const k = it.shippingGroup || "—";
    if (!byKey[k]) {byKey[k] = { group: k, rows: [] };groups.push(byKey[k]);}
    byKey[k].rows.push(it);
  });
  const subtotal = order.pricing?.subtotal;
  return (
    <div style={{ padding: "0 36px 24px" }}>
      {/* Summary card */}
      <div style={{
        background: "#fafafb", border: "1px solid #ececf0", borderRadius: 10,
        padding: "28px 28px", display: "grid",
        gridTemplateColumns: "1.1fr 1fr 1.2fr 1.4fr", gap: 0
      }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 24, paddingRight: 24 }}>
          <OrderSummaryCell label="Order Submitted" value={order.submitDate} />
          <OrderSummaryCell label="Order Subtotal" value={subtotal != null ? `$${subtotal.toFixed(2)}` : "—"} info />
          <OrderSummaryCell label="PO #" value={order.poNumber} />
        </div>
        <div style={{ paddingRight: 24 }}>
          <OrderSummaryCell label="Payment Terms" value={order.paymentTerms || "Net 30"} />
        </div>
        <div style={{ paddingLeft: 28, paddingRight: 24, borderLeft: "1px solid #e4e4e7" }}>
          <RepBlock rep={order.repInfo} />
        </div>
        <div style={{ paddingLeft: 28, borderLeft: "1px solid #e4e4e7" }}>
          <DeliveryBlock delivery={order.delivery} />
        </div>
      </div>

      {/* Line items grouped by shipping group */}
      <div style={{ marginTop: 28, display: "flex", flexDirection: "column", gap: 28 }}>
        {groups.map((g) =>
        <div key={g.group}>
          <div style={{ fontSize: 15, fontWeight: 700, color: "#0e0e10", marginBottom: 8 }}>Shipping Group: {g.group}</div>
          {g.rows.map((it, i) =>
          <React.Fragment key={it.id || i}>
            {i > 0 && <div style={{ height: 1, background: "#ececf0", margin: "4px 0" }} />}
            <OrderViewItemRow item={it} store={store} onOpen={() => onOpenItem(it)} />
          </React.Fragment>
          )}
        </div>
        )}
      </div>
    </div>);

}

// Right-hand status/date column varies by the item's lifecycle stage.
function OrderViewItemStatus({ item }) {
  const s = item.status;
  const tracking = item.tracking &&
  <a href="#" onClick={(e) => {e.preventDefault();e.stopPropagation();}} style={{ color: "#2563eb", textDecoration: "none", display: "inline-flex", alignItems: "center", gap: 4, fontVariantNumeric: "tabular-nums" }}>
      {item.tracking}<IconExternal size={13} />
    </a>;

  const row = (label, value, color) =>
  <div style={{ fontSize: 14 }}>
      <span style={{ fontWeight: 700, color: "#0e0e10" }}>{label}</span>{" "}
      <span style={{ color: color || "#0e0e10" }}>{value}</span>
    </div>;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12, alignItems: "flex-start" }}>
      <StatusBadge status={s} />
      {s === "shipped" || s === "delivered" ?
      <React.Fragment>
        {row(s === "delivered" ? "Delivered" : "Shipped", item.shipDate || item.dueDate, "#1f7a3d")}
        {tracking}
      </React.Fragment> :
      s === "artwork-production" ?
      <React.Fragment>
        {row("Ship Date", item.shipDate || item.tempShipDate || item.dueDate)}
        {row("Now Estimated", item.dueDate, "#b91c1c")}
        {tracking}
      </React.Fragment> :
      s === "on-hold" ?
      row("Ship Date", item.shipDate || item.tempShipDate || item.dueDate) :
      <React.Fragment>
        {row("Ship Date", item.shipDate || item.tempShipDate || item.dueDate)}
        {tracking}
      </React.Fragment>}
    </div>);

}

function OrderViewItemRow({ item, store, onOpen }) {
  const isIssue = item.status === "on-hold";
  const pill = (label) =>
  <span key={label} style={{
    display: "inline-flex", padding: "4px 12px", borderRadius: 999,
    background: "#f1f1f3", color: "#6b6b72", fontSize: 11, fontWeight: 600
  }}>{label}</span>;

  return (
    <div onClick={onOpen} style={{
      display: "grid", gridTemplateColumns: "220px 1.1fr .9fr .9fr", gap: 20,
      padding: "16px 0", alignItems: "start", cursor: "pointer"
    }}>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {item.isReorder &&
        <div style={{ display: "flex", gap: 8 }}>{pill("Reorder")}{pill("Legacy")}</div>}
        <div style={{
          width: 128, height: 152, background: "#f1f2f4", borderRadius: 8,
          display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden", padding: 12
        }}>
          <img src={__asset(orderPhotoFor(item.product))} alt={item.product?.title || "Uniform"} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
        </div>
        <div style={{ fontSize: 12, color: "#9a9aa1", fontWeight: 500, lineHeight: 1.3, maxWidth: 128 }}>{item.product?.title}</div>
        {isIssue &&
        <button onClick={(e) => e.stopPropagation()} style={{
          background: "#b91c1c", color: "#fff", border: 0, borderRadius: 6,
          padding: "12px 16px", fontSize: 13, fontWeight: 700, cursor: "pointer", width: 128
        }}>Fix Issue</button>}
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 16, fontSize: 14 }}>
        <div><span style={{ fontWeight: 700 }}>Order Part ID #</span> <span>{item.partId}</span></div>
        <div><span style={{ fontWeight: 700 }}>Description</span> <span>{item.product?.colorway || "—"}</span></div>
        <div><span style={{ fontWeight: 700 }}>Sport</span> <span>{item.sport}</span></div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 16, fontSize: 14 }}>
        <div><span style={{ fontWeight: 700 }}>Quantity</span> <span>{item.quantity}</span></div>
        <div><span style={{ fontWeight: 700 }}>Item Price</span> <span>{item.pricing?.subtotal != null ? `$${item.pricing.subtotal.toFixed(2)}` : "—"}</span></div>
        {item.originalOrderId && <div><span style={{ fontWeight: 700 }}>Original Order ID</span> <span>{item.originalOrderId}</span></div>}
        {item.originalPartId && <div><span style={{ fontWeight: 700 }}>Original Order Part ID</span> <span>{item.originalPartId}</span></div>}
      </div>

      <OrderViewItemStatus item={item} />
    </div>);

}

function DrawerBody({ order, store }) {
  return (
    <div style={{ padding: "0 36px 24px" }}>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 40, alignItems: "flex-start" }}>
        {/* left: art + stepper */}
        <div>
          <div style={{
            background: "#fafafb", border: "1px solid #ececf0", borderRadius: 8,
            padding: "20px 24px", display: "flex", justifyContent: "center", gap: 20
          }}>
            <OrderThumb product={order.product || {}} size="big" />
          </div>
          <button style={{
            width: "100%", marginTop: 16, background: "#fff", border: "1px solid #d4d4d8",
            borderRadius: 999, padding: "12px", fontSize: 13, fontWeight: 600,
            cursor: "pointer", letterSpacing: ".02em"
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = "#fafafb"}
          onMouseLeave={(e) => e.currentTarget.style.background = "#fff"}>
            View PDF
          </button>
        </div>

        {/* right: title + meta */}
        <div>
          <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 8 }}>{order.product?.title}</div>
          <div style={{ fontSize: 13, color: "#6b6b72", marginBottom: 12 }}>{order.product?.colorway || "Navy Jerseys"}</div>
          <div style={{ fontSize: 13, color: "#9a9aa1", marginBottom: 16 }}>
            <span style={{ fontWeight: 600 }}>Order Part ID#:</span>{" "}
            <span style={{ color: "#6b6b72" }}>{order.partId}</span>
          </div>
          <StatusBadge status={order.status} refund={order.refund} />

          <div style={{ marginTop: 20, display: "flex", flexDirection: "column", gap: 12 }}>
            <MetaRow label="Quantity" value={order.quantity} />
            <MetaRow label="Sport" value={order.sport} />
            <MetaRow label="PO Number" value={order.poNumber} />
            <MetaRow label="Tracking Number(s)" value={order.tracking ? <BlueLink>{order.tracking}</BlueLink> : "—"} />
            <MetaRow label="Temporary Ship Date" value={order.tempShipDate} />
          </div>
        </div>
      </div>

      {/* stepper full width */}
      <div style={{ marginTop: 32 }}>
        <ProgressStepper order={order} />
      </div>

      {/* delivery / rep / pricing */}
      <div style={{ marginTop: 32, display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 32 }}>
        <DeliveryBlock delivery={order.delivery} />
        <RepBlock rep={order.repInfo} />
        <PricingBlock pricing={order.pricing} />
      </div>
    </div>);

}

function BigJersey({ colors, label, variant }) {
  const c1 = colors?.[0] || "#1d3a8a";
  const c2 = colors?.[1] || "#0e0e10";
  const c3 = colors?.[2] || "#f5b400";
  return (
    <svg width="220" height="240" viewBox="0 0 220 240">
      <path d="M40 30 L72 14 L148 14 L180 30 L210 60 L188 84 L180 60 L180 220 L40 220 L40 60 L32 84 L10 60 Z"
      fill={c1.toLowerCase() === "#ffffff" ? "#f1f1f3" : c1}
      stroke={c2} strokeWidth="2" strokeLinejoin="round" />
      {/* neckline */}
      <path d="M72 14 Q110 36 148 14 L148 26 Q110 46 72 26 Z" fill={c2} />
      {/* shoulder stripes */}
      <rect x="50" y="36" width="50" height="6" fill={c3} opacity=".95" transform="rotate(-12 75 39)" />
      <rect x="50" y="46" width="50" height="6" fill="#fff" opacity=".85" transform="rotate(-12 75 49)" />
      <rect x="50" y="56" width="50" height="6" fill={c3} opacity=".95" transform="rotate(-12 75 59)" />
      <rect x="120" y="36" width="50" height="6" fill={c3} opacity=".95" transform="rotate(12 145 39)" />
      <rect x="120" y="46" width="50" height="6" fill="#fff" opacity=".85" transform="rotate(12 145 49)" />
      <rect x="120" y="56" width="50" height="6" fill={c3} opacity=".95" transform="rotate(12 145 59)" />
      {/* label */}
      <text x="110" y="140" textAnchor="middle" fontFamily="JetBrains Mono, monospace" fontWeight="800"
      fontSize={label && label.length <= 2 ? 70 : label && label.length < 6 ? 40 : 28}
      fill={c3}
      style={{ filter: "drop-shadow(2px 2px 0 rgba(0,0,0,.4))" }}>{label || ""}</text>
    </svg>);

}

function MetaRow({ label, value }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 16, fontSize: 14 }}>
      <span style={{ color: "#0e0e10", fontWeight: 600 }}>{label}</span>
      <span style={{ color: "#0e0e10", fontVariantNumeric: "tabular-nums" }}>{value || "—"}</span>
    </div>);

}

function ProgressStepper({ order }) {
  const steps = [
  { id: "submit", label: "Submit Date", sub: order.submitDate },
  { id: "confirm", label: "Order Confirmed", sub: order.confirmedDate },
  { id: "artwork", label: "Artwork Production", sub: order.artworkDate },
  { id: "factory", label: "Factory Production", sub: order.factoryDate },
  { id: "ship", label: "Ship Date", sub: order.shipDate || `Temporary: ${order.tempShipDate || ""}` },
  { id: "delivery", label: "Delivery", sub: order.deliveryDate }];

  const stageIndex = {
    "submitted": 0,
    "order-confirmed": 1,
    "artwork-production": 2,
    "factory-production": 3,
    "shipped": 4,
    "delivered": 5,
    "on-hold": 2
  }[order.status] ?? 0;

  return (
    <div style={{ position: "relative", display: "grid", gridTemplateColumns: `repeat(${steps.length}, 1fr)`, gap: 0 }}>
      {/* connecting line */}
      <div style={{
        position: "absolute", left: `${100 / steps.length / 2}%`, right: `${100 / steps.length / 2}%`,
        top: 16, height: 2, background: "#ececf0"
      }} />
      <div style={{
        position: "absolute", left: `${100 / steps.length / 2}%`,
        width: `calc((100% - ${100 / steps.length}%) * ${stageIndex / (steps.length - 1)})`,
        top: 16, height: 2, background: "#0e0e10", transition: "width .3s"
      }} />
      {steps.map((s, i) => {
        const active = i === stageIndex;
        const past = i < stageIndex;
        return (
          <div key={s.id} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, position: "relative" }}>
            <div style={{
              width: 32, height: 32, borderRadius: "50%",
              background: active ? "#0e0e10" : past ? "#0e0e10" : "#ececf0",
              color: active || past ? "#fff" : "#6b6b72",
              display: "inline-flex", alignItems: "center", justifyContent: "center",
              fontSize: 13, fontWeight: 700
            }}>{past ? <IconCheck size={14} style={{ strokeWidth: 3 }} /> : i + 1}</div>
            <div style={{ fontSize: 12, fontWeight: active ? 700 : 500, color: active ? "#0e0e10" : "#6b6b72", textAlign: "center" }}>{s.label}</div>
            {s.sub && <div style={{ fontSize: 11, color: "#9a9aa1", textAlign: "center" }}>{s.sub}</div>}
          </div>);

      })}
    </div>);

}

