// My Carts — the "Add From Cart" picker.
// Reached from the Add Product modal → "Add From Cart".

const SAMPLE_CARTS = [
{
  id: "c1", date: "March 2, 2026", time: "10:05 MST",
  name: "SKU Item Test", qty: 3, total: 156.00,
  statuses: ["rework", "active"], favorite: false
},
{
  id: "c2", date: "May 21, 2026", time: "14:52 MST",
  name: "Test", qty: 0, total: 0,
  statuses: [], favorite: false
},
{
  id: "c3", date: "May 21, 2026", time: "14:20 MST",
  name: "Test Team Store", qty: 2, total: 178.90,
  statuses: ["active"], favorite: false
},
{
  id: "c4", date: "April 14, 2026", time: "09:31 MST",
  name: "Carlsbad Hoyas — Jersey + Hat Bundle", qty: 12, total: 624.00,
  statuses: ["active"], favorite: true
},
{
  id: "c5", date: "April 02, 2026", time: "16:12 MST",
  name: "Spring Practice Tees", qty: 8, total: 312.50,
  statuses: [], favorite: false
}];


function MyCarts({ onClose, onLoadCart, onAddToStore, stores = [], activeStoreId }) {
  const [tab, setTab] = React.useState("saved");
  const [carts, setCarts] = React.useState(SAMPLE_CARTS);
  const [sort, setSort] = React.useState("None");
  const [search, setSearch] = React.useState("");
  const [toast, setToast] = React.useState(null);
  const [sortOpen, setSortOpen] = React.useState(false);
  const [addModalCart, setAddModalCart] = React.useState(null);
  const sortRef = React.useRef();
  React.useEffect(() => {
    const h = (e) => {if (sortRef.current && !sortRef.current.contains(e.target)) setSortOpen(false);};
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  const visible = React.useMemo(() => {
    let arr = carts.filter((c) => c.name.toLowerCase().includes(search.toLowerCase()));
    if (sort === "Newest") arr = [...arr].sort((a, b) => new Date(b.date) - new Date(a.date));
    if (sort === "Oldest") arr = [...arr].sort((a, b) => new Date(a.date) - new Date(b.date));
    if (sort === "Total (High → Low)") arr = [...arr].sort((a, b) => b.total - a.total);
    if (sort === "Total (Low → High)") arr = [...arr].sort((a, b) => a.total - b.total);
    return arr;
  }, [carts, search, sort]);

  const setFavorite = (id, v) => setCarts((cs) => cs.map((c) => c.id === id ? { ...c, favorite: v } : c));
  const remove = (id) => setCarts((cs) => cs.filter((c) => c.id !== id));

  return (
    <div style={{ flex: 1, padding: "28px 36px 80px", background: "#fff" }}>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 24 }}>
        <div>
          <button onClick={onClose} style={{
            background: "transparent", border: 0, cursor: "pointer", padding: "4px 0",
            color: "#6b6b72", display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 8
          }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M15 18l-6-6 6-6" /></svg>
            Back to store
          </button>
          <h1 style={{ fontSize: 22, fontWeight: 800, letterSpacing: ".02em", margin: 0 }}>MY CARTS</h1>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
          <div ref={sortRef} style={{ position: "relative" }}>
            <button onClick={() => setSortOpen((v) => !v)} style={{
              background: "transparent", border: 0, cursor: "pointer", padding: "8px 0",
              display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13, color: "#0e0e10"
            }}>
              <span style={{ color: "#6b6b72" }}>Sort by</span>
              <span style={{ fontWeight: 600 }}>{sort}</span>
              <IconChevron size={14} />
            </button>
            {sortOpen &&
            <div style={{ position: "absolute", top: "100%", right: 0, background: "#fff", border: "1px solid #ececf0", borderRadius: 6, boxShadow: "0 8px 24px rgba(20,20,30,.10)", minWidth: 180, padding: 4, zIndex: 30, marginTop: 4 }}>
                {["None", "Newest", "Oldest", "Total (High → Low)", "Total (Low → High)"].map((o) =>
              <div key={o} onClick={() => {setSort(o);setSortOpen(false);}} style={{
                padding: "8px 12px", fontSize: 13, cursor: "pointer", borderRadius: 4,
                background: sort === o ? "#fafafb" : "transparent"
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = "#fafafb"}
              onMouseLeave={(e) => e.currentTarget.style.background = sort === o ? "#fafafb" : "transparent"}>{o}</div>
              )}
              </div>
            }
          </div>
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Keyword search"
            style={{
              border: "1px solid #d4d4d8", borderRadius: 4, background: "#fff",
              padding: "12px 12px", fontSize: 13, width: 240, outline: 0
            }} />
          
        </div>
      </div>

      {
      <div>
          {/* Column headers */}
          <div style={{
          display: "grid",
          gridTemplateColumns: "1fr 2fr .6fr .8fr 1.4fr",
          gap: 16, padding: "16px 20px", fontSize: 11, fontWeight: 700, letterSpacing: ".10em", color: "#6b6b72",
          borderBottom: "1px solid #ececf0"
        }}>
            <div>DATE/TIME</div>
            <div style={{ textAlign: "center" }}>CART NAME</div>
            <div style={{ textAlign: "center" }}>QUANTITY</div>
            <div style={{ textAlign: "center" }}>TOTAL</div>
            <div style={{ textAlign: "center" }}>ACTIONS</div>
          </div>
          {visible.length === 0 ?
        <div style={{ padding: "80px 20px", textAlign: "center", color: "#6b6b72" }}>
              No carts match your search.
            </div> :

        visible.map((c) =>
        <CartRow key={c.id} cart={c}
        onFavorite={(v) => setFavorite(c.id, v)}
        onLoad={() => {onLoadCart(c);setToast(`Loaded "${c.name}"`);}}
        onAddToStore={() => setAddModalCart(c)}
        onDelete={() => remove(c.id)} />
        )
        }
        </div>
      }

      <AddCartToStoreModal
        open={!!addModalCart}
        cart={addModalCart}
        carts={carts}
        stores={stores}
        defaultStoreId={activeStoreId}
        onClose={() => setAddModalCart(null)}
        onConfirm={(payload) => {
          setAddModalCart(null);
          onAddToStore && onAddToStore(payload);
        }} />
      

      <Toast message={toast} onDone={() => setToast(null)} />
    </div>);

}

function AddCartToStoreModal({ open, cart, carts, stores, defaultStoreId, onClose, onConfirm }) {
  const [selectedCartId, setSelectedCartId] = React.useState(null);
  const [selectedStoreId, setSelectedStoreId] = React.useState(null);
  React.useEffect(() => {
    if (open) {
      setSelectedCartId(cart?.id || carts[0]?.id);
      setSelectedStoreId(defaultStoreId || stores[0]?.id);
    }
  }, [open, cart, defaultStoreId]);

  const cartOptions = carts.map((c) => ({ value: c.id, label: c.name }));
  const storeOptions = stores.map((s) => ({
    value: s.id,
    label: s.teamName || s.storeTitle || "Team Store",
    color: s.teamColors?.[0] || "#e1251b",
    logo: s.teamLogo?.url
  }));

  const selectedCart = carts.find((c) => c.id === selectedCartId);
  const selectedStore = stores.find((s) => s.id === selectedStoreId);

  return (
    <Modal open={open} onClose={onClose} width={560}>
      <div style={{ padding: "28px 28px 28px" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 28 }}>
          <h3 style={{ fontSize: 18, fontWeight: 700, margin: 0 }}>Add Saved Cart to Team Store</h3>
          <button onClick={onClose} style={{ background: "transparent", border: 0, cursor: "pointer", padding: 4, color: "#6b6b72" }}>
            <IconX size={20} />
          </button>
        </div>

        <div style={{ marginBottom: 16 }}>
          <SelectField
            label="Saved Cart"
            value={selectedCartId}
            options={cartOptions}
            onChange={setSelectedCartId} />
          
        </div>

        <div style={{ marginBottom: 28 }}>
          <TeamStoreSelect
            value={selectedStoreId}
            options={storeOptions}
            onChange={setSelectedStoreId} />
          
        </div>

        <div style={{ display: "flex", justifyContent: "center" }}>
          <Button
            variant="primary"
            disabled={!selectedCartId || !selectedStoreId}
            onClick={() => onConfirm({ cart: selectedCart, store: selectedStore })}
            style={{ padding: "16px 28px", textTransform: "none", letterSpacing: 0, fontSize: 14, borderRadius: 6 }}>
            Add to Selected Store
          </Button>
        </div>
      </div>
    </Modal>);

}

function TeamStoreSelect({ value, options, onChange }) {
  const [open, setOpen] = React.useState(false);
  const [focus, setFocus] = React.useState(false);
  const ref = React.useRef();
  React.useEffect(() => {
    const h = (e) => {if (ref.current && !ref.current.contains(e.target)) setOpen(false);};
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  const filled = !!value;
  const float = focus || filled || open;
  const selected = options.find((o) => o.value === value);
  return (
    <div ref={ref} style={{ position: "relative" }}>
      <div
        tabIndex={0}
        onFocus={() => setFocus(true)}
        onBlur={() => setFocus(false)}
        onClick={() => setOpen((v) => !v)}
        style={{
          position: "relative",
          border: `1px solid ${open || focus ? "#0e0e10" : "#d4d4d8"}`,
          borderRadius: 4, background: "#fff",
          padding: "16px 40px 16px 16px",
          cursor: "pointer", userSelect: "none", minHeight: 56,
          display: "flex", alignItems: "center", gap: 12
        }}>
        <label style={{
          position: "absolute", left: 12, top: float ? -7 : 18,
          fontSize: float ? 11 : 13,
          color: open || focus ? "#0e0e10" : "#6b6b72",
          background: "#fff", padding: float ? "0 4px" : 0,
          pointerEvents: "none", transition: "all .12s ease",
          fontWeight: float ? 500 : 400
        }}>Select Team Store</label>
        {selected && <TeamBadge option={selected} />}
        <div style={{ fontSize: 14, color: "#0e0e10" }}>{selected?.label || ""}</div>
        <IconChevron size={18} style={{ position: "absolute", right: 12, top: "50%", transform: `translateY(-50%) rotate(${open ? 180 : 0}deg)`, transition: "transform .15s", color: "#6b6b72" }} />
      </div>
      {open &&
      <div style={{
        position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0,
        background: "#fff", border: "1px solid #e5e5e9", borderRadius: 6,
        boxShadow: "0 8px 24px rgba(20,20,30,.10)", zIndex: 30,
        maxHeight: 280, overflowY: "auto"
      }}>
          {options.length === 0 ?
        <div style={{ padding: 16, color: "#9a9aa1", fontSize: 13 }}>No team stores yet.</div> :
        options.map((o) =>
        <div key={o.value}
        onMouseDown={(e) => {e.preventDefault();onChange(o.value);setOpen(false);}}
        style={{
          padding: "12px 16px", cursor: "pointer", fontSize: 14,
          background: o.value === value ? "#f7f7f8" : "transparent",
          display: "flex", alignItems: "center", gap: 12
        }}
        onMouseEnter={(e) => {if (o.value !== value) e.currentTarget.style.background = "#fafafb";}}
        onMouseLeave={(e) => {if (o.value !== value) e.currentTarget.style.background = "transparent";}}>
              <TeamBadge option={o} />
              <span>{o.label}</span>
              {o.value === value && <IconCheck size={16} style={{ marginLeft: "auto" }} />}
            </div>
        )}
        </div>
      }
    </div>);

}

function TeamBadge({ option }) {
  if (option.logo) {
    return <img src={__asset(option.logo)} alt="" style={{ width: 28, height: 28, borderRadius: "50%", objectFit: "cover", border: "1px solid #ececf0", flexShrink: 0 }} />;
  }
  return (
    <span style={{
      width: 28, height: 28, borderRadius: "50%", background: option.color || "#e1251b",
      display: "inline-flex", alignItems: "center", justifyContent: "center",
      color: "#fff", fontWeight: 800, fontSize: 11, flexShrink: 0,
      border: (option.color || "").toLowerCase() === "#ffffff" ? "1px solid #d4d4d8" : "none"
    }}>{option.label?.[0]?.toUpperCase() || "T"}</span>);

}

function CartRow({ cart, onFavorite, onLoad, onAddToStore, onDelete }) {
  const statusStyle = {
    rework: { background: "#e1251b", color: "#fff" },
    active: { background: "#cfe8fb", color: "#1c5d99" }
  };
  return (
    <div style={{
      display: "grid",
      gridTemplateColumns: "1fr 2fr .6fr .8fr 1.4fr",
      gap: 16, padding: "24px 20px", alignItems: "center",
      borderBottom: "1px solid #f1f1f3",
      transition: "background .12s"
    }}
    onMouseEnter={(e) => e.currentTarget.style.background = "#fafafb"}
    onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
      <div>
        <div style={{ fontSize: 14, fontWeight: 600, color: "#0e0e10" }}>{cart.date}</div>
        <div style={{ fontSize: 12, color: "#6b6b72", marginTop: 2 }}>{cart.time}</div>
      </div>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 14, color: "#0e0e10", marginBottom: 8 }}>{cart.name}</div>
        <button style={{ background: "transparent", border: 0, cursor: "pointer", color: "#6b6b72", fontSize: 12, display: "inline-flex", alignItems: "center", gap: 4 }}>
          <IconEdit size={12} /> EDIT
        </button>
      </div>
      <div style={{ textAlign: "center", fontSize: 14, color: "#0e0e10" }}>
        {cart.qty || "—"}
      </div>
      <div style={{ textAlign: "center", fontSize: 14, color: "#0e0e10", fontWeight: 500 }}>
        ${cart.total.toFixed(2)}
      </div>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "stretch", gap: 8, minWidth: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, justifyContent: "flex-end" }}>
          <button onClick={() => onFavorite(!cart.favorite)} title="Favorite" style={{
            background: "transparent", border: 0, cursor: "pointer", padding: 4,
            display: "inline-flex", flexDirection: "column", alignItems: "center", color: cart.favorite ? "#f5b400" : "#9a9aa1"
          }}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill={cart.favorite ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
              <polygon points="12 2 15.1 8.3 22 9.3 17 14.1 18.2 21 12 17.8 5.8 21 7 14.1 2 9.3 8.9 8.3 12 2" />
            </svg>
            <span style={{ fontSize: 10, color: "#9a9aa1", marginTop: 2 }}>Favorite</span>
          </button>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "flex-end" }}>
            {cart.statuses.map((s) =>
            <span key={s} style={{
              ...statusStyle[s],
              padding: "4px 12px", borderRadius: 4, fontSize: 11, fontWeight: 700,
              textTransform: "capitalize"
            }}>{s}</span>
            )}
          </div>
        </div>
        <button onClick={onLoad} style={{
          background: "#fafafb", border: "1px solid #ececf0", borderRadius: 4,
          padding: "8px 16px", fontSize: 12, color: "#0e0e10", cursor: "pointer",
          display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, fontWeight: 600,
          transition: "background .12s"
        }}
        onMouseEnter={(e) => e.currentTarget.style.background = "#f1f1f3"}
        onMouseLeave={(e) => e.currentTarget.style.background = "#fafafb"}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M7 17L17 7" /><path d="M9 7h8v8" /></svg>
          LOAD CART
        </button>
        <button onClick={onAddToStore} style={{
          background: "#fafafb", border: "1px solid #ececf0", borderRadius: 4,
          padding: "8px 16px", fontSize: 12, color: "#0e0e10", cursor: "pointer",
          display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, fontWeight: 600,
          transition: "background .12s"
        }}
        onMouseEnter={(e) => {e.currentTarget.style.background = "#0e0e10";e.currentTarget.style.color = "#fff";e.currentTarget.style.borderColor = "#0e0e10";}}
        onMouseLeave={(e) => {e.currentTarget.style.background = "#fafafb";e.currentTarget.style.color = "#0e0e10";e.currentTarget.style.borderColor = "#ececf0";}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M7 17L17 7" /><path d="M9 7h8v8" /></svg>
          ADD TO TEAM STORE
        </button>
        <button onClick={onDelete} style={{
          background: "#fafafb", border: "1px solid #ececf0", borderRadius: 4,
          padding: "8px 16px", fontSize: 12, color: "#0e0e10", cursor: "pointer",
          display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, fontWeight: 600,
          transition: "background .12s"
        }}
        onMouseEnter={(e) => {e.currentTarget.style.background = "#fff3f2";e.currentTarget.style.color = "#b81d14";e.currentTarget.style.borderColor = "#f5d0cd";}}
        onMouseLeave={(e) => {e.currentTarget.style.background = "#fafafb";e.currentTarget.style.color = "#0e0e10";e.currentTarget.style.borderColor = "#ececf0";}}>
          <IconTrash size={13} />
          DELETE
        </button>
      </div>
    </div>);

}

Object.assign(window, { MyCarts });

