function SavedDesigns({ onClose, onAddToStore, storeTeamName, stores = [], activeStoreId }) {
  const [sort, setSort] = React.useState("None");
  const [filter, setFilter] = React.useState("All");
  const [search, setSearch] = React.useState("");
  const [favs, setFavs] = React.useState({});
  const [toast, setToast] = React.useState(null);
  const [addModalDesign, setAddModalDesign] = React.useState(null);

  const visible = SAVED_DESIGNS.filter((d) => d.title.toLowerCase().includes(search.toLowerCase()));

  return (
    <div style={{ flex: 1, padding: "28px 36px 80px", background: "#fff" }}>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 28 }}>
        <div>
          <button onClick={onClose} style={{
            background: "transparent", border: 0, cursor: "pointer", padding: "4px 0",
            color: "#6b6b72", display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 8,
          }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M15 18l-6-6 6-6"/></svg>
            Back to store
          </button>
          <h1 style={{ fontSize: 22, fontWeight: 800, letterSpacing: ".02em", margin: 0 }}>SAVED DESIGNS</h1>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
          <InlineDropdown label="Sort by" value={sort} options={["None", "Newest", "Oldest", "Title (A→Z)"]} onChange={setSort} />
          <InlineDropdown label="Filter by" value={filter} options={["All", "Basketball", "Baseball", "Football", "Soccer"]} onChange={setFilter} />
          <div style={{
            position: "relative", border: "1px solid #d4d4d8", borderRadius: 4,
            background: "#fff", width: 260, display: "flex", alignItems: "center",
          }}>
            <IconSearch size={14} style={{ position: "absolute", left: 12, color: "#9a9aa1" }} />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Keyword Search" style={{
              width: "100%", border: 0, outline: 0, background: "transparent",
              padding: "12px 12px 12px 36px", fontSize: 13,
            }} />
          </div>
        </div>
      </div>

      <div style={{
        display: "grid", gridTemplateColumns: "1.4fr 1.6fr 1fr",
        gap: 16, padding: "16px 20px", fontSize: 12, fontWeight: 700, letterSpacing: ".10em",
        color: "#6b6b72", borderBottom: "1px solid #ececf0", textAlign: "center",
      }}>
        <div style={{ textAlign: "left" }}>DESIGN INFORMATION</div>
        <div>THUMBNAILS</div>
        <div>ACTIONS</div>
      </div>

      {visible.map((d) => (
        <DesignRow key={d.id} design={d}
          fav={!!favs[d.id]}
          onFav={(v) => setFavs((f) => ({ ...f, [d.id]: v }))}
          onAddToStore={() => setAddModalDesign(d)} />
      ))}

      <AddDesignToStoreModal
        open={!!addModalDesign}
        design={addModalDesign}
        stores={stores}
        defaultStoreId={activeStoreId}
        onClose={() => setAddModalDesign(null)}
        onConfirm={(payload) => {
          setAddModalDesign(null);
          onAddToStore && onAddToStore(payload);
        }}
      />

      <Toast message={toast} onDone={() => setToast(null)} />
    </div>
  );
}

function AddDesignToStoreModal({ open, design, stores, defaultStoreId, onClose, onConfirm }) {
  const [selectedStoreId, setSelectedStoreId] = React.useState(null);
  React.useEffect(() => {
    if (open) setSelectedStoreId(defaultStoreId || stores[0]?.id);
  }, [open, defaultStoreId]);

  const storeOptions = stores.map((s) => ({
    value: s.id,
    label: s.teamName || s.storeTitle || "Team Store",
    color: s.teamColors?.[0] || "#e1251b",
    logo: s.teamLogo?.url,
  }));
  const selectedStore = stores.find((s) => s.id === selectedStoreId);

  return (
    <Modal open={open} onClose={onClose} width={520}>
      <div style={{ padding: "28px 28px 28px" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 28 }}>
          <h3 style={{ fontSize: 18, fontWeight: 700, margin: 0 }}>Add Product to Team Store</h3>
          <button onClick={onClose} style={{ background: "transparent", border: 0, cursor: "pointer", padding: 4, color: "#6b6b72" }}>
            <IconX size={20} />
          </button>
        </div>
        <div style={{ marginBottom: 28 }}>
          <TeamStoreSelect
            value={selectedStoreId}
            options={storeOptions}
            onChange={setSelectedStoreId}
          />
        </div>
        <div style={{ display: "flex", justifyContent: "center" }}>
          <Button
            variant="primary"
            disabled={!selectedStoreId}
            onClick={() => onConfirm({ design, store: selectedStore })}
            style={{ padding: "16px 28px", textTransform: "none", letterSpacing: 0, fontSize: 14, borderRadius: 6 }}>
            Add to Selected Store
          </Button>
        </div>
      </div>
    </Modal>
  );
}

function InlineDropdown({ label, value, options, onChange }) {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef();
  React.useEffect(() => {
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button onClick={() => setOpen((v) => !v)} style={{
        background: "transparent", border: 0, cursor: "pointer",
        display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13,
        padding: "8px 0",
      }}>
        <span style={{ color: "#6b6b72" }}>{label}</span>
        <span style={{ color: "#0e0e10", fontWeight: 600 }}>{value}</span>
        <IconChevron size={14} style={{ color: "#6b6b72" }} />
      </button>
      {open && (
        <div style={{
          position: "absolute", top: "100%", left: 0, marginTop: 8,
          background: "#fff", border: "1px solid #ececf0", borderRadius: 6,
          boxShadow: "0 8px 24px rgba(20,20,30,.10)", minWidth: 160, padding: 4, zIndex: 30,
        }}>
          {options.map((o) => (
            <div key={o} onClick={() => { onChange(o); setOpen(false); }} style={{
              padding: "8px 12px", fontSize: 13, cursor: "pointer", borderRadius: 4,
              background: value === o ? "#fafafb" : "transparent",
            }}
              onMouseEnter={(e) => e.currentTarget.style.background = "#fafafb"}
              onMouseLeave={(e) => e.currentTarget.style.background = value === o ? "#fafafb" : "transparent"}>{o}</div>
          ))}
        </div>
      )}
    </div>
  );
}

