// Overview mode — renders every major screen side-by-side as scaled iframes.
//
// Each cell loads index.html#frame=<id> in an iframe; app.jsx reads that hash
// on boot and jumps the state machine straight to that screen with seed data.

const OVERVIEW_FRAMES = [
  { id: "portal",                      label: "00 · Team Stores portal" },
  { id: "empty",                       label: "01 · Empty state" },
  { id: "form",                        label: "02 · Create form" },
  { id: "form-tax",                    label: "03 · Sales tax confirm" },
  { id: "loading",                     label: "04 · Creating store…" },
  { id: "list",                        label: "05 · Store list" },
  { id: "dashboard-general",           label: "06 · Dashboard / General" },
  { id: "dashboard-products-empty",    label: "07 · Products (empty)" },
  { id: "customizer",                  label: "08 · Customizer picker" },
  { id: "my-carts",                    label: "09 · My Carts" },
  { id: "saved-designs",               label: "10 · Saved Designs" },
  { id: "dashboard-products-configure",label: "11 · Configure pending" },
  { id: "dashboard-products-drafts",   label: "12 · Drafts / Published" },
];

// Native iframe viewport — the App is min-width: 1280
const FRAME_W = 1280;
const FRAME_H = 820;

function OverviewGrid({ onExit }) {
  // Responsive: pick a thumb width based on viewport (3 per row at >= 1500, 2 below)
  const [cols, setCols] = React.useState(() => (window.innerWidth >= 1500 ? 3 : 2));
  React.useEffect(() => {
    const onResize = () => setCols(window.innerWidth >= 1500 ? 3 : 2);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  // Compute thumb width to fit cols across the available width
  const [containerW, setContainerW] = React.useState(window.innerWidth);
  React.useEffect(() => {
    const onResize = () => setContainerW(window.innerWidth);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  const GAP = 22;
  const PAD = 36;
  const usable = containerW - PAD * 2 - GAP * (cols - 1);
  const thumbW = Math.max(380, Math.floor(usable / cols));
  const scale = thumbW / FRAME_W;
  const thumbH = Math.round(FRAME_H * scale);

  return (
    <div style={{
      position: "fixed", inset: 0, background: "#f7f7f8",
      overflow: "auto", zIndex: 5,
    }}>
      {/* Top bar */}
      <div style={{
        position: "sticky", top: 0, zIndex: 2,
        background: "rgba(255,255,255,.92)",
        backdropFilter: "saturate(140%) blur(8px)",
        borderBottom: "1px solid #ececf0",
        padding: "16px 36px",
        display: "flex", alignItems: "center", justifyContent: "space-between",
      }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 16 }}>
          <strong style={{ fontSize: 14, letterSpacing: ".08em" }}>FRAME OVERVIEW</strong>
          <span style={{ color: "#6b6b72", fontSize: 12 }}>
            {OVERVIEW_FRAMES.length} screens · click any frame to open it
          </span>
        </div>
        <button onClick={onExit} style={{
          background: "#0e0e10", color: "#fff", border: 0, borderRadius: 6,
          padding: "8px 16px", fontSize: 13, fontWeight: 600, cursor: "pointer",
        }}>Exit overview</button>
      </div>

      {/* Grid */}
      <div style={{
        padding: `${PAD}px`,
        display: "grid",
        gridTemplateColumns: `repeat(${cols}, ${thumbW}px)`,
        gap: GAP,
        justifyContent: "center",
      }}>
        {OVERVIEW_FRAMES.map((f) => (
          <FrameCard key={f.id} frame={f} width={thumbW} height={thumbH} scale={scale} />
        ))}
      </div>
    </div>
  );
}

function FrameCard({ frame, width, height, scale }) {
  const src = `${location.pathname}#frame=${frame.id}`;
  const openFull = () => window.open(src, "_blank");
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between" }}>
        <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".06em", color: "#0e0e10" }}>
          {frame.label.toUpperCase()}
        </span>
        <button onClick={openFull} style={{
          background: "transparent", border: 0, color: "#6b6b72",
          fontSize: 11, cursor: "pointer", padding: 0,
        }}>Open ↗</button>
      </div>

      <div
        onClick={openFull}
        title="Click to open in a new tab"
        style={{
          width, height,
          background: "#fff",
          border: "1px solid #e5e5e9",
          borderRadius: 10,
          overflow: "hidden",
          boxShadow: "0 1px 2px rgba(20,20,30,.04), 0 12px 32px rgba(20,20,30,.06)",
          cursor: "pointer",
          position: "relative",
        }}
      >
        <iframe
          src={__asset(src)}
          title={frame.label}
          style={{
            width: FRAME_W,
            height: FRAME_H,
            border: 0,
            transform: `scale(${scale})`,
            transformOrigin: "top left",
            pointerEvents: "none",
            background: "#fff",
          }}
        />
        {/* Hover overlay */}
        <div className="frame-card-hover" style={{
          position: "absolute", inset: 0,
          background: "rgba(14,14,16,0)",
          transition: "background .15s",
          pointerEvents: "none",
        }} />
      </div>
    </div>
  );
}

Object.assign(window, { OverviewGrid, OVERVIEW_FRAMES });


