const USER_TPL_KEY = "prolook_user_templates";
function loadUserTemplates() {
  try { const raw = localStorage.getItem(USER_TPL_KEY); return raw ? JSON.parse(raw) : []; } catch (e) { return []; }
}
function saveUserTemplates(list) {
  try { localStorage.setItem(USER_TPL_KEY, JSON.stringify(list)); } catch (e) {}
}

