// Enriched demo stores — a couple are live with products so Overview / workspace
// states (revenue, active stores, launched controls) all have something to show.
// Client rule (non-negotiable): every Stock Vault item is added to every store
// catalog by default. Items carry fromVault so the catalog can badge them.
function vaultDefaultProducts(storeId, curatedTitles) {
  const all = (window.__prostockItems || []).concat(window.__marucciVaultItems || []);
  return all.map((it) => {
    const cw = (it.colorways || [])[0] || {};
    const curated = curatedTitles.indexOf(it.title) >= 0;
    const pricing = { adult: { retail: String(it.priceAdult != null ? it.priceAdult : it.retail || 0) } };
    if (it.priceYouth != null) pricing.youth = { retail: String(it.priceYouth) };
    return { id: storeId + "-vault-" + it.id, title: it.title, subtitle: it.sku + " · " + (it.source || "Stock Vault"), sku: it.sku, status: "published",
      teamSetting: curated ? "team-supplied" : "fan-gear", brand: it.brand || "Prolook", source: it.source || "Stock Vault", category: it.vaultCategory, storeCategory: it.vaultCategory,
      stock: "in", deco: "none", decoratable: it.stockType === "pro" || it.stockType === "sideline", photo: cw.front || null, pricing, fromVault: true, rosters: [] };
  });
}
function makeSeededStores() {
  const seeded = makeSeedStores();
  const curatedA = ["RCKLESS OG USA -8", "Code USA Baseball -10", "Blacksmith Wrap Adult Batting Gloves", "Blacksmith Wrap Youth Batting Gloves", "Lizard Skins Cypress 43A2LS 11.50\" I-Web", "CFT Mid Molded", "Belt"];
  const curatedB = ["F5 USA Baseball -10", "Fractal USA Baseball -12", "PWR Fade Batting Gloves", "PWR Fade Youth Batting Gloves", "Lizard Skins Cypress 98R3LS 12.75\" H-Web", "CFT Turf", "Belt", "Marucci Flow Rope Hat"];
  const active = seeded.map((s, i) => ({ ...s, seeded: true, live: true, status: "active", products: vaultDefaultProducts(s.id, i === 0 ? curatedA : curatedB) }));
  return [...active, ...makeArchivedStores()];
}

