/* ===== Products Tab Evolution — Confluence spec 4231856129 ===== */
// One canonical product record across four sources (source is an attribute,
// never a type). Table-at-scale list, decoration lifecycle + art approval,
// batch decoration, Stock Vault, three new intake channels, policy touches.
// Zinc-ramp literals match the PROLOOK DS tokens the prototype uses.
const PTE_C = { ink: "#09090b", z800: "#27272a", z700: "#3f3f46", z600: "#52525b", z500: "#71717a", z400: "#a1a1aa", z300: "#d4d4d8", z200: "#e4e4e7", z100: "#f4f4f5", z50: "#fafafa", red: "#e1251b", redInk: "#b81d14", ok: "#1f8a55", okBg: "#e7f5ed", warn: "#b5760a", warnBg: "#fff4e0", blue: "#1d5fbf", blueBg: "#e8f1fd", indigo: "#4353b8", indigoBg: "#eef2ff", rejBg: "#fdeaea" };

// Third-party integration is platform-wide on this fork: every store is seller-of-record Marucci.
function isMultiSourceStore(store) { return true; }

function pteCategoryOf(p) {
  if (p.category) return p.category;
  const t = (p.title || "").toLowerCase();
  if (/(pant|short|legging|tight|jogger)/.test(t)) return "Pants";
  if (/(bag|backpack|towel)/.test(t)) return "Bags";
  if (/(bat|glove)/.test(t)) return "Hard goods";
  if (/(hoodie|fleece|pullover|quarter)/.test(t)) return "Fleece";
  if (/polo/.test(t)) return "Polos";
  if (/(tee|shirt(?! jersey))/.test(t)) return "Tees";
  return "Uniforms";
}
// Canonical-record defaults — legacy single-brand products read as Prolook custom.
function pteMeta(p) {
  return {
    brand: p.brand || "Prolook",
    source: p.source || "Prolook custom",
    category: pteCategoryOf(p),
    stock: p.stock || "na",
    deco: p.deco || "na",
    decoratable: !!p.decoratable,
  };
}
const PTE_DECO = {
  none: { label: "Not decorated", bg: PTE_C.z100, ink: PTE_C.z600, dot: PTE_C.z400 },
  render: { label: "Render pending", bg: PTE_C.indigoBg, ink: PTE_C.indigo, dot: PTE_C.indigo },
  draft: { label: "Art: Draft", bg: PTE_C.warnBg, ink: PTE_C.warn, dot: PTE_C.warn },
  submitted: { label: "Art: Submitted", bg: PTE_C.blueBg, ink: PTE_C.blue, dot: PTE_C.blue },
  approved: { label: "Art: Approved", bg: PTE_C.okBg, ink: PTE_C.ok, dot: PTE_C.ok },
  rejected: { label: "Art: Rejected", bg: PTE_C.rejBg, ink: PTE_C.redInk, dot: PTE_C.redInk },
  na: { label: "—", bg: "transparent", ink: PTE_C.z300, dot: "transparent" },
};
// ── Lifecycle removal (July 2026): single live list, source-keyed locks ──
// Source badge — the third-party build adds Vault and the seller catalog.
function pteSourceBadge(p) {
  const s = String(p.srcKind || p.source || "").toLowerCase();
  const sub = String(p.subtitle || "").toLowerCase() + " " + String(p.style || "").toLowerCase();
  if (s === "vault" || s.includes("vault") || sub.includes("vault")) return "Vault";
  if (s.includes("marucci") || s.includes("stock")) return "Marucci Catalog";
  if (s.includes("design")) return "Saved Design";
  if (s.includes("cart")) return "Saved Cart";
  return "Custom";
}
// Vault / seller-catalog items are not made to order — no design or order locks.
function pteRestricted(p) {
  const b = pteSourceBadge(p);
  return b !== "Vault" && b !== "Marucci Catalog";
}
// Lock trigger = any non-cancelled order (data-driven via p.hasOrders); a bundle
// with orders also locks its restricted members.
function pteHasOrders(p, store) {
  if (p.hasOrders) return true;
  return !!(store && (store.products || []).some((b) => b.isBundle && b.hasOrders && (b.bundleItemIds || []).includes(p.id)));
}
function pteLockState(p, store) {
  if (!pteRestricted(p)) return "none";
  return pteHasOrders(p, store) ? "full" : "design";
}
const PTE_LOCK_TIPS = {
  design: "Design is locked once an item is added to the store.",
  full: "This item has orders — changes are locked because it is made to order.",
};
// Send for Approval renders only when the store has an Active team manager.
function pteHasActiveTM(store) {
  try { return seedTmInvites(store).some((i) => i.status === "active"); } catch (e) { return false; }
}

// Publish gates: render-set existence is policy-independent; art approval
// blocks publish only under the strict (default) policy.
function ptePublishBlocked(p, store) {
  const m = pteMeta(p);
  if (m.deco === "render") return "renders";
  if ((store.artPolicy || "block-publish") !== "block-publish") return null;
  return ["draft", "submitted", "rejected"].includes(m.deco) ? "art" : null;
}
function pteChip(bg, ink, extra) { return Object.assign({ fontSize: 10.5, fontWeight: 700, letterSpacing: ".4px", padding: "3px 9px", borderRadius: 999, background: bg, color: ink, whiteSpace: "nowrap", display: "inline-block" }, extra || {}); }
function pteRetail(p, tier) { const v = parseFloat(String((p.pricing && p.pricing[tier] && p.pricing[tier].retail) != null ? p.pricing[tier].retail : "").replace(/[^0-9.]/g, "")); return isNaN(v) ? null : v; }
function ptePriceText(p) {
  if (p.teamSetting === "team-supplied") return "Covered";
  if (p.isBundle && p.bundleType === "choice") {
    const vals = [pteRetail(p, "youth"), pteRetail(p, "adult")].filter((v) => v != null);
    if (!vals.length) return "—";
    return "from $" + Math.min(...vals).toFixed(2);
  }
  const y = pteRetail(p, "youth"), a = pteRetail(p, "adult");
  if (y == null && a == null) return "—";
  const f = (v) => v == null ? "—" : "$" + (v % 1 ? v.toFixed(2) : v.toFixed(0));
  return f(y) + " / " + f(a);
}
function PteThumb({ product, store, size = 34, radius = 6 }) {
  const m = pteMeta(product);
  if (product.photo) return (
    <span style={{ width: size, height: size, borderRadius: radius, flexShrink: 0, background: "#fafafa", border: "1px solid " + PTE_C.z100, display: "inline-flex", alignItems: "center", justifyContent: "center", overflow: "hidden", padding: 2 }}>
      <CatalogPhoto photo={product.photo} alt={product.title} />
    </span>
  );
  if (product.thumbnail) return <span style={{ width: size, height: size, flexShrink: 0, display: "inline-flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>{product.thumbnail}</span>;
  return (
    <span style={{ width: size, height: size, borderRadius: radius, flexShrink: 0, background: PTE_C.z100, display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, color: PTE_C.z400 }}>
      {store && store.__letterThumbs === false ? "" : m.category.slice(0, 1)}
    </span>
  );
}

// ─────────── Delete / removal — keyed to source + order state ───────────
function ProductDeleteModal({ product, store, onClose, onConfirm, onGoToOrders, onGoToBundle }) {
  if (!product) return null;
  const locked = pteLockState(product, store) === "full";
  // Epic C — bundle protection, keyed to membership. Affected bundles are always named.
  const holdingBundles = product.isBundle ? [] : ((store && store.products) || []).filter((b) => b.isBundle && (b.bundleItemIds || []).includes(product.id));
  const twoMember = holdingBundles.filter((b) => (b.bundleItemIds || []).length === 2);
  const escalate = !locked && twoMember.length > 0;
  const names = (list) => list.map((b) => '“' + (b.title || "Bundle") + '”').join(", ");
  const btn = (kind) => ({
    border: kind === "secondary" ? "1px solid " + PTE_C.z300 : 0, borderRadius: 6, padding: "11px 20px", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit",
    background: kind === "danger" ? PTE_C.red : kind === "primary" ? PTE_C.ink : "#fff",
    color: kind === "secondary" ? PTE_C.ink : "#fff",
  });
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(9,9,11,.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 400, padding: 24 }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: 480, maxWidth: "100%", background: "#fff", borderRadius: 12, boxShadow: "0 24px 48px rgba(9,9,11,.2)", padding: 28 }}>
        <div style={{ display: "flex", gap: 14, alignItems: "flex-start", marginBottom: 20 }}>
          <span style={{ width: 40, height: 40, borderRadius: "50%", flexShrink: 0, background: locked ? PTE_C.rejBg : PTE_C.z100, color: locked ? PTE_C.redInk : PTE_C.ink, display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
            {locked ? <IconAlert size={18} /> : <IconTrash size={18} />}
          </span>
          <div>
            <div style={{ fontSize: 16, fontWeight: 800, color: PTE_C.ink, fontFamily: "Archivo, sans-serif", marginBottom: 6 }}>
              {locked ? "This item has orders" : escalate ? "This leaves a bundle with one item" : "Delete this product?"}
            </div>
            <div style={{ fontSize: 13, color: PTE_C.z600, lineHeight: 1.55 }}>
              {locked
                ? `“${product.title}” is made to order and can’t be deleted while it has open orders. Cancel the blocking orders from the Orders tab first — once every order is cancelled, delete is permitted.`
                : escalate
                ? `“${product.title}” is one of two items in ${names(twoMember)}. Removing it leaves that bundle with a single member — it becomes Incomplete and drops off the storefront until a second item is added. The bundle itself is not deleted.`
                : holdingBundles.length > 0
                ? `“${product.title}” will be removed from this store’s catalog and will also leave ${names(holdingBundles)}. ${holdingBundles.length === 1 ? "That bundle stays" : "Those bundles stay"} complete. This can’t be undone.`
                : `“${product.title}” will be removed from this store’s catalog. This can’t be undone.`}
            </div>
          </div>
        </div>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 10 }}>
          {locked ? (
            <React.Fragment>
              <button onClick={onClose} style={btn("secondary")}>Keep in Store</button>
              <button onClick={onGoToOrders} style={btn("primary")}>Go to Orders</button>
            </React.Fragment>
          ) : (
            <React.Fragment>
              <button onClick={onClose} style={btn("secondary")}>Cancel</button>
              {escalate && onGoToBundle && <button onClick={() => onGoToBundle(twoMember[0].id)} style={btn("primary")}>Go to bundle</button>}
              <button onClick={onConfirm} style={btn("danger")}>{escalate ? "Remove anyway" : "Delete"}</button>
            </React.Fragment>
          )}
        </div>
      </div>
    </div>
  );
}

// ─────────── 4 — Store-level category curation ───────────
// Lives on the Products tab (a Settings card links here): the rep orders the
// categories, orders products inside them, pins required uniforms to the top and
// features one item. The order IS the storefront's tab order and browse order,
// so the panel carries a live preview of the result.
function storeCatCfg(store) {
  window.__storeCatCfg = window.__storeCatCfg || {};
  const id = (store && store.id) || "store";
  if (!window.__storeCatCfg[id]) window.__storeCatCfg[id] = { order: null, subs: {}, pins: {}, feat: {}, prodOrder: {}, added: [], subOf: {} };
  return window.__storeCatCfg[id];
}
const CAT_SYS = "Team Gear";
const CAT_NONE = "Uncategorized";
// Same category the catalog table shows: the explicit store category, else the
// product record's own category. Team Gear is a store category like any other —
// what makes it special is that it is system-managed and carries the team
// settings, so team-required / team-supplied items always belong to it.
function productCat(p) {
  const explicit = p.storeCategory || (typeof pteMeta === "function" ? pteMeta(p).category : "");
  const t = p.teamSetting || "fan-gear";
  if (!explicit) return (t === "team-required" || t === "team-supplied") ? CAT_SYS : CAT_NONE;
  return explicit;
}
function isTeamGearItem(p) {
  const t = p.teamSetting || "fan-gear";
  return t === "team-required" || t === "team-supplied" || productCat(p) === CAT_SYS;
}
function storeCatList(store, products) {
  const cfg = storeCatCfg(store);
  const fromWorkspace = (window.__prodCats || []).map((c) => c.name).filter((n) => n !== CAT_SYS);
  const used = Array.from(new Set((products || []).map(productCat)));
  const all = Array.from(new Set([CAT_SYS, ...fromWorkspace, ...cfg.added, ...used.filter((n) => n !== CAT_NONE)]));
  const order = cfg.order || all;
  const sorted = order.filter((n) => all.includes(n)).concat(all.filter((n) => !order.includes(n)));
  if (used.includes(CAT_NONE)) sorted.push(CAT_NONE);
  return sorted;
}
function storeCatProducts(store, products, cat) {
  const cfg = storeCatCfg(store);
  // Team Gear collects every team-required / team-supplied item wherever it is
  // categorized — that section keeps its special behavior.
  const list = (products || []).filter((p) => cat === CAT_SYS ? isTeamGearItem(p) : productCat(p) === cat);
  const ord = cfg.prodOrder[cat] || [];
  const byOrder = (a, b) => {
    const pa = cfg.pins[a.id] ? 0 : 1, pb = cfg.pins[b.id] ? 0 : 1;
    if (pa !== pb) return pa - pb;
    const ia = ord.indexOf(a.id), ib = ord.indexOf(b.id);
    return (ia < 0 ? 999 : ia) - (ib < 0 ? 999 : ib);
  };
  return list.slice().sort(byOrder);
}
function StoreCategoryManager({ store, products, onBack, onToast, onUpdateProduct }) {
  const cfg = storeCatCfg(store);
  const [tick, setTick] = React.useState(0);
  const bump = () => setTick((n) => n + 1);
  const cats = storeCatList(store, products);
  const [sel, setSel] = React.useState(cats[0] || CAT_SYS);
  const [newCat, setNewCat] = React.useState("");
  const [newSub, setNewSub] = React.useState("");
  const [drag, setDrag] = React.useState(null);
  const active = cats.includes(sel) ? sel : cats[0];
  const items = storeCatProducts(store, products, active);
  const countOf = (c) => storeCatProducts(store, products, c).length;
  const publishedIn = (c) => storeCatProducts(store, products, c).filter((p) => p.status !== "draft" && !p.hidden).length;
  const tabs = cats.filter((c) => countOf(c) > 0 && publishedIn(c) > 0);
  const overflow = tabs.slice(4);
  const shown = tabs.slice(0, 4);

  const reorderCats = (from, to) => {
    const list = cats.filter((c) => c !== CAT_NONE);
    if (from < 0 || to < 0 || from >= list.length || to >= list.length) return;
    const next = list.slice();
    next.splice(to, 0, next.splice(from, 1)[0]);
    cfg.order = next;
    bump();
  };
  const reorderProds = (from, to) => {
    const ids = items.map((p) => p.id);
    if (from < 0 || to < 0 || from >= ids.length || to >= ids.length) return;
    const next = ids.slice();
    next.splice(to, 0, next.splice(from, 1)[0]);
    cfg.prodOrder[active] = next;
    bump();
  };
  const addCat = () => {
    const n = newCat.trim();
    if (!n || cats.some((c) => c.toLowerCase() === n.toLowerCase())) return;
    cfg.added = [...cfg.added, n];
    cfg.order = (cfg.order || cats.filter((c) => c !== CAT_NONE)).concat([n]);
    setNewCat(""); setSel(n); bump();
    onToast && onToast("Category \u201c" + n + "\u201d added to this store");
  };
  const addSub = () => {
    const n = newSub.trim();
    if (!n) return;
    cfg.subs[active] = [...(cfg.subs[active] || []), n];
    setNewSub(""); bump();
    onToast && onToast("Subcategory \u201c" + n + "\u201d added under " + active);
  };
  const removeCat = (c) => {
    if (c === CAT_SYS || c === CAT_NONE) return;
    cfg.added = cfg.added.filter((x) => x !== c);
    cfg.order = (cfg.order || cats).filter((x) => x !== c);
    delete cfg.subs[c];
    bump();
    onToast && onToast(countOf(c) > 0
      ? "\u201c" + c + "\u201d removed \u2014 its " + countOf(c) + " products moved to Uncategorized"
      : "\u201c" + c + "\u201d removed");
  };
  const togglePin = (p) => { cfg.pins[p.id] = !cfg.pins[p.id]; bump(); onToast && onToast(cfg.pins[p.id] ? "\u201c" + p.title + "\u201d pinned to the top of " + active : "Unpinned \u201c" + p.title + "\u201d"); };
  const toggleFeat = (p) => { cfg.feat[p.id] = !cfg.feat[p.id]; bump(); onToast && onToast(cfg.feat[p.id] ? "\u201c" + p.title + "\u201d featured in " + active : "Removed the feature treatment"); };

  const handle = (
    <svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor" style={{ flexShrink: 0, opacity: .5 }}>
      <circle cx="4" cy="2.5" r="1.1" /><circle cx="8" cy="2.5" r="1.1" /><circle cx="4" cy="6" r="1.1" /><circle cx="8" cy="6" r="1.1" /><circle cx="4" cy="9.5" r="1.1" /><circle cx="8" cy="9.5" r="1.1" />
    </svg>
  );
  const col = { background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, padding: 16, minWidth: 0 };
  const hdr = (t, s) => (
    <div style={{ marginBottom: 12 }}>
      <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".06em", color: PTE_C.ink }}>{t}</div>
      <div style={{ fontSize: 11.5, color: PTE_C.z500, marginTop: 3, lineHeight: 1.45 }}>{s}</div>
    </div>
  );
  return (
    <div style={{ paddingBottom: 100 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 6 }}>
        {onBack &&
          <button onClick={onBack} style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#fff", border: "1px solid " + PTE_C.z300, borderRadius: 6, padding: "7px 12px", fontSize: 12.5, fontWeight: 700, color: PTE_C.ink, cursor: "pointer", fontFamily: "inherit" }}>
            <IconChevronLeft size={13} /> Catalog
          </button>}
        <h2 style={{ margin: 0, fontSize: 20, fontWeight: 800, fontFamily: "Archivo, sans-serif", color: PTE_C.ink }}>Categories &amp; Sorting</h2>
        <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".05em", color: PTE_C.z600, background: PTE_C.z100, borderRadius: 999, padding: "3px 9px" }}>THIS STORE ONLY</span>
      </div>
      <p style={{ margin: "0 0 18px", fontSize: 13, color: PTE_C.z500, maxWidth: 780, lineHeight: 1.55 }}>
        This order is what buyers see: categories become the storefront header tabs, and the product order inside a category is its browse order. Workspace categories are the starting set — anything you add here belongs to this store.
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "minmax(240px,270px) minmax(420px,1.6fr) minmax(300px,1fr)", gap: 16, alignItems: "start" }}>
        {/* Categories */}
        <div style={col}>
          {hdr("CATEGORY ORDER", "Drag to reorder. Team Gear is system-managed \u2014 it can move, but not be renamed or removed.")}
          {cats.map((c, i) => {
            const on = c === active;
            const sys = c === CAT_SYS, none = c === CAT_NONE;
            const n = countOf(c), pub = publishedIn(c);
            return (
              <div key={c}
                draggable={!none}
                onDragStart={() => setDrag({ kind: "cat", i })}
                onDragOver={(e) => { e.preventDefault(); if (drag && drag.kind === "cat" && drag.i !== i && !none) { reorderCats(drag.i, i); setDrag({ kind: "cat", i }); } }}
                onDragEnd={() => setDrag(null)}
                onClick={() => setSel(c)}
                style={{ display: "flex", alignItems: "center", gap: 9, padding: "9px 10px", marginBottom: 5, borderRadius: 7, cursor: "pointer", background: on ? PTE_C.z50 : "#fff", border: "1px solid " + (on ? PTE_C.ink : PTE_C.z200) }}>
                {!none && handle}
                <span style={{ minWidth: 0, flex: 1 }}>
                  <span style={{ display: "block", fontSize: 12.5, fontWeight: 700, color: none ? PTE_C.z500 : PTE_C.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c}</span>
                  <span style={{ display: "block", fontSize: 10.5, color: PTE_C.z400, marginTop: 1 }}>
                    {n === 0 ? "Empty \u2014 no storefront tab" : pub === 0 ? n + " item" + (n === 1 ? "" : "s") + " \u00b7 none published" : n + " item" + (n === 1 ? "" : "s")}
                  </span>
                </span>
                {sys && <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: ".05em", color: PTE_C.z600, background: PTE_C.z100, borderRadius: 999, padding: "2px 7px", flexShrink: 0 }}>SYSTEM</span>}
                {!sys && !none &&
                  <button onClick={(e) => { e.stopPropagation(); removeCat(c); }} title={"Remove " + c} style={{ background: "none", border: 0, padding: 2, cursor: "pointer", color: PTE_C.z400, display: "inline-flex", flexShrink: 0 }}><IconTrash size={12} /></button>}
              </div>
            );
          })}
          <div style={{ display: "flex", gap: 6, marginTop: 10 }}>
            <input value={newCat} onChange={(e) => setNewCat(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addCat(); }} placeholder="New category"
              style={{ flex: 1, minWidth: 0, height: 32, boxSizing: "border-box", border: "1px solid " + PTE_C.z300, borderRadius: 6, padding: "0 10px", fontSize: 12.5, fontFamily: "inherit", outline: "none" }} />
            <button onClick={addCat} disabled={!newCat.trim()} style={{ background: newCat.trim() ? PTE_C.ink : PTE_C.z100, color: newCat.trim() ? "#fff" : PTE_C.z400, border: 0, borderRadius: 6, padding: "0 12px", height: 32, fontSize: 12, fontWeight: 700, cursor: newCat.trim() ? "pointer" : "default", fontFamily: "inherit" }}>Add</button>
          </div>
        </div>

        {/* Products in the selected category */}
        <div style={col}>
          {hdr(String(active || "").toUpperCase() + " \u00b7 PRODUCT ORDER", "Drag to reorder. Pin moves an item to the top and keeps it there; Feature only changes emphasis.")}
          {/* Subcategories — one level, never deeper */}
          <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap", marginBottom: 12, paddingBottom: 12, borderBottom: "1px solid " + PTE_C.z100 }}>
            <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".05em", color: PTE_C.z500 }}>SUBCATEGORIES</span>
            {(cfg.subs[active] || []).map((s) => (
              <span key={s} style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 11.5, fontWeight: 600, color: PTE_C.z700, background: PTE_C.z50, border: "1px solid " + PTE_C.z200, borderRadius: 999, padding: "3px 9px" }}>
                {s}
                <button onClick={() => { cfg.subs[active] = (cfg.subs[active] || []).filter((x) => x !== s); bump(); }} style={{ background: "none", border: 0, padding: 0, cursor: "pointer", color: PTE_C.z400, display: "inline-flex" }}><IconX size={10} /></button>
              </span>
            ))}
            {(cfg.subs[active] || []).length === 0 && <span style={{ fontSize: 11.5, color: PTE_C.z400 }}>None</span>}
            <span style={{ display: "inline-flex", gap: 5, marginLeft: "auto" }}>
              <input value={newSub} onChange={(e) => setNewSub(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addSub(); }} placeholder="Add subcategory"
                style={{ width: 132, height: 28, boxSizing: "border-box", border: "1px solid " + PTE_C.z300, borderRadius: 6, padding: "0 9px", fontSize: 11.5, fontFamily: "inherit", outline: "none" }} />
            </span>
          </div>
          {items.length === 0 &&
            <div style={{ padding: "34px 12px", textAlign: "center", fontSize: 12.5, color: PTE_C.z400, lineHeight: 1.5 }}>
              Nothing in {active} yet. {active === CAT_NONE ? "Assign a category on each product to get it out of this bucket." : "Set this category on a product in the catalog and it appears here."}
            </div>}
          {items.length > 0 && publishedIn(active) === 0 &&
            <div style={{ display: "flex", gap: 8, alignItems: "flex-start", background: "#fdf6e7", border: "1px solid #efdcae", borderRadius: 7, padding: "9px 11px", marginBottom: 10, fontSize: 11.5, color: "#6b5314", lineHeight: 1.45 }}>
              <IconAlert size={12} style={{ flexShrink: 0, marginTop: 1, color: "#8a5f10" }} /> Every item here is a draft or hidden, so this category won’t render a storefront tab yet.
            </div>}
          {items.map((p, i) => {
            const pinned = !!cfg.pins[p.id];
            const feat = !!cfg.feat[p.id];
            const draft = p.status === "draft";
            return (
              <div key={p.id}
                draggable
                onDragStart={() => setDrag({ kind: "prod", i })}
                onDragOver={(e) => { e.preventDefault(); if (drag && drag.kind === "prod" && drag.i !== i) { reorderProds(drag.i, i); setDrag({ kind: "prod", i }); } }}
                onDragEnd={() => setDrag(null)}
                style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "10px 11px", marginBottom: 6, borderRadius: 7, background: "#fff", border: "1px solid " + (feat ? PTE_C.red : PTE_C.z200) }}>
                {handle}
                <span style={{ width: 20, fontSize: 11, fontWeight: 800, color: PTE_C.z400, fontVariantNumeric: "tabular-nums", flexShrink: 0 }}>{i + 1}</span>
                <PteThumb product={p} store={store} />
                <span style={{ minWidth: 0, flex: 1 }}>
                  <span title={p.title} style={{ display: "block", fontSize: 12.5, fontWeight: 700, color: PTE_C.ink, lineHeight: 1.3, textWrap: "pretty" }}>{p.title}</span>
                  <span style={{ display: "flex", gap: 6, marginTop: 3, alignItems: "center", flexWrap: "wrap" }}>
                    {pinned && <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: ".05em", color: PTE_C.ink, background: PTE_C.z100, borderRadius: 3, padding: "1px 5px" }}>PINNED</span>}
                    {feat && <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: ".05em", color: "#fff", background: PTE_C.red, borderRadius: 3, padding: "1px 5px" }}>FEATURED</span>}
                    {draft && <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: ".05em", color: PTE_C.z500, background: PTE_C.z100, borderRadius: 3, padding: "1px 5px" }}>DRAFT</span>}
                    {p.hidden && <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: ".05em", color: PTE_C.z500, background: PTE_C.z100, borderRadius: 3, padding: "1px 5px" }}>HIDDEN</span>}
                    {!pinned && !feat && !draft && !p.hidden && <span style={{ fontSize: 10.5, color: PTE_C.z400 }}>{p.subtitle || "Published"}</span>}
                  </span>
                  <span style={{ display: "flex", gap: 6, marginTop: 7 }}>
                    <button onClick={() => togglePin(p)} title="Pin to the top of this category" style={{ background: pinned ? PTE_C.ink : "#fff", color: pinned ? "#fff" : PTE_C.z600, border: "1px solid " + (pinned ? PTE_C.ink : PTE_C.z300), borderRadius: 6, padding: "5px 10px", fontSize: 11, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>{pinned ? "Pinned" : "Pin"}</button>
                    <button onClick={() => toggleFeat(p)} title="Feature this product — emphasis only, position unchanged" style={{ background: feat ? PTE_C.red : "#fff", color: feat ? "#fff" : PTE_C.z600, border: "1px solid " + (feat ? PTE_C.red : PTE_C.z300), borderRadius: 6, padding: "5px 10px", fontSize: 11, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>{feat ? "Featured" : "Feature"}</button>
                  </span>
                </span>
              </div>
            );
          })}
        </div>

        {/* Storefront preview */}
        <div style={{ ...col, position: "sticky", top: 12 }}>
          {hdr("STOREFRONT PREVIEW", "Tabs render every category that has a published item; the rest fold into More.")}
          <div style={{ border: "1px solid " + PTE_C.z200, borderRadius: 8, overflow: "hidden" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "10px 12px", borderBottom: "1px solid " + PTE_C.z200, background: PTE_C.z50, flexWrap: "wrap" }}>
              {shown.map((c) => (
                <span key={c} onClick={() => setSel(c)} style={{ cursor: "pointer", fontSize: 10.5, fontWeight: 800, letterSpacing: ".05em", textTransform: "uppercase", color: c === active ? PTE_C.red : PTE_C.z600, borderBottom: "2px solid " + (c === active ? PTE_C.red : "transparent"), paddingBottom: 2 }}>{c}</span>
              ))}
              {overflow.length > 0 && <span title={overflow.join(", ")} style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".05em", textTransform: "uppercase", color: PTE_C.z500 }}>More ▾ ({overflow.length})</span>}
              {tabs.length === 0 && <span style={{ fontSize: 11.5, color: PTE_C.z400 }}>No published items yet — no tabs.</span>}
            </div>
            <div style={{ padding: 12 }}>
              {active === CAT_SYS &&
                <div style={{ display: "flex", gap: 7, alignItems: "flex-start", background: "#eef3fb", border: "1px solid #cfe0f5", borderRadius: 7, padding: "8px 10px", marginBottom: 10, fontSize: 11, color: "#1e4e8c", lineHeight: 1.45 }}>
                  <IconInfo size={12} style={{ flexShrink: 0, marginTop: 1 }} /> Team Gear keeps its required-gear nudge — required for rostered players, visible but optional for fans.
                </div>}
              {items.filter((p) => p.status !== "draft" && !p.hidden).length === 0
                ? <div style={{ fontSize: 11.5, color: PTE_C.z400, padding: "18px 0", textAlign: "center" }}>Nothing published in {active}.</div>
                : items.filter((p) => p.status !== "draft" && !p.hidden).map((p, i) => {
                  const feat = !!cfg.feat[p.id];
                  return (
                    <div key={p.id} style={{ display: "flex", alignItems: "center", gap: 9, padding: feat ? "10px 10px" : "7px 10px", marginBottom: 6, borderRadius: 7, background: feat ? "#fff7f6" : PTE_C.z50, border: "1px solid " + (feat ? PTE_C.red : PTE_C.z200) }}>
                      <span style={{ width: 16, fontSize: 10.5, fontWeight: 800, color: PTE_C.z400 }}>{i + 1}</span>
                      <span style={{ flex: 1, minWidth: 0, fontSize: feat ? 12.5 : 11.5, fontWeight: feat ? 800 : 600, color: PTE_C.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.title}</span>
                      {cfg.pins[p.id] && <span style={{ fontSize: 8.5, fontWeight: 800, letterSpacing: ".05em", color: PTE_C.z600 }}>PINNED</span>}
                      {feat && <span style={{ fontSize: 8.5, fontWeight: 800, letterSpacing: ".05em", color: "#fff", background: PTE_C.red, borderRadius: 3, padding: "1px 5px" }}>FEATURED</span>}
                    </div>
                  );
                })}
            </div>
          </div>
          <div style={{ marginTop: 10, fontSize: 11, color: PTE_C.z400, lineHeight: 1.5 }}>
            Featured treatment is a badge and accent border in place — pending stakeholder sign-off on how loud it should be, and how many items may carry it.
          </div>
        </div>
      </div>
    </div>
  );
}

// ─────────── Products list V2 — table at scale (Epic A) ───────────
function ProductsListV2({ onManageCategories, products, store, multiSource, onPublish, onUnpublish, onSendForApproval, onRemove, onAddProducts, onCreateBundle, onUpdateProduct, onBulkPrice, onOpenImages, onOpenEditor, onDecorateBatch, onPatchStore, onToast }) {
  const [q, setQ] = React.useState("");
  const [deleting, setDeleting] = React.useState(null); // product pending delete confirmation
  const [sel, setSel] = React.useState({});
  const [menuId, setMenuId] = React.useState(null);
  const [colOpen, setColOpen] = React.useState(false);
  const [editingId, setEditingId] = React.useState(null);
  const [bulkOpen, setBulkOpen] = React.useState(false);
  const [cols, setCols] = React.useState(() => multiSource
    ? { brand: true, source: true, cat: true, stock: true, deco: true, teams: false }
    : { brand: false, source: false, cat: true, stock: false, deco: false, teams: true });
  const [facets, setFacets] = React.useState({ brand: "All", source: "All", cat: "All", stock: "All", deco: "All", set: "All", vis: "All", fund: "All" });
  const setFacet = (k, v) => setFacets((f) => ({ ...f, [k]: v }));
  // Deep link from Settings — filter to items still collecting fundraising.
  React.useEffect(() => {
    if (window.__pteFilterCollecting) { window.__pteFilterCollecting = false; setFacet("fund", "Collecting"); }
  }, []);

  const reqGroups = store.reqGroups || [];
  const metaOf = pteMeta;
  const match = (p) => {
    const m = metaOf(p);
    if (q && !((p.title || "") + " " + (p.subtitle || "") + " " + (p.sku || "")).toLowerCase().includes(q.toLowerCase())) return false;
    if (facets.brand !== "All" && m.brand !== facets.brand) return false;
    if (facets.source !== "All" && m.source !== facets.source) return false;
    if (facets.cat !== "All" && (p.storeCategory || m.category) !== facets.cat) return false;
    if (facets.stock !== "All" && ({ "In stock": "in", "Out of stock": "out", "N/A (made to order)": "na" })[facets.stock] !== m.stock) return false;
    if (facets.deco !== "All") {
      const dm = { "Not decorated": "none", "Render pending": "render", "Art: Draft": "draft", "Art: Submitted": "submitted", "Art: Approved": "approved", "Art: Rejected": "rejected" };
      if (dm[facets.deco] !== m.deco) return false;
    }
    if (facets.set !== "All" && ({ "Team Required": "team-required", "Team Supplied": "team-supplied", "Fan Gear": "fan-gear" })[facets.set] !== (p.teamSetting || "fan-gear")) return false;
    if (facets.vis !== "All" && (facets.vis === "Hidden") !== !!p.hidden) return false;
    if (facets.fund !== "All" && !(itemFundOn(p, store) && itemFundAmount(p) > 0)) return false;
    return true;
  };
  const filtered = products.filter(match);
  const visible = filtered;
  const anyFilter = !!q || Object.values(facets).some((v) => v !== "All");
  const total = products.length;

  const presentCats = Array.from(new Set(products.map((p) => p.storeCategory || metaOf(p).category)));
  const facetDefs = [
    multiSource && { k: "brand", label: "Brand", opts: ["All", "Marucci", "Victus", "Prolook"] },
    multiSource && { k: "source", label: "Source", opts: ["All", "Prolook custom", "Marucci stock", "Decorated stock", "External customizer"] },
    { k: "cat", label: "Category", opts: ["All"].concat(presentCats) },
    multiSource && { k: "stock", label: "Stock", opts: ["All", "In stock", "Out of stock", "N/A (made to order)"] },
    multiSource && { k: "deco", label: "Decoration", opts: ["All", "Not decorated", "Render pending", "Art: Draft", "Art: Submitted", "Art: Approved", "Art: Rejected"] },
    { k: "set", label: "Setting", opts: ["All", "Team Required", "Team Supplied", "Fan Gear"] },
    { k: "vis", label: "Visibility", opts: ["All", "Visible", "Hidden"] },
    { k: "fund", label: "Fundraising", opts: ["All", "Collecting"] },
  ].filter(Boolean);
  const colDefs = [
    multiSource && ["brand", "Brand"], multiSource && ["source", "Source"], ["cat", "Category"],
    multiSource && ["stock", "Stock"], multiSource && ["deco", "Decoration"], ["teams", "Teams"],
  ].filter(Boolean);

  const gridCols = ["36px", "minmax(230px,1.6fr)", cols.brand && "minmax(86px,.7fr)", cols.source && "minmax(112px,.9fr)", cols.cat && "minmax(90px,.8fr)", cols.stock && "minmax(96px,.8fr)", cols.deco && "minmax(120px,1fr)", "minmax(100px,.9fr)", cols.teams && "minmax(96px,.8fr)", "minmax(96px,.8fr)", "minmax(100px,.9fr)", "76px"].filter(Boolean).join(" ");
  const rowGrid = { display: "grid", gridTemplateColumns: gridCols, gap: 14, alignItems: "center", padding: "7px 20px" };

  const selIds = visible.filter((p) => sel[p.id]).map((p) => p.id);
  const selProds = visible.filter((p) => sel[p.id]);
  const decoSel = selProds.filter((p) => metaOf(p).decoratable);
  const reqSel = selProds.filter((p) => p.teamSetting === "team-required");
  const allChecked = visible.length > 0 && visible.every((p) => sel[p.id]);
  const editingProduct = products.find((p) => p.id === editingId) || null;
  const lockedSel = selProds.filter((p) => pteLockState(p, store) === "full");
  const hasActiveTM = pteHasActiveTM(store);
  const saveToVault = (arr) => {
    window.__vaultItems = window.__vaultItems || [];
    arr.forEach((p) => {
      const m = metaOf(p);
      window.__vaultItems.push({ id: "v-" + p.id + "-" + Date.now(), title: p.title, brand: m.brand, source: m.source, photo: p.photo, category: m.category, deco: (store.teamName || "Team") + " mark · Left chest 3.5in · Embroidery · " + (m.deco === "approved" ? "Approved" : "Art " + m.deco), used: "This store" });
    });
  };
  const groupSelected = () => {
    const name = metaOf(reqSel[0]).category === "Bags" ? "Bag" : "Gear";
    const tag = name + " · 1 of " + reqSel.length;
    const ids = new Set(reqSel.map((p) => p.id));
    onPatchStore({
      products: products.map((p) => ids.has(p.id) ? { ...p, group: tag } : p),
      reqGroups: [...reqGroups, { name, count: reqSel.length }],
    });
    setSel({});
    onToast && onToast("Requirement group created — buyers pick 1 of " + reqSel.length);
  };

  const pillStyle = (on) => ({ background: on ? PTE_C.ink : "#fff", color: on ? "#fff" : PTE_C.ink, border: "1px solid " + (on ? PTE_C.ink : PTE_C.z300), padding: "8px 20px", borderRadius: 999, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", display: "inline-flex", alignItems: "center", gap: 8 });
  const cntStyle = (on) => ({ fontSize: 11, fontWeight: 700, borderRadius: 999, padding: "1px 8px", background: on ? "rgba(255,255,255,.18)" : PTE_C.z100, color: on ? "#fff" : PTE_C.z600 });
  const selArrow = (active) => "url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%2210%22 height=%226%22%3E%3Cpath d=%22M1 1l4 4 4-4%22 stroke=%22" + (active ? "%23fff" : "%23666") + "%22 fill=%22none%22 stroke-width=%221.5%22/%3E%3C/svg%3E')";
  const facetStyle = (active) => ({ appearance: "none", WebkitAppearance: "none", border: "1px solid " + (active ? PTE_C.ink : PTE_C.z300), background: (active ? PTE_C.ink : "#fff") + " " + selArrow(active) + " no-repeat right 10px center", color: active ? "#fff" : PTE_C.z700, borderRadius: 999, padding: "0 30px 0 12px", height: 32, boxSizing: "border-box", fontSize: 12.5, fontWeight: 600, fontFamily: "inherit", cursor: "pointer" });
  const headCell = { fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: PTE_C.z400 };
  const bulkBtn = (kind) => ({ background: kind === "primary" ? "#fff" : "transparent", color: kind === "primary" ? PTE_C.ink : "#fff", border: kind === "primary" ? 0 : "1px solid rgba(255,255,255,.25)", borderRadius: 6, padding: "8px 13px", fontSize: 12, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", whiteSpace: "nowrap" });

  return (
    <div style={{ paddingBottom: 100 }}>
      {(menuId || colOpen) && <div onClick={() => { setMenuId(null); setColOpen(false); }} style={{ position: "fixed", inset: 0, zIndex: 30 }} />}

      {/* Pills + result line + primary actions */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, flexWrap: "wrap", marginBottom: 18 }}>
        <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
          <span style={{ fontSize: 16, fontWeight: 800, color: PTE_C.ink, fontFamily: "Archivo, sans-serif" }}>Catalog</span>
          <span style={{ fontSize: 11.5, fontWeight: 700, borderRadius: 999, padding: "2px 10px", background: PTE_C.z100, color: PTE_C.z600 }}>{total}</span>
          {anyFilter
            ? <span style={{ fontSize: 12, color: PTE_C.z400, marginLeft: 8 }}>{visible.length} of {total} match filters</span>
            : <span style={{ fontSize: 12, color: PTE_C.z400, marginLeft: 8 }}>Items are live on the storefront once the store launches.</span>}
        </div>
        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={onAddProducts} style={{ background: PTE_C.ink, color: "#fff", border: 0, borderRadius: 6, padding: "10px 20px", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>+ Add Products</button>
          <button onClick={onCreateBundle} style={{ background: "#fff", color: PTE_C.ink, border: "1px solid " + PTE_C.z300, borderRadius: 6, padding: "10px 16px", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Create Bundle</button>
        </div>
      </div>

      {/* Search + faceted filters + column control */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search products…" style={{ width: 220, height: 32, boxSizing: "border-box", border: "1px solid " + PTE_C.z300, borderRadius: 6, padding: "0 12px", fontSize: 13, fontFamily: "inherit", outline: "none", background: "#fff" }} />
        {facetDefs.map((f) => (
          <select key={f.k} value={facets[f.k] === "All" ? f.label + ": All" : facets[f.k]} onChange={(e) => setFacet(f.k, e.target.value.startsWith(f.label + ": ") ? e.target.value.split(": ")[1] : e.target.value)} style={facetStyle(facets[f.k] !== "All")}>
            {f.opts.map((o) => <option key={o} value={o === "All" ? f.label + ": All" : o}>{o === "All" ? f.label + ": All" : o}</option>)}
          </select>
        ))}
        {anyFilter && <button onClick={() => { setQ(""); setFacets({ brand: "All", source: "All", cat: "All", stock: "All", deco: "All", set: "All", vis: "All" }); }} style={{ background: "none", border: 0, fontSize: 12, fontWeight: 600, color: PTE_C.z400, cursor: "pointer", fontFamily: "inherit" }}>Clear</button>}
        <div style={{ flex: 1 }} />
        <div style={{ position: "relative" }}>
          <button onClick={() => setColOpen((v) => !v)} style={{ background: "#fff", border: "1px solid " + PTE_C.z300, borderRadius: 6, padding: "0 14px", height: 32, boxSizing: "border-box", fontSize: 12.5, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", color: PTE_C.z700 }}>Columns ▾</button>
          {colOpen && (
            <div style={{ position: "absolute", right: 0, top: "calc(100% + 6px)", zIndex: 40, background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 8, boxShadow: "0 8px 24px rgba(20,20,30,.12)", padding: 8, minWidth: 170 }}>
              {colDefs.map(([k, label]) => (
                <button key={k} onClick={() => setCols((c) => ({ ...c, [k]: !c[k] }))} style={{ display: "flex", gap: 8, alignItems: "center", width: "100%", textAlign: "left", background: "none", border: 0, borderRadius: 6, padding: "7px 10px", fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, color: PTE_C.z800, cursor: "pointer" }}>
                  <span style={{ width: 14, display: "inline-block", color: cols[k] ? PTE_C.ink : "transparent", fontWeight: 700 }}>✓</span>{label}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Requirement-groups strip (Epic E) */}
      {reqGroups.length > 0 && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12, padding: "10px 14px", background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 8, flexWrap: "wrap" }}>
          <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: PTE_C.z500 }}>Requirement groups</span>
          {reqGroups.map((g, i) => <span key={i} style={{ fontSize: 12, fontWeight: 600, background: PTE_C.z100, borderRadius: 999, padding: "4px 12px", color: PTE_C.z800 }}>{g.name} — pick 1 of {g.count}</span>)}
          <span style={{ fontSize: 12, color: PTE_C.z400 }}>Buyers satisfy the requirement with any one member. Select 2+ Required items to create a group.</span>
        </div>
      )}

      {/* Table */}
      <div style={{ background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, overflowX: "auto" }}>
        <div style={{ ...rowGrid, padding: "10px 20px", borderBottom: "1px solid " + PTE_C.z200, background: PTE_C.z50 }}>
          <span><input type="checkbox" checked={allChecked} onChange={() => { const next = { ...sel }; visible.forEach((p) => { next[p.id] = !allChecked; }); setSel(next); }} style={{ width: 15, height: 15, accentColor: PTE_C.ink, cursor: "pointer" }} /></span>
          <span style={headCell}>Product</span>
          {cols.brand && <span style={headCell}>Brand</span>}
          {cols.source && <span style={headCell}>Source</span>}
          {cols.cat && <span style={headCell}>Category</span>}
          {cols.stock && <span style={headCell}>Stock</span>}
          {cols.deco && <span style={headCell}>Decoration</span>}
          <span style={headCell}>Setting</span>
          {cols.teams && <span style={headCell}>Teams</span>}
          <span style={headCell}>Storefront</span>
          <span style={{ ...headCell, textAlign: "right" }}>Youth / Adult</span>
          <span />
        </div>
        {visible.length === 0 && (
          products.length === 0 && !anyFilter ? (
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "88px 20px 96px", textAlign: "center" }}>
              <div style={{ width: 56, height: 56, borderRadius: "50%", background: PTE_C.z100, color: PTE_C.ink, display: "inline-flex", alignItems: "center", justifyContent: "center", marginBottom: 16 }}>
                <IconShirt size={26} />
              </div>
              <div style={{ fontSize: 20, fontWeight: 800, color: PTE_C.ink, marginBottom: 8, fontFamily: "Archivo, sans-serif" }}>No products yet</div>
              <div style={{ color: PTE_C.z600, fontSize: 14, maxWidth: 420, lineHeight: 1.55, marginBottom: 22 }}>
                Pull products from your saved designs and carts, or customize a new one, to start building this store.
              </div>
              <button type="button" onClick={onAddProducts} style={{ background: PTE_C.ink, color: "#fff", border: 0, borderRadius: 6, padding: "12px 28px", fontSize: 14, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>+ Add Products</button>
            </div>
          ) : (
            <div style={{ padding: "72px 20px", textAlign: "center", color: PTE_C.z500, fontSize: 14 }}>
              {anyFilter ? "No products match these filters." : "No products yet — added items appear here."}
            </div>
          )
        )}
        {visible.map((p) => {
          const m = metaOf(p);
          const dm = PTE_DECO[m.deco] || PTE_DECO.na;
          const lock = pteLockState(p, store);
          const setMeta = { "team-required": ["REQUIRED", PTE_C.ink, "#fff"], "team-supplied": ["SUPPLIED", PTE_C.z100, PTE_C.z700], "fan-gear": ["FAN GEAR", "#fff", PTE_C.z500] }[p.teamSetting || "fan-gear"];
          const stockMeta = m.stock === "in" ? ["In stock", PTE_C.okBg, PTE_C.ok] : m.stock === "out" ? [(store.oosTreatment || "hidden") === "hidden" ? "Out · hidden" : "Out of stock", PTE_C.z800, "#fff"] : ["Made to order", PTE_C.z50, PTE_C.z400];
          const teamsText = p.teams || (p.rosters && p.rosters.length ? p.rosters.length + (p.rosters.length === 1 ? " team" : " teams") : "Available league-wide");
          const menuItems = [];
          menuItems.push({ label: "Update Product", act: () => setEditingId(p.id) });
          if (hasActiveTM) menuItems.push({ label: "Send for Approval", note: "Optional — reviewed by this store's team manager", act: () => onSendForApproval && onSendForApproval(p.id) });
          // Customize (Artwork Editor) — Pro Stock / Sideline Stock only; brand-catalog items are made to order.
          if (!pteRestricted(p) || m.decoratable) menuItems.push({ label: "Customize", act: () => onOpenEditor && onOpenEditor(p.id) });
          if (p.teamSetting === "team-required") menuItems.push({ label: "Allow opt-out: " + (p.optOut ? "On" : "Off"), note: "“I already own this” counts as satisfied", act: () => { onUpdateProduct({ ...p, optOut: !p.optOut }); onToast && onToast(p.optOut ? "Opt-out disabled" : "Opt-out enabled — counts as satisfied in required-gear tracking"); } });
          if (multiSource) menuItems.push({ label: "Save to Vault", note: "Carries source, brand, decoration record", act: () => { saveToVault([p]); onToast && onToast("Saved “" + p.title + "” to Stock Vault"); } });
          menuItems.push({ label: "Delete", danger: true, act: () => setDeleting(p) });
          return (
            <div key={p.id} style={{ ...rowGrid, borderBottom: "1px solid " + PTE_C.z100, minHeight: 48, background: sel[p.id] ? PTE_C.z50 : "#fff" }}>
              <span><input type="checkbox" checked={!!sel[p.id]} onChange={() => setSel((s) => ({ ...s, [p.id]: !s[p.id] }))} style={{ width: 15, height: 15, accentColor: PTE_C.ink, cursor: "pointer" }} /></span>
              <span style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0, opacity: p.hidden ? 0.55 : 1 }}>
                <PteThumb product={p} store={store} />
                <span style={{ minWidth: 0 }}>
                  <button onClick={() => (!pteRestricted(p) || m.decoratable) && onOpenEditor ? onOpenEditor(p.id) : setEditingId(p.id)} style={{ background: "none", border: 0, padding: 0, fontFamily: "inherit", fontSize: 13.5, fontWeight: 600, color: PTE_C.ink, cursor: "pointer", textAlign: "left", display: "block", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: 230 }}
                    onMouseEnter={(e) => e.currentTarget.style.color = PTE_C.redInk} onMouseLeave={(e) => e.currentTarget.style.color = PTE_C.ink}>{p.title}</button>
                  <span style={{ fontSize: 11, color: PTE_C.z400, display: "flex", gap: 6, alignItems: "center" }}>
                    {lock !== "none" && <span title={PTE_LOCK_TIPS[lock]} style={{ display: "inline-flex", alignItems: "center", color: lock === "full" ? PTE_C.redInk : PTE_C.z500, cursor: "help", flexShrink: 0 }}><IconLock size={11} style={{ strokeWidth: 2 }} /></span>}
                    <span style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: 190 }}>{p.subtitle || p.sku || m.source}</span>
                    {p.group && <span style={{ fontSize: 10, fontWeight: 700, color: PTE_C.z600, background: PTE_C.z100, borderRadius: 4, padding: "1px 6px", whiteSpace: "nowrap" }}>{p.group}</span>}
                    {p.teamSetting === "team-required" && p.optOut && <span style={{ fontSize: 10, fontWeight: 700, color: PTE_C.blue, background: PTE_C.blueBg, borderRadius: 4, padding: "1px 6px", whiteSpace: "nowrap" }}>OPT-OUT OK</span>}
                  </span>
                </span>
              </span>
              {cols.brand && <span><span style={pteChip(m.brand === "Prolook" ? PTE_C.ink : PTE_C.z100, m.brand === "Prolook" ? "#fff" : PTE_C.z700)}>{m.brand.toUpperCase()}</span></span>}
              {cols.source && <span><span style={pteChip(PTE_C.z100, PTE_C.z700)}>{pteSourceBadge(p).toUpperCase()}</span></span>}
              {cols.cat && <span style={{ fontSize: 12.5, color: PTE_C.z600 }}>{(catOf && catOf[p.id]) || p.storeCategory || m.category}{p.storeSubcategory ? <span style={{ color: PTE_C.z400 }}> · {p.storeSubcategory}</span> : null}</span>}
              {cols.stock && <span><span style={pteChip(stockMeta[1], stockMeta[2])}>{stockMeta[0]}</span></span>}
              {cols.deco && <span>{m.deco === "na" ? <span style={{ fontSize: 12, color: PTE_C.z300 }}>—</span> : <span style={pteChip(dm.bg, dm.ink, { display: "inline-flex", alignItems: "center", gap: 5 })}><span style={{ width: 5, height: 5, borderRadius: 999, background: dm.dot, display: "inline-block" }} />{dm.label}</span>}</span>}
              <span><span style={pteChip(setMeta[1], setMeta[2], p.teamSetting === "fan-gear" || !p.teamSetting ? { border: "1px solid " + PTE_C.z200 } : null)}>{setMeta[0]}</span></span>
              {cols.teams && <span style={{ fontSize: 12.5, color: PTE_C.z600 }}>{teamsText}</span>}
              <span>
                <button onClick={() => { onUpdateProduct({ ...p, hidden: !p.hidden }); onToast && onToast(p.hidden ? `"${p.title}" is visible on the storefront` : `"${p.title}" hidden from the storefront — orders, category and lock state are kept`); }}
                  title={p.hidden ? "Hidden from the storefront — click to show" : "Visible on the storefront — click to hide"}
                  style={{ display: "inline-flex", alignItems: "center", gap: 7, background: "none", border: 0, padding: 0, cursor: "pointer", fontFamily: "inherit" }}>
                  <span style={{ width: 30, height: 17, borderRadius: 999, position: "relative", flexShrink: 0, background: p.hidden ? PTE_C.z300 : PTE_C.ok, transition: "background .14s" }}>
                    <span style={{ position: "absolute", top: 2, left: p.hidden ? 2 : 15, width: 13, height: 13, borderRadius: 999, background: "#fff", transition: "left .14s" }} />
                  </span>
                  <span style={{ fontSize: 11.5, fontWeight: 700, color: p.hidden ? PTE_C.z500 : PTE_C.ok }}>{p.hidden ? "Hidden" : "Visible"}</span>
                </button>
              </span>
              <span style={{ textAlign: "right", fontVariantNumeric: "tabular-nums", fontSize: 13, color: PTE_C.z700 }}>
                {ptePriceText(p)}
                {p.erode != null && <span style={{ display: "block", fontSize: 10, fontWeight: 700, color: PTE_C.warn }}>Margin −${Number(p.erode).toFixed(2)}</span>}
              </span>
              <span style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 4, position: "relative" }}>
                {(!pteRestricted(p) || m.decoratable) && (
                  <button title="Edit decoration in the Artwork Editor" onClick={() => onOpenEditor && onOpenEditor(p.id)} style={{ width: 28, height: 28, border: "1px solid " + PTE_C.z200, borderRadius: 6, display: "inline-flex", alignItems: "center", justifyContent: "center", color: PTE_C.z600, fontSize: 13, background: "#fff", cursor: "pointer", fontFamily: "inherit" }}>✎</button>
                )}
                <button onClick={() => setMenuId(menuId === p.id ? null : p.id)} style={{ width: 28, height: 28, border: "1px solid transparent", borderRadius: 6, background: menuId === p.id ? PTE_C.z100 : "none", cursor: "pointer", color: PTE_C.z500, fontSize: 15, fontFamily: "inherit" }}>⋯</button>
                {menuId === p.id && (
                  <div style={{ position: "absolute", right: 0, top: "calc(100% + 4px)", zIndex: 50, background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 8, boxShadow: "0 8px 24px rgba(20,20,30,.14)", padding: 6, minWidth: 210, textAlign: "left" }}>
                    {menuItems.map((mi, i) => (
                      <button key={i} disabled={mi.disabled} onClick={() => { setMenuId(null); mi.act(); }} style={{ display: "block", width: "100%", textAlign: "left", background: "none", border: 0, borderRadius: 6, padding: "8px 10px", fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, color: mi.disabled ? PTE_C.z300 : mi.danger ? PTE_C.redInk : PTE_C.z800, cursor: mi.disabled ? "default" : "pointer" }}>
                        {mi.label}
                        {mi.note && <span style={{ display: "block", fontSize: 10.5, color: PTE_C.z400, fontWeight: 400, marginTop: 2 }}>{mi.note}</span>}
                      </button>
                    ))}
                  </div>
                )}
              </span>
            </div>
          );
        })}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 20px", borderTop: "1px solid " + PTE_C.z100, fontSize: 12, color: PTE_C.z400 }}>
          <span>Showing 1–{visible.length} of {visible.length}</span>
          <span>List virtualizes past 50 rows — pagination appears at 100+</span>
        </div>
      </div>

      {/* Bulk actions bar */}
      {selIds.length > 0 && (
        <div style={{ position: "fixed", left: "50%", transform: "translateX(-50%)", bottom: 24, zIndex: 60, background: PTE_C.ink, color: "#fff", borderRadius: 12, boxShadow: "0 12px 32px rgba(20,20,30,.3)", padding: "12px 18px", display: "flex", alignItems: "center", gap: 14 }}>
          <span style={{ fontSize: 13, fontWeight: 700 }}>{selIds.length} selected</span>
          <span style={{ width: 1, height: 20, background: "rgba(255,255,255,.2)" }} />
          <button onClick={() => setBulkOpen(true)} title={lockedSel.length ? lockedSel.length + " locked item" + (lockedSel.length === 1 ? "" : "s") + " will be excluded" : "Bulk price selected"} style={bulkBtn("primary")}>Bulk price{lockedSel.length ? ` (${selIds.length - lockedSel.length} of ${selIds.length})` : ""}</button>
          <button onClick={() => { onToast && onToast("Team assignment updated for " + selIds.length + " products"); setSel({}); }} style={bulkBtn()}>Assign to teams</button>
          {multiSource && <button disabled={decoSel.length === 0} onClick={() => { if (!decoSel.length) return; onDecorateBatch(decoSel.map((p) => ({ fromStore: true, id: p.id, title: p.title, photo: p.photo, brand: metaOf(p).brand, category: metaOf(p).category, ok: metaOf(p).category !== "Hard goods" }))); setSel({}); }} title="Batch decoration via the Image Editor zone map" style={{ ...bulkBtn(), ...(decoSel.length === 0 ? { opacity: .4, cursor: "default" } : { borderColor: PTE_C.red, color: "#ffb3ae" }) }}>Decorate selected ({decoSel.length})</button>}
          {reqSel.length >= 2 && <button onClick={groupSelected} style={bulkBtn()}>Group as requirement</button>}
          {multiSource && <button onClick={() => { saveToVault(selProds); onToast && onToast(selIds.length + " saved to Stock Vault"); setSel({}); }} style={bulkBtn()}>Save to Vault</button>}
          <button onClick={() => {
            const ok = selProds.filter((p) => pteLockState(p, store) !== "full");
            ok.forEach((p) => onRemove(p.id));
            setSel({});
            const blockedN = selProds.length - ok.length;
            onToast && onToast(ok.length + " deleted" + (blockedN ? " — " + blockedN + " with orders kept (cancel their orders first)" : ""));
          }} style={{ ...bulkBtn(), color: "#ff9d96" }}>Delete</button>
        </div>
      )}

      <EditProductDrawer
        open={!!editingProduct}
        product={editingProduct}
        store={store}
        onClose={() => setEditingId(null)}
        onSave={(updated) => { onUpdateProduct && onUpdateProduct(updated); setEditingId(null); }}
        onDelete={() => { if (editingProduct) { setEditingId(null); setDeleting(editingProduct); } }} />

      <BulkPricingModal
        open={bulkOpen}
        store={store}
        draftProducts={selProds.length ? selProds : visible.filter((p) => !p.isBundle)}
        onClose={() => setBulkOpen(false)}
        onApply={(ids, profit) => {
          onBulkPrice && onBulkPrice(ids, profit);
          setBulkOpen(false);
          if (multiSource) onToast && onToast("Bulk pricing applied — 1 held at MAP floor $24.00");
          setSel({});
        }} />

      <ProductDeleteModal
        product={deleting}
        store={store}
        onClose={() => setDeleting(null)}
        onConfirm={() => { if (deleting) { onRemove(deleting.id); onToast && onToast(`"${deleting.title}" deleted`); } setDeleting(null); }}
        onGoToBundle={typeof onOpenDetail === "function" ? (bid) => { setDeleting(null); onOpenDetail(bid); } : undefined}
        onGoToOrders={() => { setDeleting(null); window.__goToPendingOrder && window.__goToPendingOrder(); }} />
    </div>
  );
}

// ─────────── Add Products — six intake channels (Epic G) ───────────
function AddChannelsView({ onBack, onChannel }) {
  const channels = [
    { k: "marucci", label: "Add Marucci Products", desc: "Browse the ingested Marucci / Victus catalog by sport, category and product line. Availability visible at selection.", isNew: true },
    { k: "external", label: "External Customizer", desc: "Hand off to Marucci's bat or glove builder; the configured item returns here as a draft.", isNew: true },
    { k: "vault", label: "Add from Vault", desc: "Pull previously vaulted items — including pre-decorated blanks — into this store.", isNew: true },
    { k: "designs", label: "Saved Designs", desc: "Add products from your saved Customizer designs.", isNew: false },
    { k: "carts", label: "Saved Carts", desc: "Pull products from a saved cart.", isNew: false },
    { k: "custom", label: "Custom Products", desc: "Design a new product in a brand Customizer.", isNew: false },
  ];
  return (
    <div style={{ paddingBottom: 60 }}>
      <button onClick={onBack} style={{ background: "none", border: 0, padding: 0, fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, color: PTE_C.z500, cursor: "pointer", marginBottom: 14, display: "inline-block" }}>← Back to Products</button>
      <h2 style={{ fontSize: 24, fontWeight: 800, letterSpacing: "-.4px", margin: "0 0 6px", fontFamily: "Archivo, sans-serif", color: PTE_C.ink }}>Add Products</h2>
      <p style={{ fontSize: 14, color: PTE_C.z500, margin: "0 0 24px", maxWidth: 640, lineHeight: 1.5 }}>Every channel writes into the same canonical product record — the source is an attribute, not a separate type. Items land as drafts and go through the same publish gate.</p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 16, maxWidth: 1080 }}>
        {channels.map((ch) => (
          <button key={ch.k} onClick={() => onChannel(ch.k)} style={{ position: "relative", textAlign: "left", background: "#fff", border: "1px solid " + (ch.isNew ? PTE_C.z300 : PTE_C.z200), borderRadius: 10, padding: 22, cursor: "pointer", fontFamily: "inherit", minHeight: 120, boxShadow: ch.isNew ? "0 1px 3px rgba(20,20,30,.05)" : "none" }}>
            {ch.isNew && <span style={{ position: "absolute", top: 14, right: 14, fontSize: 9.5, fontWeight: 700, letterSpacing: ".8px", background: PTE_C.red, color: "#fff", borderRadius: 4, padding: "2px 7px" }}>NEW</span>}
            <span style={{ fontSize: 15, fontWeight: 700, display: "block", marginBottom: 6, color: PTE_C.ink }}>{ch.label}</span>
            <span style={{ fontSize: 12.5, color: PTE_C.z500, lineHeight: 1.5, display: "block" }}>{ch.desc}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

// ─────────── Marucci catalog browse + Decorate Selected exit ───────────
const MARUCCI_CATALOG = [
  { id: "c1", title: "Fleece Hoodie", sku: "MAFH-300", cat: "Fleece", cost: "$31.20", oos: false, photo: "performance-hoodie", dec: true },
  { id: "c2", title: "Dugout Pullover", sku: "MDP-210", cat: "Fleece", cost: "$34.60", oos: false, photo: "sfn-warmup", dec: true },
  { id: "c3", title: "Performance Tee", sku: "MPT-100", cat: "Tees", cost: "$12.40", oos: false, photo: "hooded-tech-tee", dec: true },
  { id: "c4", title: "Long-Sleeve Tee", sku: "MLT-110", cat: "Tees", cost: "$14.90", oos: true, letter: "T", dec: true },
  { id: "c5", title: "Coaches Polo", sku: "MCP-55", cat: "Polos", cost: "$21.00", oos: false, letter: "P", dec: true },
  { id: "c6", title: "Team Backpack", sku: "VBP-30", cat: "Bags", cost: "$29.80", oos: false, photo: "team-bag", dec: true },
  { id: "c7", title: "Bat Pack", sku: "MBP-20", cat: "Bags", cost: "$24.10", oos: false, photo: "squad-bag", dec: true },
  { id: "c8", title: "CAT X2 Bat (blank)", sku: "MCX2-33", cat: "Hard goods", cost: "$289.00", oos: false, letter: "H", dec: false },
];
function MarucciCatalogView({ store, onBack, onAddDrafts, onDecorate }) {
  const [cat, setCat] = React.useState("All");
  const [sel, setSel] = React.useState({});
  const items = MARUCCI_CATALOG.filter((c) => cat === "All" || c.cat === cat);
  const selected = MARUCCI_CATALOG.filter((c) => sel[c.id]);
  const toItem = (c) => ({ id: c.id, title: c.title, sku: c.sku, photo: c.photo || null, letter: c.letter, brand: c.sku.startsWith("V") ? "Victus" : "Marucci", source: "Marucci stock", category: c.cat, stock: c.oos ? "out" : "in", deco: "none", decoratable: c.dec, subtitle: c.sku + " · blank — supplier cost " + c.cost });
  return (
    <div style={{ paddingBottom: 100 }}>
      <button onClick={onBack} style={{ background: "none", border: 0, padding: 0, fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, color: PTE_C.z500, cursor: "pointer", marginBottom: 14, display: "inline-block" }}>← Back to channels</button>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, marginBottom: 6 }}>
        <h2 style={{ fontSize: 24, fontWeight: 800, letterSpacing: "-.4px", margin: 0, fontFamily: "Archivo, sans-serif", color: PTE_C.ink }}>Add Marucci Products</h2>
        <span style={{ fontSize: 12, color: PTE_C.z400 }}>Ingested catalog · synced 2h ago · availability live</span>
      </div>
      <p style={{ fontSize: 14, color: PTE_C.z500, margin: "0 0 20px", lineHeight: 1.5 }}>Select blanks to add as drafts, or select and decorate in one pass. Out-of-stock variants shown for planning; they publish hidden from the storefront.</p>
      <div style={{ display: "flex", gap: 8, marginBottom: 18, flexWrap: "wrap" }}>
        {["All", "Fleece", "Tees", "Polos", "Bags", "Hard goods"].map((c) => (
          <button key={c} onClick={() => setCat(c)} style={{ background: cat === c ? PTE_C.ink : "#fff", color: cat === c ? "#fff" : PTE_C.z700, border: "1px solid " + (cat === c ? PTE_C.ink : PTE_C.z300), borderRadius: 999, padding: "7px 16px", fontSize: 12.5, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>{c}</button>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 14, maxWidth: 1200 }}>
        {items.map((c) => (
          <button key={c.id} onClick={() => setSel((s) => ({ ...s, [c.id]: !s[c.id] }))} style={{ position: "relative", textAlign: "left", background: "#fff", border: "2px solid " + (sel[c.id] ? PTE_C.ink : PTE_C.z200), borderRadius: 10, padding: 16, cursor: "pointer", fontFamily: "inherit" }}>
            <span style={{ position: "absolute", top: 10, right: 10, width: 20, height: 20, borderRadius: 999, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, background: sel[c.id] ? PTE_C.ink : PTE_C.z100, color: sel[c.id] ? "#fff" : "transparent" }}>✓</span>
            {c.oos && <span style={{ position: "absolute", top: 12, left: 12, fontSize: 9.5, fontWeight: 700, letterSpacing: ".6px", background: PTE_C.z800, color: "#fff", borderRadius: 4, padding: "2px 7px" }}>OUT OF STOCK</span>}
            <span style={{ height: 110, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 10 }}>
              {c.photo
                ? <span style={{ width: "100%", height: 106, display: "flex", alignItems: "center", justifyContent: "center" }}><CatalogPhoto photo={c.photo} alt={c.title} /></span>
                : <span style={{ width: 76, height: 96, borderRadius: 8, background: PTE_C.z100, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, fontWeight: 700, color: PTE_C.z300 }}>{c.letter}</span>}
            </span>
            <span style={{ fontSize: 13, fontWeight: 700, display: "block", color: PTE_C.ink }}>{c.title}</span>
            <span style={{ fontSize: 11.5, color: PTE_C.z400, display: "block", marginTop: 2 }}>{c.sku} · {c.cat}</span>
            <span style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 8 }}>
              <span style={{ fontSize: 12, color: PTE_C.z500 }}>Cost <strong style={{ color: PTE_C.ink }}>{c.cost}</strong></span>
              <span style={{ fontSize: 10, fontWeight: 700, letterSpacing: ".4px", padding: "2px 8px", borderRadius: 999, background: c.dec ? PTE_C.indigoBg : PTE_C.z100, color: c.dec ? PTE_C.indigo : PTE_C.z400 }}>{c.dec ? "Decoratable" : "No zone map"}</span>
            </span>
          </button>
        ))}
      </div>
      {selected.length > 0 && (
        <div style={{ position: "fixed", left: "50%", transform: "translateX(-50%)", bottom: 24, zIndex: 60, background: PTE_C.ink, color: "#fff", borderRadius: 12, boxShadow: "0 12px 32px rgba(20,20,30,.3)", padding: "12px 18px", display: "flex", alignItems: "center", gap: 14 }}>
          <span style={{ fontSize: 13, fontWeight: 700 }}>{selected.length} selected</span>
          <button onClick={() => onAddDrafts(selected.map(toItem))} style={{ background: "#fff", color: PTE_C.ink, border: 0, borderRadius: 6, padding: "9px 16px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Add as drafts</button>
          <button onClick={() => onDecorate(selected.map((c) => ({ ...toItem(c), fromStore: false, ok: c.dec })))} style={{ background: PTE_C.red, color: "#fff", border: 0, borderRadius: 6, padding: "9px 16px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Decorate selected →</button>
        </div>
      )}
    </div>
  );
}

// ─────────── Batch decoration — review grid (Epic D) ───────────
function BatchDecorateView({ store, items, onCancel, onSave }) {
  const [rows, setRows] = React.useState(() => (items || []).map((b) => ({ ...b, ok: b.ok !== false, included: true })));
  const included = rows.filter((b) => b.included && b.ok);
  const mark = (store.teamName || "Team").split(/[\s—-]/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("").toUpperCase();
  return (
    <div style={{ paddingBottom: 60 }}>
      <button onClick={onCancel} style={{ background: "none", border: 0, padding: 0, fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, color: PTE_C.z500, cursor: "pointer", marginBottom: 14, display: "inline-block" }}>← Cancel batch</button>
      <h2 style={{ fontSize: 24, fontWeight: 800, letterSpacing: "-.4px", margin: "0 0 6px", fontFamily: "Archivo, sans-serif", color: PTE_C.ink }}>Batch decoration — review</h2>
      <p style={{ fontSize: 14, color: PTE_C.z500, margin: "0 0 18px", maxWidth: 720, lineHeight: 1.5 }}>One placement, resolved per product through each template's imprint-zone map. Spot-check the grid; override or exclude before committing. Renders are produced server-side after save.</p>
      <div style={{ display: "flex", alignItems: "center", gap: 14, background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, padding: "14px 18px", marginBottom: 18, maxWidth: 720 }}>
        <span style={{ width: 44, height: 44, borderRadius: 8, background: (store.teamColors && store.teamColors[0]) || PTE_C.ink, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 16, fontWeight: 800, fontFamily: "Archivo, sans-serif", flexShrink: 0 }}>{mark}</span>
        <div>
          <div style={{ fontSize: 13, fontWeight: 700, color: PTE_C.ink }}>{store.teamName || "Team"} — Primary mark</div>
          <div style={{ fontSize: 12, color: PTE_C.z500 }}>Left chest · 3.5 in wide · Embroidery · From team artwork library</div>
        </div>
        <span style={{ marginLeft: "auto", fontSize: 10.5, fontWeight: 700, letterSpacing: ".6px", textTransform: "uppercase", background: PTE_C.okBg, color: PTE_C.ok, borderRadius: 999, padding: "3px 10px" }}>Production-ready</span>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 14, maxWidth: 1200, marginBottom: 20 }}>
        {rows.map((b, i) => (
          <div key={b.id} style={{ background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, padding: 16, opacity: b.included && b.ok ? 1 : .55 }}>
            <span style={{ height: 100, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 10, position: "relative" }}>
              {b.photo
                ? <span style={{ width: "100%", height: 96, display: "flex", alignItems: "center", justifyContent: "center", opacity: .9 }}><CatalogPhoto photo={b.photo} alt={b.title} /></span>
                : <span style={{ width: 70, height: 88, borderRadius: 8, background: PTE_C.z100, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, fontWeight: 700, color: PTE_C.z300 }}>{(b.category || "P").slice(0, 1)}</span>}
              {b.ok && <span style={{ position: "absolute", left: "calc(50% - 26px)", top: 34, width: 18, height: 18, borderRadius: 4, background: (store.teamColors && store.teamColors[0]) || PTE_C.ink, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 8, fontWeight: 800 }}>{mark}</span>}
            </span>
            <div style={{ fontSize: 13, fontWeight: 700, color: PTE_C.ink }}>{b.title}</div>
            <div style={{ fontSize: 11.5, color: PTE_C.z500, margin: "3px 0 8px" }}>{b.ok ? "Left chest · resolves to 3.5 in · Embroidery" : "No imprint zone on this template"}</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ fontSize: 10.5, fontWeight: 700, padding: "3px 10px", borderRadius: 999, background: !b.ok ? PTE_C.warnBg : b.included ? PTE_C.okBg : PTE_C.z100, color: !b.ok ? PTE_C.warn : b.included ? PTE_C.ok : PTE_C.z400 }}>{b.ok ? (b.included ? "Resolved" : "Excluded") : "Needs review"}</span>
              <button onClick={() => setRows((r) => r.map((x, j) => j === i ? { ...x, included: !x.included } : x))} style={{ background: "none", border: 0, fontSize: 11.5, fontWeight: 600, color: PTE_C.z400, cursor: "pointer", fontFamily: "inherit", textDecoration: "underline", textUnderlineOffset: 2 }}>{b.included ? "Exclude" : "Include"}</button>
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
        <button onClick={() => onSave(included)} disabled={included.length === 0} style={{ background: included.length ? PTE_C.ink : PTE_C.z100, color: included.length ? "#fff" : PTE_C.z400, border: 0, borderRadius: 6, padding: "12px 24px", fontSize: 13.5, fontWeight: 700, cursor: included.length ? "pointer" : "default", fontFamily: "inherit" }}>Save all — {included.length} decorated drafts</button>
        <span style={{ fontSize: 12.5, color: PTE_C.z500 }}>Creates placement records → server render queued → art enters approval as <strong>Draft</strong></span>
      </div>
    </div>
  );
}

// ─────────── Product Images view — renders, imprint record, approval (Epic C) ───────────
function ProductImagesView({ product, store, onBack, onOpenEditor, onUpdateProduct, onToast }) {
  const p = product;
  const m = pteMeta(p);
  const dm = PTE_DECO[m.deco] || PTE_DECO.na;
  const stateLabel = { none: "Not decorated", render: "Render pending", draft: "Draft", submitted: "Submitted", approved: "Approved", rejected: "Rejected", na: "—" }[m.deco];
  const vChipC = (state) => ({ Approved: [PTE_C.okBg, PTE_C.ok], Draft: [PTE_C.warnBg, PTE_C.warn], Submitted: [PTE_C.blueBg, PTE_C.blue], Rejected: [PTE_C.rejBg, PTE_C.redInk], "Render pending": [PTE_C.indigoBg, PTE_C.indigo] })[state] || [PTE_C.z100, PTE_C.z500];
  const variants = [
    { label: "Primary · Front", photo: p.photo, state: stateLabel },
    { label: "Primary · Back", photo: p.photo, state: stateLabel },
    { label: "Alt colorway · Front", photo: null, state: "Render pending" },
    { label: "Alt colorway · Back", photo: null, state: "Render pending" },
  ];
  const stepIdx = { none: -1, render: 0, draft: 0, submitted: 1, approved: 2, rejected: 1, na: -1 }[m.deco];
  const steps = ["Draft", "Submitted", m.deco === "rejected" ? "Rejected" : "Approved"].map((label, i) => ({
    label, line: i < 2,
    note: i === 0 ? "Placement saved from the editor" : i === 1 ? "Awaiting seller art review" : m.deco === "rejected" ? "Logo too small for embroidery at 3.5in — resize to 4in" : "Cleared for production & storefront",
    on: i <= stepIdx, red: m.deco === "rejected" && i === 1,
  }));
  const canSubmit = ["draft", "rejected"].includes(m.deco);
  const imprint = [
    ["Zone", "Left chest"], ["Size", "3.5 in wide"], ["Method", "Embroidery"],
    ["Artwork", (store.teamName || "Team") + " primary (vector)"], ["Colors", "PMS 289C · 152C"],
    ["Personalization", m.source === "Prolook custom" ? "Name & number (roster pre-fill)" : "Not supported (stock)"],
    ["Record", "IMP-" + String(p.id).replace(/[^A-Z0-9]/gi, "").slice(-6).toUpperCase()],
  ];
  return (
    <div style={{ paddingBottom: 60 }}>
      <button onClick={onBack} style={{ background: "none", border: 0, padding: 0, fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, color: PTE_C.z500, cursor: "pointer", marginBottom: 14, display: "inline-block" }}>← Back to Products</button>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, marginBottom: 18 }}>
        <h2 style={{ fontSize: 24, fontWeight: 800, letterSpacing: "-.4px", margin: 0, fontFamily: "Archivo, sans-serif", color: PTE_C.ink }}>{p.title}</h2>
        <span style={{ fontSize: 12.5, color: PTE_C.z400 }}>{m.brand} · {m.source} · {dm.label}</span>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 340px", gap: 20, alignItems: "start", maxWidth: 1200 }}>
        <div style={{ background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, padding: 20 }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
            <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: PTE_C.z500 }}>Variant image set — composited renders</span>
            <button onClick={() => onOpenEditor && onOpenEditor()} style={{ background: PTE_C.ink, color: "#fff", border: 0, borderRadius: 6, padding: "9px 18px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>✎ Edit in Image Editor</button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12 }}>
            {variants.map((v, i) => (
              <div key={i} style={{ border: "1px solid " + PTE_C.z200, borderRadius: 8, padding: 10, textAlign: "center" }}>
                <span style={{ height: 96, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 8 }}>
                  {v.photo
                    ? <span style={{ width: "100%", height: 92, display: "flex", alignItems: "center", justifyContent: "center" }}><CatalogPhoto photo={v.photo} alt={v.label} /></span>
                    : <span style={{ width: 64, height: 84, borderRadius: 6, background: "linear-gradient(90deg," + PTE_C.z100 + " 25%," + PTE_C.z50 + " 50%," + PTE_C.z100 + " 75%)" }} />}
                </span>
                <div style={{ fontSize: 11.5, fontWeight: 600, color: PTE_C.ink }}>{v.label}</div>
                <span style={{ display: "inline-block", marginTop: 5, fontSize: 9.5, fontWeight: 700, letterSpacing: ".4px", padding: "2px 8px", borderRadius: 999, background: vChipC(v.state)[0], color: vChipC(v.state)[1] }}>{v.state}</span>
              </div>
            ))}
          </div>
          <div style={{ marginTop: 14, fontSize: 12, color: PTE_C.z400, lineHeight: 1.5 }}>Storefront imagery is derived — the server compositor renders every image from the placement record. A change to artwork or placement invalidates and re-queues the set.</div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <div style={{ background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, padding: 18 }}>
            <div style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: PTE_C.z500, marginBottom: 12 }}>Production imprint record</div>
            {imprint.map(([k, v]) => (
              <div key={k} style={{ display: "flex", justifyContent: "space-between", gap: 12, padding: "7px 0", borderBottom: "1px solid " + PTE_C.z100, fontSize: 12.5 }}>
                <span style={{ color: PTE_C.z500 }}>{k}</span><span style={{ fontWeight: 600, textAlign: "right", color: PTE_C.ink }}>{v}</span>
              </div>
            ))}
          </div>
          <div style={{ background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, padding: 18 }}>
            <div style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: PTE_C.z500, marginBottom: 12 }}>Art approval</div>
            {steps.map((s, i) => (
              <div key={i} style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
                <span style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                  <span style={{ width: 10, height: 10, borderRadius: 999, marginTop: 3, background: s.on ? (s.red ? PTE_C.red : PTE_C.ink) : PTE_C.z200 }} />
                  {s.line && <span style={{ width: 2, height: 22, background: PTE_C.z200 }} />}
                </span>
                <span style={{ fontSize: 12.5, paddingBottom: 10 }}>
                  <strong style={{ color: s.on ? PTE_C.ink : PTE_C.z400 }}>{s.label}</strong>
                  <span style={{ display: "block", color: PTE_C.z400, fontSize: 11.5 }}>{s.note}</span>
                </span>
              </div>
            ))}
            <button disabled={!canSubmit} onClick={() => { onUpdateProduct({ ...p, deco: "submitted" }); onToast && onToast("Art submitted — entered the seller art approver's review queue"); }} style={{ width: "100%", marginTop: 12, border: 0, borderRadius: 8, padding: 11, fontSize: 12.5, fontWeight: 700, fontFamily: "inherit", cursor: canSubmit ? "pointer" : "default", background: canSubmit ? PTE_C.ink : PTE_C.z100, color: canSubmit ? "#fff" : PTE_C.z400 }}>
              {m.deco === "submitted" ? "Awaiting review" : m.deco === "approved" ? "Approved" : m.deco === "rejected" ? "Resubmit for approval" : "Submit for approval"}
            </button>
            <div style={{ fontSize: 11.5, color: PTE_C.z400, marginTop: 8, lineHeight: 1.5 }}>
              {(store.artPolicy || "block-publish") === "block-publish" ? "Policy: unapproved art blocks publish (strict, default). Flip in Store Settings." : "Policy: publishable while in review; order submission is gated. Flip in Store Settings."}
            </div>
          </div>
          <button onClick={() => { window.__vaultItems = window.__vaultItems || []; window.__vaultItems.push({ id: "v-" + p.id + "-" + Date.now(), title: p.title, brand: m.brand, source: m.source, photo: p.photo, category: m.category, deco: (store.teamName || "Team") + " primary · Left chest 3.5in · Embroidery · " + stateLabel, used: "This store" }); onToast && onToast("Saved to Stock Vault with its decoration record"); }} style={{ background: "#fff", border: "1px solid " + PTE_C.z300, borderRadius: 8, padding: 11, fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", color: PTE_C.z800 }}>Save to Stock Vault</button>
        </div>
      </div>
    </div>
  );
}

// ─────────── Image Editor — artwork placement across the variant image set ───────────
// Placement is the record: layers are stored per variant (colorway × view), the
// server compositor derives every storefront render from them. Copy a layer once
// and paste it into the ticked variants; ink flips for contrast on dark bodies.
const IE_FONTS = [
  { id: "block", label: "Block", stack: "Archivo, sans-serif", weight: 800, ls: "1px" },
  { id: "sans", label: "Sans", stack: "Inter, sans-serif", weight: 700, ls: ".5px" },
  { id: "mono", label: "Mono", stack: "'JetBrains Mono', ui-monospace, Menlo, monospace", weight: 500, ls: "1.5px" },
];
const IE_VIEWS = [{ id: "front", name: "Front" }, { id: "back", name: "Back" }];
// Only an em/en-dash suffix is a colorway ("Fleece Hoodie — Charcoal"); a hyphen
// inside a product word is not ("Quarter-Zip"). Alternates that collide with the
// derived primary drop out, so every label in the variant strip stays unique.
function ieColorways(product) {
  const seg = /[—–]\s*([A-Za-z][A-Za-z ]*)$/.exec(product.title || "");
  const raw = seg ? seg[1].trim() : "";
  const primary = { id: "primary", name: raw || "Primary", filter: "none", dark: false };
  const alts = [
    { id: "navy", name: "Navy", filter: "brightness(.45) sepia(1) hue-rotate(190deg) saturate(3.2)", dark: true },
    { id: "black", name: "Black", filter: "brightness(.32) saturate(.12)", dark: true },
  ];
  return [primary].concat(alts.filter((a) => a.name.toLowerCase() !== primary.name.toLowerCase()));
}
// Store titles carry a season ("Lincoln High Baseball — Fall 2026"); artwork never
// does, so season and year tokens are stripped before a mark is derived.
function ieTeamWords(store) {
  const name = String(store.teamName || store.storeTitle || "Team").split(/[—–]/)[0];
  const drop = /^(fall|spring|summer|winter|season|\d{2,4}(-\d{2,4})?)$/i;
  const words = name.split(/[\s\-_/]+/).filter((w) => w && !drop.test(w));
  return words.length ? words : ["Team"];
}
function ieTeamName(store) {
  const w = ieTeamWords(store);
  const two = w.slice(0, 2).join(" ");
  return (two.length <= 14 ? two : w[0]).toUpperCase();
}
function ieTeamArt(store) {
  const words = ieTeamWords(store);
  const initials = words.slice(0, 2).map((w) => w[0]).join("").toUpperCase();
  const word = words[0].toUpperCase();
  return [
    { id: "primary", name: "team-primary.svg", mark: initials, meta: "Vector · 2 color", w: 14 },
    { id: "wordmark", name: "team-wordmark.svg", mark: word, meta: "Vector · 1 color", w: 34 },
    { id: "alt", name: "alternate-mark.png", mark: "ALT", meta: "PNG · needs vector", w: 20 },
  ];
}
// Garment reads ~20in across the render, so width% maps to imprint inches.
function ieZone(l) {
  if (l.w >= 45) return "Full front";
  if (l.y > 66) return "Lower front";
  if (l.y < 30) return "Collar · upper";
  if (l.x < 42) return "Left chest";
  if (l.x > 58) return "Right chest";
  return "Center chest";
}
function ieInches(w) { return (Math.round(w * 0.2 * 10) / 10).toFixed(1) + " in"; }

function ProductImageEditor({ product, store, onBack, onSave }) {
  const p = product;
  const m = pteMeta(p);
  const colorways = React.useMemo(() => ieColorways(p), [p.id, p.title]);
  const library = React.useMemo(() => ieTeamArt(store), [store.teamName, store.storeTitle]);
  const swatches = React.useMemo(() => {
    // Near-blacks and near-whites collapse so the row never shows two swatches
    // a printer would treat as the same ink.
    const norm = (c) => { const h = String(c).toLowerCase(); if (/^#(0[0-9a-f]|1[0-8])/.test(h)) return "#09090b"; if (/^#(f[0-9a-f]){1,3}/.test(h)) return "#ffffff"; return h; };
    const all = ["#ffffff", "#09090b"].concat(store.teamColors || []);
    return all.filter((c, i) => c && all.findIndex((x) => norm(x) === norm(c)) === i).slice(0, 5);
  }, [store.teamColors]);
  const teamInk = (store.teamColors && store.teamColors[0]) || PTE_C.ink;

  const initial = React.useMemo(() => {
    const by = {};
    colorways.forEach((c) => IE_VIEWS.forEach((v) => { by[c.id + "-" + v.id] = []; }));
    if (["draft", "submitted", "approved", "rejected"].includes(m.deco)) {
      by["primary-front"] = [{ id: "l1", type: "art", src: "primary", name: library[0].name, mark: library[0].mark, x: 34, y: 43, w: 14, rot: 0, fx: 1, fy: 1, color: teamInk, removeWhite: true }];
      by["primary-back"] = [{ id: "l2", type: "text", name: library[1].mark, text: library[1].mark, x: 50, y: 40, w: 38, rot: 0, fx: 1, fy: 1, color: teamInk, font: "block" }];
    }
    return by;
  }, [p.id]);

  const [layersBy, setLayersBy] = React.useState(initial);
  const [active, setActive] = React.useState("primary-front");
  const [selectedId, setSelectedId] = React.useState(() => ((initial["primary-front"] || [])[0] || {}).id || null);
  const [checked, setChecked] = React.useState({});
  const [clipboard, setClipboard] = React.useState(null);
  const [panel, setPanel] = React.useState(null);
  const [pick, setPick] = React.useState(library[0].id);
  const [undoStack, setUndoStack] = React.useState([]);
  const [redoStack, setRedoStack] = React.useState([]);
  const [toast, setToast] = React.useState(null);
  const [saved, setSaved] = React.useState(true);

  const canvasRef = React.useRef(null);
  const toastTimer = React.useRef(null);
  // Layer type is drawn in px, so the canvas width has to be real: a % width can
  // only stay truthful against the inch readout if the glyphs fit their box.
  const [canvasW, setCanvasW] = React.useState(520);
  React.useEffect(() => {
    const el = canvasRef.current;
    if (!el) return;
    const read = () => { const w = el.getBoundingClientRect().width; if (w) setCanvasW(w); };
    read();
    if (!window.ResizeObserver) { window.addEventListener("resize", read); return () => window.removeEventListener("resize", read); }
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const fitPx = (text, wPct, inset, cap, ratio) => {
    const n = Math.max(1, String(text == null ? "" : text).length);
    return Math.max(6, Math.min(cap, (canvasW * wPct / 100) * inset / (n * ratio)));
  };
  const live = React.useRef({});
  live.current = { layersBy, active };
  React.useEffect(() => () => clearTimeout(toastTimer.current), []);
  const flash = (msg) => { clearTimeout(toastTimer.current); setToast(msg); toastTimer.current = setTimeout(() => setToast(null), 2400); };

  const snap = () => { const o = {}; const cur = live.current.layersBy; Object.keys(cur).forEach((k) => { o[k] = cur[k].map((l) => ({ ...l })); }); return o; };
  const pushUndo = () => { setUndoStack((u) => [...u, snap()].slice(-40)); setRedoStack([]); };
  const commit = (next) => { pushUndo(); setLayersBy(next); setSaved(false); };

  const cw = colorways.find((c) => c.id === active.split("-")[0]) || colorways[0];
  const view = IE_VIEWS.find((v) => v.id === active.split("-")[1]) || IE_VIEWS[0];
  const layers = layersBy[active] || [];
  const sel = layers.find((l) => l.id === selectedId) || null;
  const checkedIds = Object.keys(checked).filter((k) => checked[k]);
  const setLayers = (list, nextSel) => { commit({ ...layersBy, [active]: list }); if (nextSel !== undefined) setSelectedId(nextSel); };
  const patchSel = (patch) => { if (!sel) return; setLayers(layers.map((l) => l.id === sel.id ? { ...l, ...patch } : l)); };
  const needSel = () => { if (!sel) { flash("Select a layer first"); return true; } return false; };

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const startDrag = (e, layer, mode, corner) => {
    e.preventDefault(); e.stopPropagation();
    const rect = canvasRef.current && canvasRef.current.getBoundingClientRect();
    if (!rect) return;
    const start = { mx: e.clientX, my: e.clientY, x: layer.x, y: layer.y, w: layer.w };
    setSelectedId(layer.id);
    pushUndo();
    const move = (ev) => {
      const dx = ((ev.clientX - start.mx) / rect.width) * 100;
      const dy = ((ev.clientY - start.my) / rect.height) * 100;
      const key = live.current.active;
      setLayersBy((cur) => ({ ...cur, [key]: (cur[key] || []).map((l) => {
        if (l.id !== layer.id) return l;
        if (mode === "move") return { ...l, x: clamp(start.x + dx, 3, 97), y: clamp(start.y + dy, 3, 97) };
        const sign = (corner === "se" || corner === "ne") ? 1 : -1;
        return { ...l, w: clamp(start.w + dx * 2 * sign, 6, 90) };
      }) }));
      setSaved(false);
    };
    const up = () => { window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };
  const startGrip = (e, layer) => {
    e.preventDefault(); e.stopPropagation();
    const list = layers;
    const from = list.findIndex((l) => l.id === layer.id);
    const startY = e.clientY;
    let to = from;
    const move = (ev) => { to = clamp(from - Math.round((ev.clientY - startY) / 56), 0, list.length - 1); };
    const up = () => {
      window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up);
      if (to !== from) { const next = list.slice(); const [item] = next.splice(from, 1); next.splice(to, 0, item); setLayers(next); }
    };
    setSelectedId(layer.id);
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };

  const photoSrc = p.photo ? `assets/products/${p.photo}.png` : null;
  const imgStyle = { position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", pointerEvents: "none", filter: cw.filter, transform: view.id === "back" ? "scaleX(-1)" : "none" };
  const toolBtn = { display: "flex", alignItems: "center", gap: 6, padding: "7px 10px", borderRadius: 6, border: 0, background: "none", fontFamily: "inherit", fontSize: 12.5, color: PTE_C.z700, cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0 };
  const divider = <span style={{ width: 1, height: 22, background: PTE_C.z200, margin: "0 6px", flexShrink: 0 }} />;
  const sectionLabel = { fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: PTE_C.z500 };
  const swatchStyle = (c, big) => ({ width: big ? 28 : 20, height: big ? 28 : 20, borderRadius: 5, background: c, cursor: "pointer", flexShrink: 0, padding: 0,
    border: "1px solid " + (String(c).toLowerCase() === "#ffffff" ? PTE_C.z300 : "transparent"),
    boxShadow: sel && String(sel.color).toLowerCase() === String(c).toLowerCase() ? "0 0 0 2px " + PTE_C.ink : "none" });

  const doCopy = () => { if (needSel()) return; setClipboard({ ...sel }); flash("Copied " + sel.name); };
  const doPaste = () => {
    if (!clipboard) { flash("Nothing in the clipboard — copy a layer first"); return; }
    if (!checkedIds.length) { flash("Tick the variants to paste into"); return; }
    const next = { ...layersBy };
    checkedIds.forEach((vid, i) => {
      const dark = (colorways.find((c) => c.id === vid.split("-")[0]) || {}).dark;
      const lc = String(clipboard.color).toLowerCase();
      const color = lc === "#ffffff" && !dark ? PTE_C.ink : ((lc === "#09090b" || lc === "#0e0e10") && dark ? "#ffffff" : clipboard.color);
      next[vid] = [...(next[vid] || []), { ...clipboard, color, id: "l" + Date.now() + "_" + i }];
    });
    commit(next);
    flash("Pasted " + clipboard.name + " into " + checkedIds.length + " variant" + (checkedIds.length === 1 ? "" : "s") + " — ink flipped for contrast");
  };
  const doUndo = () => {
    if (!undoStack.length) { flash("Nothing to undo"); return; }
    const prev = undoStack[undoStack.length - 1];
    setRedoStack((r) => [...r, snap()]); setUndoStack((u) => u.slice(0, -1)); setLayersBy(prev); setSaved(false);
  };
  const doRedo = () => {
    if (!redoStack.length) { flash("Nothing to redo"); return; }
    const next = redoStack[redoStack.length - 1];
    setUndoStack((u) => [...u, snap()]); setRedoStack((r) => r.slice(0, -1)); setLayersBy(next); setSaved(false);
  };
  // A new layer never lands under one already on this variant.
  const freeY = (base) => clamp(base + (layers.length ? 12 * layers.length : 0), 12, 64);
  const doInsert = () => {
    const art = library.find((a) => a.id === pick);
    if (!art) { flash("Pick an artwork file first"); return; }
    const layer = { id: "l" + Date.now(), type: "art", src: art.id, name: art.name, mark: art.mark, x: 50, y: freeY(44), w: art.w, rot: 0, fx: 1, fy: 1, color: cw.dark ? "#ffffff" : teamInk, removeWhite: true };
    setLayers([...layers, layer], layer.id);
    setPanel(null);
    flash("Inserted " + art.name);
  };
  const doAddText = () => {
    const label = ieTeamName(store);
    const layer = { id: "l" + Date.now(), type: "text", name: label, text: label, x: 50, y: freeY(44), w: 34, rot: 0, fx: 1, fy: 1, color: cw.dark ? "#ffffff" : teamInk, font: "block" };
    setLayers([...layers, layer], layer.id);
  };
  const doSaveAll = () => {
    const images = Object.keys(layersBy).filter((k) => (layersBy[k] || []).length).length;
    const dirty = !saved;
    setSaved(true);
    onSave && onSave({ dirty, images, zone: sel ? ieZone(sel) : (layersBy["primary-front"] || [])[0] ? ieZone(layersBy["primary-front"][0]) : "Left chest" });
    flash(images ? "Saved placement on " + images + " product image" + (images === 1 ? "" : "s") + " — renders re-queued" : "Saved — no artwork placed yet");
  };

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 380, display: "flex", flexDirection: "column", background: PTE_C.z100, color: PTE_C.ink, fontFamily: '"Inter",system-ui,sans-serif', userSelect: "none", overflow: "hidden" }}>

      <div style={{ height: 56, flexShrink: 0, background: "#fff", borderBottom: "1px solid " + PTE_C.z200, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 16px", gap: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, minWidth: 0 }}>
          <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 12px", border: "1px solid " + PTE_C.z300, borderRadius: 6, background: "#fff", fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, cursor: "pointer", flexShrink: 0, color: PTE_C.ink }}>← Back</button>
          {divider}
          <span style={{ minWidth: 0 }}>
            <span style={{ display: "block", fontSize: 13.5, fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.title}{p.sku ? " — " + p.sku : ""}</span>
            <span style={{ display: "block", fontSize: 11, color: PTE_C.z500, whiteSpace: "nowrap" }}>{store.storeTitle || store.teamName} · {m.brand} · Image editor</span>
          </span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
          <span style={{ fontSize: 12, color: saved ? PTE_C.z500 : PTE_C.warn, whiteSpace: "nowrap" }}>{saved ? "All changes saved" : "Unsaved changes"}</span>
          <button onClick={doSaveAll} style={{ background: PTE_C.ink, color: "#fff", border: 0, borderRadius: 6, padding: "10px 20px", fontSize: 12.5, fontWeight: 700, fontFamily: "inherit", cursor: "pointer" }}>Save all</button>
        </div>
      </div>

      <div style={{ height: 48, flexShrink: 0, background: "#fff", borderBottom: "1px solid " + PTE_C.z200, display: "flex", alignItems: "center", padding: "0 12px", gap: 2, overflowX: "auto", overflowY: "hidden" }}>
        <button onClick={doCopy} style={toolBtn}>Copy</button>
        <button onClick={doPaste} style={toolBtn}>Paste</button>
        {divider}
        <button onClick={doUndo} style={Object.assign({}, toolBtn, { color: undoStack.length ? PTE_C.z700 : PTE_C.z300 })}>↺ Undo</button>
        <button onClick={doRedo} style={Object.assign({}, toolBtn, { color: redoStack.length ? PTE_C.z700 : PTE_C.z300 })}>↻ Redo</button>
        {divider}
        <button onClick={() => { if (!needSel()) patchSel({ fx: sel.fx * -1 }); }} style={toolBtn}>Flip H</button>
        <button onClick={() => { if (!needSel()) patchSel({ fy: sel.fy * -1 }); }} style={toolBtn}>Flip V</button>
        {divider}
        <button onClick={() => { if (!needSel()) patchSel({ rot: sel.rot - 15 }); }} style={toolBtn}>⟲ 15°</button>
        <button onClick={() => { if (!needSel()) patchSel({ rot: sel.rot + 15 }); }} style={toolBtn}>⟳ 15°</button>
        <span style={{ fontSize: 11.5, color: PTE_C.z400, fontFamily: "'JetBrains Mono', ui-monospace, monospace", minWidth: 38, flexShrink: 0 }}>{sel ? sel.rot + "°" : "—"}</span>
        {divider}
        <span style={{ fontSize: 12.5, color: PTE_C.z700, whiteSpace: "nowrap", flexShrink: 0, marginRight: 4 }}>Recolor</span>
        <span style={{ display: "flex", gap: 6, flexShrink: 0 }}>
          {swatches.map((c) => <button key={c} onClick={() => { if (!needSel()) patchSel({ color: c }); }} title={c} style={swatchStyle(c, false)} />)}
        </span>
      </div>

      <div style={{ flex: 1, minHeight: 0, display: "flex" }}>

        <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
          <div style={{ flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, padding: "12px 20px 0" }}>
            <span style={sectionLabel}>Canvas · {cw.name} · {view.name}</span>
            <span style={{ fontSize: 12, color: PTE_C.z500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{sel ? "Selected: " + sel.name : "Nothing selected"}</span>
          </div>
          <div style={{ flex: 1, minHeight: 0, display: "flex", alignItems: "center", justifyContent: "center", padding: "14px 20px 18px" }}>
            <div ref={canvasRef} onPointerDown={() => setSelectedId(null)} style={{ position: "relative", aspectRatio: "10 / 11", height: "100%", maxWidth: "100%", background: "#fff", border: "1px solid " + PTE_C.z200, borderRadius: 10, boxShadow: "0 4px 12px rgba(9,9,11,.06)", overflow: "hidden" }}>
              {photoSrc
                ? <img src={__asset(photoSrc)} alt={p.title} draggable={false} style={imgStyle} />
                : <span style={{ position: "absolute", inset: "14%", border: "1.5px dashed " + PTE_C.z300, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12.5, color: PTE_C.z400, background: cw.dark ? PTE_C.z800 : PTE_C.z50 }}>Blank {m.category.toLowerCase()} — render pending</span>}
              <span style={{ position: "absolute", left: 12, bottom: 10, fontSize: 10, color: PTE_C.z400, fontFamily: "'JetBrains Mono', ui-monospace, monospace" }}>{(p.sku || "IMG").replace(/[^A-Za-z0-9]/g, "")}_{cw.id}_{view.id}.png · 1000 × 1100</span>
              {layers.map((l, i) => {
                const isSel = l.id === selectedId;
                const f = IE_FONTS.find((x) => x.id === l.font) || IE_FONTS[0];
                return (
                  <div key={l.id} onPointerDown={(e) => startDrag(e, l, "move")} style={{ position: "absolute", left: l.x + "%", top: l.y + "%", width: l.w + "%", transform: `translate(-50%,-50%) rotate(${l.rot}deg) scale(${l.fx},${l.fy})`, display: "flex", alignItems: "center", justifyContent: "center", cursor: "move", zIndex: 10 + i, outline: isSel ? "1.5px solid " + PTE_C.red : "none", outlineOffset: 4 }}>
                    {l.type === "art" && !l.removeWhite && <span style={{ position: "absolute", inset: "-8%", background: "#fff", borderRadius: 2 }} />}
                    {l.type === "art"
                      ? <span style={{ position: "relative", display: "block", width: "100%", boxSizing: "border-box", textAlign: "center", fontFamily: "Archivo, sans-serif", fontWeight: 800, fontSize: fitPx(l.mark, l.w, 0.8, 54, 0.66), letterSpacing: "1px", color: l.color, lineHeight: 1.05, padding: "9% 6%", border: "2px solid " + l.color, borderRadius: 3 }}>{l.mark}</span>
                      : <span style={{ position: "relative", display: "block", width: "100%", textAlign: "center", fontFamily: f.stack, fontWeight: f.weight, fontSize: fitPx(l.text, l.w, 0.98, 46, 0.78), letterSpacing: f.ls, color: l.color, lineHeight: 1.1, whiteSpace: "nowrap" }}>{l.text}</span>}
                    {isSel && ["nw", "ne", "se", "sw"].map((c) => (
                      <span key={c} onPointerDown={(e) => startDrag(e, l, "scale", c)} style={{ position: "absolute", width: 9, height: 9, background: "#fff", border: "2px solid " + PTE_C.red, borderRadius: 2, zIndex: 3,
                        cursor: (c === "nw" || c === "se") ? "nwse-resize" : "nesw-resize",
                        top: c[0] === "n" ? -9 : "auto", bottom: c[0] === "s" ? -9 : "auto", left: c[1] === "w" ? -9 : "auto", right: c[1] === "e" ? -9 : "auto" }} />
                    ))}
                  </div>
                );
              })}
            </div>
          </div>

          <div style={{ flexShrink: 0, background: "#fff", borderTop: "1px solid " + PTE_C.z200, padding: "14px 18px 16px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, marginBottom: 12 }}>
              <span style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={sectionLabel}>Variants</span>
                <span style={{ fontSize: 12, color: PTE_C.z400, whiteSpace: "nowrap" }}>{colorways.length} colorways × {IE_VIEWS.length} views · {checkedIds.length} ticked</span>
              </span>
              <span style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
                <span style={{ fontSize: 12, color: PTE_C.z500, whiteSpace: "nowrap" }}>{clipboard ? "Clipboard: " + clipboard.name : "Clipboard empty"}</span>
                <button onClick={doPaste} style={{ padding: "8px 14px", borderRadius: 6, border: 0, fontSize: 12.5, fontWeight: 700, fontFamily: "inherit", cursor: "pointer", background: PTE_C.ink, color: "#fff", whiteSpace: "nowrap" }}>Paste to {checkedIds.length} variant{checkedIds.length === 1 ? "" : "s"}</button>
              </span>
            </div>
            <div style={{ display: "flex", gap: 10, overflowX: "auto", paddingBottom: 4 }}>
              {colorways.map((c) => IE_VIEWS.map((v) => {
                const id = c.id + "-" + v.id;
                const on = id === active;
                const tick = !!checked[id];
                const count = (layersBy[id] || []).length;
                return (
                  <div key={id} onClick={() => { setActive(id); setSelectedId(((layersBy[id] || [])[0] || {}).id || null); }} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px 8px 8px", border: "1px solid " + (on ? PTE_C.ink : PTE_C.z200), boxShadow: on ? "0 0 0 1px " + PTE_C.ink : "none", borderRadius: 8, cursor: "pointer", background: "#fff", flexShrink: 0 }}>
                    <span style={{ width: 38, height: 42, borderRadius: 5, flexShrink: 0, overflow: "hidden", background: PTE_C.z50, position: "relative", display: "block" }}>
                      {photoSrc && <img src={__asset(photoSrc)} alt="" draggable={false} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", filter: c.filter, transform: v.id === "back" ? "scaleX(-1)" : "none" }} />}
                    </span>
                    <span style={{ display: "flex", flexDirection: "column", gap: 2, minWidth: 0 }}>
                      <span style={{ fontSize: 12.5, fontWeight: 600, whiteSpace: "nowrap" }}>{c.name}</span>
                      <span style={{ fontSize: 11, color: PTE_C.z500, whiteSpace: "nowrap" }}>{v.name} · {count === 1 ? "1 layer" : count + " layers"}</span>
                    </span>
                    <span onClick={(e) => { e.stopPropagation(); setChecked((s) => ({ ...s, [id]: !s[id] })); }} style={{ width: 20, height: 20, borderRadius: 5, flexShrink: 0, border: "1px solid " + (tick ? PTE_C.ink : PTE_C.z300), background: tick ? PTE_C.ink : "#fff", color: "#fff", fontSize: 11, display: "flex", alignItems: "center", justifyContent: "center" }}>{tick ? "✓" : ""}</span>
                  </div>
                );
              }))}
            </div>
          </div>
        </div>

        <div style={{ width: 340, flexShrink: 0, background: "#fff", borderLeft: "1px solid " + PTE_C.z200, display: "flex", flexDirection: "column", minHeight: 0 }}>
          <div style={{ padding: 16, borderBottom: "1px solid " + PTE_C.z200, display: "flex", gap: 10 }}>
            <button onClick={() => setPanel("upload")} style={{ flex: 1, padding: 10, border: "1px solid " + PTE_C.z300, borderRadius: 6, background: "#fff", fontSize: 12.5, fontWeight: 600, fontFamily: "inherit", cursor: "pointer", color: PTE_C.ink }}>Upload image</button>
            <button onClick={doAddText} style={{ flex: 1, padding: 10, border: "1px solid " + PTE_C.z300, borderRadius: 6, background: "#fff", fontSize: 12.5, fontWeight: 600, fontFamily: "inherit", cursor: "pointer", color: PTE_C.ink }}>Add text</button>
          </div>

          <div style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
            <div style={{ padding: "16px 16px 8px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
              <span style={sectionLabel}>Layers</span>
              <span style={{ fontSize: 11, color: PTE_C.z400 }}>{layers.length === 1 ? "1 layer" : layers.length + " layers"}</span>
            </div>
            <div style={{ padding: "0 16px 8px", display: "flex", flexDirection: "column", gap: 8 }}>
              {layers.slice().reverse().map((l) => {
                const isSel = l.id === selectedId;
                return (
                  <div key={l.id} onClick={() => setSelectedId(l.id)} style={{ display: "flex", alignItems: "center", gap: 9, padding: "9px 10px", border: "1px solid " + (isSel ? PTE_C.red : PTE_C.z200), background: isSel ? "#fdf3f2" : "#fff", borderRadius: 8, cursor: "pointer" }}>
                    <span onPointerDown={(e) => startGrip(e, l)} title="Drag to reorder" style={{ display: "flex", flexDirection: "column", gap: 2, padding: "2px 3px", cursor: "grab", flexShrink: 0 }}>
                      {[0, 1, 2].map((r) => <span key={r} style={{ display: "flex", gap: 2 }}><span style={{ width: 3, height: 3, borderRadius: 999, background: PTE_C.z300 }} /><span style={{ width: 3, height: 3, borderRadius: 999, background: PTE_C.z300 }} /></span>)}
                    </span>
                    <span style={{ width: 34, height: 34, borderRadius: 5, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", background: cw.dark ? PTE_C.z800 : PTE_C.z100, color: l.color, fontSize: 9, fontWeight: 800, letterSpacing: ".5px", border: "1px solid " + PTE_C.z200, fontFamily: "Archivo, sans-serif", overflow: "hidden" }}>{l.type === "art" ? l.mark : "T"}</span>
                    <span style={{ display: "flex", flexDirection: "column", gap: 2, minWidth: 0, flex: 1 }}>
                      <span style={{ fontSize: 12.5, fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{l.name}</span>
                      <span style={{ fontSize: 11, color: PTE_C.z500, whiteSpace: "nowrap" }}>{l.type === "art" ? "Artwork" : "Text · " + (IE_FONTS.find((f) => f.id === l.font) || IE_FONTS[0]).label} · {ieZone(l)} {ieInches(l.w)}</span>
                    </span>
                    <span style={{ display: "flex", gap: 2, flexShrink: 0 }}>
                      <button title="Duplicate" onClick={(e) => { e.stopPropagation(); const clone = { ...l, id: "l" + Date.now(), x: clamp(l.x + 4, 3, 97), y: clamp(l.y + 4, 3, 97) }; setLayers([...layers, clone], clone.id); }} style={{ width: 26, height: 26, borderRadius: 5, border: 0, background: "none", color: PTE_C.z600, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>⧉</button>
                      <button title="Delete" onClick={(e) => { e.stopPropagation(); setLayers(layers.filter((x) => x.id !== l.id), null); }} style={{ width: 26, height: 26, borderRadius: 5, border: 0, background: "none", color: PTE_C.z600, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>✕</button>
                    </span>
                  </div>
                );
              })}
              {!layers.length && (
                <div style={{ padding: "22px 16px", border: "1px dashed " + PTE_C.z300, borderRadius: 8, textAlign: "center" }}>
                  <div style={{ fontSize: 12.5, color: PTE_C.z600, marginBottom: 4 }}>No artwork on this image</div>
                  <div style={{ fontSize: 11.5, color: PTE_C.z400, lineHeight: 1.5 }}>Upload a mark, add text, or paste from another variant.</div>
                </div>
              )}
            </div>

            {sel && (
              <div style={{ margin: "12px 16px 16px", border: "1px solid " + PTE_C.z200, borderRadius: 10, overflow: "hidden" }}>
                <div style={{ padding: "11px 14px", background: PTE_C.z50, borderBottom: "1px solid " + PTE_C.z200 }}>
                  <span style={sectionLabel}>{sel.type === "art" ? "Artwork properties" : "Text properties"}</span>
                </div>
                <div style={{ padding: 14 }}>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 8 }}>
                    <div>
                      <div style={{ fontSize: 11, color: PTE_C.z500, marginBottom: 5 }}>Position</div>
                      <div style={{ padding: "8px 10px", border: "1px solid " + PTE_C.z200, borderRadius: 6, fontSize: 12, fontFamily: "'JetBrains Mono', ui-monospace, monospace" }}>{Math.round(sel.x)}% · {Math.round(sel.y)}%</div>
                    </div>
                    <div>
                      <div style={{ fontSize: 11, color: PTE_C.z500, marginBottom: 5 }}>Size</div>
                      <div style={{ padding: "8px 10px", border: "1px solid " + PTE_C.z200, borderRadius: 6, fontSize: 12, fontFamily: "'JetBrains Mono', ui-monospace, monospace" }}>{Math.round(sel.w)}% wide</div>
                    </div>
                  </div>
                  <div style={{ fontSize: 11.5, color: PTE_C.z500, marginBottom: 14 }}>Reads as <strong style={{ color: PTE_C.ink, fontWeight: 600 }}>{ieZone(sel)} · {ieInches(sel.w)}</strong> on the imprint record</div>

                  {sel.type === "text" && (
                    <div style={{ marginBottom: 14 }}>
                      <div style={{ fontSize: 11, color: PTE_C.z500, marginBottom: 5 }}>Text</div>
                      <input value={sel.text} onChange={(e) => { const v = e.target.value; setLayersBy((cur) => ({ ...cur, [active]: (cur[active] || []).map((l) => l.id === sel.id ? { ...l, text: v, name: v || "Text" } : l) })); setSaved(false); }}
                        style={{ width: "100%", boxSizing: "border-box", padding: "9px 11px", border: "1px solid " + PTE_C.z300, borderRadius: 6, fontSize: 13, fontFamily: "inherit", outline: "none" }} />
                      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
                        {IE_FONTS.map((f) => (
                          <button key={f.id} onClick={() => patchSel({ font: f.id })} style={{ padding: "7px 12px", borderRadius: 6, fontSize: 12, cursor: "pointer", fontFamily: f.stack, border: "1px solid " + (sel.font === f.id ? PTE_C.ink : PTE_C.z200), background: sel.font === f.id ? PTE_C.ink : "#fff", color: sel.font === f.id ? "#fff" : PTE_C.z700 }}>{f.label}</button>
                        ))}
                      </div>
                    </div>
                  )}

                  {sel.type === "art" && (
                    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, padding: "2px 0 14px", borderBottom: "1px solid " + PTE_C.z100, marginBottom: 14 }}>
                      <span style={{ fontSize: 12.5, color: PTE_C.z700 }}>Remove white background</span>
                      <span onClick={() => patchSel({ removeWhite: !sel.removeWhite })} style={{ width: 38, height: 22, borderRadius: 999, position: "relative", flexShrink: 0, cursor: "pointer", background: sel.removeWhite ? PTE_C.ink : PTE_C.z300 }}>
                        <span style={{ position: "absolute", top: 2, left: sel.removeWhite ? 18 : 2, width: 18, height: 18, borderRadius: 999, background: "#fff", transition: "left .14s cubic-bezier(.2,0,0,1)" }} />
                      </span>
                    </div>
                  )}

                  <div style={{ fontSize: 11, color: PTE_C.z500, marginBottom: 8 }}>Recolor</div>
                  <div style={{ display: "flex", gap: 8 }}>
                    {swatches.map((c) => <button key={c} onClick={() => patchSel({ color: c })} title={c} style={swatchStyle(c, true)} />)}
                  </div>
                </div>
              </div>
            )}
          </div>

          <div style={{ flexShrink: 0, borderTop: "1px solid " + PTE_C.z200, padding: "14px 16px" }}>
            <div style={{ marginBottom: 8 }}><span style={sectionLabel}>Image caption</span></div>
            <div style={{ padding: "9px 11px", border: "1px solid " + PTE_C.z200, borderRadius: 6, fontSize: 12.5, color: PTE_C.z600, background: PTE_C.z50, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.title} — {cw.name} ({view.name.toLowerCase()})</div>
          </div>
        </div>
      </div>

      {panel === "upload" && (
        <div onClick={() => setPanel(null)} style={{ position: "fixed", inset: 0, background: "rgba(9,9,11,.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 40, padding: 24 }}>
          <div onClick={(e) => e.stopPropagation()} style={{ width: 620, maxWidth: "100%", background: "#fff", borderRadius: 12, boxShadow: "0 24px 48px rgba(9,9,11,.18)", overflow: "hidden" }}>
            <div style={{ padding: "18px 22px", borderBottom: "1px solid " + PTE_C.z200, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <span style={{ fontSize: 16, fontWeight: 700, fontFamily: "Archivo, sans-serif" }}>Upload image</span>
              <button onClick={() => setPanel(null)} style={{ border: 0, background: "none", color: PTE_C.z500, fontSize: 15, cursor: "pointer", fontFamily: "inherit" }}>✕</button>
            </div>
            <div style={{ padding: 22 }}>
              <div style={{ border: "1.5px dashed " + PTE_C.z300, borderRadius: 10, padding: 30, textAlign: "center", background: PTE_C.z50, marginBottom: 22 }}>
                <div style={{ fontSize: 14.5, fontWeight: 600, marginBottom: 6 }}>Drag and drop artwork here</div>
                <div style={{ fontSize: 12.5, color: PTE_C.z500 }}>or click to browse · .gif, .jpg, .png, .svg</div>
              </div>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
                <span style={sectionLabel}>Team artwork library</span>
                <span style={{ fontSize: 11, color: PTE_C.z400 }}>Lives on the team — persists across seasons</span>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(3,minmax(0,1fr))", gap: 12, marginBottom: 24 }}>
                {library.map((a) => (
                  <div key={a.id} onClick={() => setPick(a.id)} style={{ padding: 10, borderRadius: 8, cursor: "pointer", border: "1px solid " + (pick === a.id ? PTE_C.ink : PTE_C.z200), background: pick === a.id ? PTE_C.z50 : "#fff" }}>
                    <span style={{ display: "flex", alignItems: "center", justifyContent: "center", height: 64, marginBottom: 8, borderRadius: 6, background: PTE_C.z100, fontFamily: "Archivo, sans-serif", fontWeight: 800, fontSize: 15, letterSpacing: "1px", color: PTE_C.z700, overflow: "hidden" }}>{a.mark}</span>
                    <span style={{ display: "block", fontSize: 12, fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{a.name}</span>
                    <span style={{ fontSize: 11, color: PTE_C.z500 }}>{a.meta}</span>
                  </div>
                ))}
              </div>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
                <button onClick={() => setPick(null)} style={{ border: 0, background: "none", fontSize: 12.5, color: PTE_C.redInk, cursor: "pointer", fontFamily: "inherit", padding: 0 }}>{pick ? "Remove " + (library.find((a) => a.id === pick) || {}).name : "Nothing selected"}</button>
                <button onClick={doInsert} style={{ background: PTE_C.ink, color: "#fff", border: 0, borderRadius: 6, padding: "10px 20px", fontSize: 12.5, fontWeight: 700, fontFamily: "inherit", cursor: "pointer" }}>Insert image</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {toast && <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", background: PTE_C.ink, color: "#fff", padding: "12px 20px", borderRadius: 8, fontSize: 12.5, boxShadow: "0 12px 32px rgba(9,9,11,.25)", zIndex: 50 }}>{toast}</div>}
    </div>
  );
}

