function RptTh({ children, right, style }) { return <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".07em", color: RPT.faint, textTransform: "uppercase", textAlign: right ? "right" : "left", ...style }}>{children}</span>; }
