function RptCard({ children, style, dark }) { return <div style={{ background: dark ? "#0e0e10" : "#fff", color: dark ? "#fff" : RPT.ink, border: dark ? 0 : "1px solid " + RPT.line, borderRadius: 12, padding: "20px 24px", ...style }}>{children}</div>; }
