  const selIds = Object.keys(sel).filter((k) => sel[k]); const selPlayers = data.players.filter((p) => selIds.includes(p.id));
  const reachable = selPlayers.filter(canReach); const unreachable = selPlayers.filter((p) => !canReach(p));
